window.AP_DATA=[{"id": "tr", "name": "Trigonometrie", "short": "10.1", "tasks": [{"id": "tr18htA2", "year": 2018, "term": "Haupttermin", "nr": "A 2", "notr": false, "pts": "6", "stmt": ["n_2018ht_A2_0", "n_2018ht_A2_1"], "note": "Teilaufgaben A 2.1 und A 2.2", "subs": [{"label": "A 2.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "Das Dreieck ABD ist bei A rechtwinklig. Pythagoras für die Diagonale:", "m": "\\begin{aligned}\\s{BD} &= \\sqrt{7{,}8^2+5{,}2^2}\\cm = \\erg{9{,}4\\cm}\\end{aligned}"}, {"t": "Für die Fläche von BCD brauchst du den Winkel bei B. Zuerst ∢DBA mit dem Tangens:", "m": "\\begin{aligned}\\tan\\w DBA &= \\dfrac{5{,}2}{7{,}8}\\\\[2pt]&\\Rightarrow\\;\\w DBA = 33{,}7^\\circ\\\\[3pt]\\w CBD &= 70^\\circ-33{,}7^\\circ = 36{,}3^\\circ\\end{aligned}"}, {"t": "Sinus-Flächenformel mit \\(\\overline{BD}\\), \\(\\overline{BC}\\) und dem eingeschlossenen Winkel:", "m": "\\begin{aligned}A_{BCD} &= 0{,}5\\cdot 9{,}4\\cdot 8{,}6\\cdot\\sin 36{,}3^\\circ\\cmq = \\erg{23{,}9\\cmq}\\end{aligned}"}], "solimg": "ns_2018ht_A2_A21", "solcap": "Zeichnung aus dem Lösungsmuster (der Kreisbogen gehört zu A 2.3)"}, {"label": "A 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Dreieck ABE soll ebenfalls 23,9 cm² haben. Mit \\(\\overline{AB}\\), \\(\\overline{BE}\\) und ∢CBA = 70°:", "m": "\\begin{aligned}23{,}9\\cmq &= 0{,}5\\cdot 7{,}8\\cm\\cdot\\s{BE}\\cdot\\sin 70^\\circ\\\\[3pt]\\s{BE} &= 6{,}5\\cm\\end{aligned}"}, {"t": "[AE] liegt gegenüber vom Winkel bei B. Kosinussatz:", "m": "\\begin{aligned}\\s{AE} &= \\sqrt{7{,}8^2+6{,}5^2-2\\cdot 7{,}8\\cdot 6{,}5\\cdot\\cos 70^\\circ}\\cm = \\erg{8{,}3\\cm}\\end{aligned}"}]}]}, {"id": "tr18ntA2", "year": 2018, "term": "Nachtermin", "nr": "A 2", "notr": false, "pts": "4", "stmt": ["n_2018nt_A2_0"], "note": "Teilaufgaben A 2.1 und A 2.2", "subs": [{"label": "A 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Dreieck ABC ist bei B rechtwinklig. Pythagoras:", "m": "\\begin{aligned}\\s{AC} &= \\sqrt{7^2+6^2}\\cm = \\erg{9{,}22\\cm}\\end{aligned}"}, {"t": "∢BCA ergänzt φ zu 90° (∢DCB = 90°). Im Dreieck ABC ist [AB] Gegenkathete und [BC] Ankathete von ∢BCA.", "m": "\\begin{aligned}\\tan(90^\\circ-\\varphi) &= \\dfrac{7}{6}\\\\[3pt]90^\\circ-\\varphi &= 49{,}40^\\circ\\\\[3pt]\\varphi &= \\erg{40{,}60^\\circ}\\end{aligned}"}], "solimg": "ns_2018nt_A2_A21", "solcap": "Zeichnung aus dem Lösungsmuster (Kreisbogen und S gehören zu A 2.3)"}, {"label": "A 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Weil AB ∥ CD, gilt der Vierstreckensatz mit Zentrum M für die Dreiecke AFM und CEM. Mit \\(\\overline{EC}=(10-3)\\) cm und \\(\\overline{AF}=3\\) cm verhält sich \\(\\overline{MC}\\) zur ganzen Diagonale wie 7 zu 10.", "m": "\\begin{aligned}\\dfrac{\\s{MC}}{9{,}22\\cm} &= \\dfrac{(10-3)\\cm}{10\\cm}\\\\[3pt]\\s{MC} &= \\erg{6{,}45\\cm}\\end{aligned}"}]}]}, {"id": "tr19htA1", "year": 2019, "term": "Haupttermin", "nr": "A 1", "notr": false, "pts": "5", "stmt": ["n_2019ht_A1_0"], "note": null, "subs": [{"label": "A 1.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im Dreieck ABC sind alle drei Seiten bekannt. ∢ACB liegt gegenüber von [AB]. Kosinussatz:", "m": "\\begin{aligned}\\s{AB}^2 &= \\s{AC}^2+\\s{BC}^2-2\\cdot\\s{AC}\\cdot\\s{BC}\\cdot\\cos\\w ACB\\\\[3pt]95^2 &= 150^2+75^2-2\\cdot 150\\cdot 75\\cdot\\cos\\w ACB\\\\[3pt]\\cos\\w ACB &= \\dfrac{150^2+75^2-95^2}{2\\cdot 150\\cdot 75}\\\\[2pt]&\\Rightarrow\\;\\w ACB = \\erg{32^\\circ}\\end{aligned}"}]}, {"label": "A 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Die Diagonalen stehen senkrecht. Im rechtwinkligen Dreieck MBC ist \\(\\overline{MB}=0{,}5\\cdot\\overline{BD}\\) die Gegenkathete von ∢ACB.", "m": "\\begin{aligned}\\sin 32^\\circ &= \\dfrac{0{,}5\\cdot\\s{BD}}{75\\cm}\\\\[3pt]\\s{BD} &= \\erg{79\\cm}\\end{aligned}"}, {"t": "Drachenfläche = halbes Produkt der Diagonalen:", "m": "\\begin{aligned}A &= 0{,}5\\cdot 150\\cdot 79\\cmq = \\erg{5925\\cmq}\\end{aligned}"}]}, {"label": "A 1.3", "pts": "1", "text": "", "img": null, "sol": [{"t": "Die Fläche ist proportional zu \\(\\overline{AC}\\), weil \\(\\overline{BD}\\) gleich bleibt. 150 cm → 100 cm ist ein Drittel weniger.", "m": "\\begin{aligned}\\dfrac{150-100}{150} &= \\dfrac13 \\approx \\erg{33\\,\\%}\\end{aligned}"}]}]}, {"id": "tr19htB1", "year": 2019, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "10", "stmt": ["n_2019ht_B1_0"], "note": "Teilaufgaben B 1.1, B 1.2 und B 1.3", "subs": [{"label": "B 1.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "Im Dreieck ABC sind alle Seiten bekannt. β liegt gegenüber von [AC]. Kosinussatz:", "m": "\\begin{aligned}14^2 &= 7^2+10^2-2\\cdot 7\\cdot 10\\cdot\\cos\\beta\\\\[3pt]\\beta &= \\erg{109{,}62^\\circ}\\end{aligned}"}, {"t": "Sinussatz: ε liegt gegenüber von [BC] = 10 cm, β gegenüber von [AC] = 14 cm.", "m": "\\begin{aligned}\\dfrac{\\sin\\varepsilon}{10} &= \\dfrac{\\sin 109{,}62^\\circ}{14}\\\\[3pt]\\varepsilon &= \\erg{42{,}28^\\circ}\\end{aligned}"}], "solimg": "ns_2019ht_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster (der Kreis gehört zu B 1.4)"}, {"label": "B 1.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "[BP] steht senkrecht auf [AC]. Im rechtwinkligen Dreieck ABP ist [AB] die Hypotenuse.", "m": "\\begin{aligned}\\s{BP} &= 7\\cm\\cdot\\sin 42{,}28^\\circ = 4{,}71\\cm\\\\[3pt]\\s{AP} &= 7\\cm\\cdot\\cos 42{,}28^\\circ = 5{,}18\\cm\\end{aligned}"}, {"t": "Umfang:", "m": "\\begin{aligned}u &= (7+4{,}71+5{,}18)\\cm = \\erg{16{,}89\\cm}\\end{aligned}"}]}, {"label": "B 1.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Trapezfläche \\(A=\\frac{\\overline{AB}+\\overline{CD}}{2}\\cdot h\\). Die Höhe h steckt im Dreieck an der Seite [BC]: Der Winkel zwischen [BC] und der Höhe ist β − 90°.", "m": "\\begin{aligned}\\cos(109{,}62^\\circ-90^\\circ) &= \\dfrac{h}{10\\cm}\\\\[3pt]h &= 9{,}42\\cm\\end{aligned}"}, {"t": "[CD] im Dreieck ACD mit dem Sinussatz. Zuerst den Winkel bei D (∢DCA = ε, Wechselwinkel):", "m": "\\begin{aligned}\\w ADC &= 180^\\circ-(42{,}28^\\circ+50^\\circ) = 87{,}72^\\circ\\\\[3pt]\\s{CD} &= \\dfrac{14\\cm\\cdot\\sin 50^\\circ}{\\sin 87{,}72^\\circ} = 10{,}73\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}A &= \\dfrac{7+10{,}73}{2}\\cdot 9{,}42\\cmq = \\erg{83{,}51\\cmq}\\end{aligned}"}]}]}, {"id": "tr19ntA1", "year": 2019, "term": "Nachtermin", "nr": "A 1", "notr": false, "pts": "3", "stmt": ["n_2019nt_A1_0"], "note": "Teilaufgaben A 1.1", "subs": [{"label": "A 1.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Im Viereck ABCD ist die Winkelsumme 360°. Zwei Winkel sind rechte Winkel:", "m": "\\begin{aligned}\\w CBA &= 360^\\circ-90^\\circ-90^\\circ-115^\\circ = 65^\\circ\\end{aligned}"}, {"t": "Zeichne die Höhe h von C auf [AB]. Im entstehenden rechtwinkligen Dreieck ist h die Gegenkathete und \\(\\overline{AB}-\\overline{CD}\\) die Ankathete von ∢CBA:", "m": "\\begin{aligned}\\tan 65^\\circ &= \\dfrac{h}{(8{,}7-5{,}2)\\cm}\\\\[3pt]h &= 3{,}5\\cdot\\tan 65^\\circ\\cm = 7{,}5\\cm\\end{aligned}"}, {"t": "Flächeninhalt des Trapezes:", "m": "\\begin{aligned}A &= 0{,}5\\cdot(\\s{AB}+\\s{CD})\\cdot h\\\\[3pt]A &= 0{,}5\\cdot(8{,}7+5{,}2)\\cdot 7{,}5\\cmq = \\erg{52{,}1\\cmq}\\end{aligned}"}]}]}, {"id": "tr19ntB2", "year": 2019, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "9", "stmt": ["n_2019nt_B2_0"], "note": "Teilaufgaben B 2.1, B 2.2 und B 2.3", "subs": [{"label": "B 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "In der Raute stehen die Diagonalen senkrecht. Dreieck BCM ist rechtwinklig mit Hypotenuse [BC]:", "m": "\\begin{aligned}\\s{CM} &= \\sqrt{6^2-3^2}\\cm = \\erg{5{,}20\\cm}\\end{aligned}"}, {"t": "\\(\\overline{BD}=2\\cdot3=6\\) cm = Seitenlänge. Die Dreiecke ABD und BCD sind daher gleichseitig:", "m": "\\begin{aligned}\\beta &= 2\\cdot 60^\\circ = \\erg{120^\\circ}\\end{aligned}"}]}, {"label": "B 2.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Raute ABCD zeichnen, Kreisbögen um B und D mit Radius 6 cm, [OP] parallel zu DB, Trapez OPQR ergänzen.", "m": null}], "solimg": "ns_2019nt_B2_B22", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 2.3", "pts": "4", "text": "", "img": null, "sol": [{"t": "Länge von [OP]:", "m": "\\begin{aligned}\\s{OP} &= 0{,}6\\cdot 5{,}2\\cm = 3{,}12\\cm\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum M (OP ∥ RQ):", "m": "\\begin{aligned}\\dfrac{\\s{MG}}{6{,}5\\cm} &= \\dfrac{3{,}12\\cm}{5{,}2\\cm}\\\\[3pt]\\s{MG} &= \\erg{3{,}90\\cm}\\end{aligned}"}, {"t": "Pythagoras im rechtwinkligen Dreieck MHR:", "m": "\\begin{aligned}\\s{MR} &= \\sqrt{6{,}5^2+(0{,}5\\cdot5{,}2)^2}\\cm = 7{,}00\\cm\\end{aligned}"}, {"t": "Nochmals Vierstreckensatz, dann Differenz:", "m": "\\begin{aligned}\\dfrac{\\s{MO}}{7{,}00\\cm} &= \\dfrac{3{,}90\\cm}{6{,}5\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{MO} = 4{,}20\\cm\\\\[3pt]\\s{OR} &= (7{,}00-4{,}20)\\cm = \\erg{2{,}80\\cm}\\end{aligned}"}]}]}, {"id": "tr20htA3", "year": 2020, "term": "Haupttermin", "nr": "A 3", "notr": false, "pts": "5", "stmt": ["n_2020ht_A3_0"], "note": null, "subs": [{"label": "A 3.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(\\overline{BE}=\\overline{BC}-\\overline{EC}\\). Vierstreckensatz mit Zentrum C (DE ∥ AB):", "m": "\\begin{aligned}\\dfrac{\\s{EC}}{5\\cm} &= \\dfrac{3{,}6\\cm}{7\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{EC} = 2{,}57\\cm\\\\[3pt]\\s{BE} &= (5-2{,}57)\\cm = \\erg{2{,}43\\cm}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Zuerst ∢BAC mit dem Sinussatz im Dreieck ABC:", "m": "\\begin{aligned}\\dfrac{\\sin\\w BAC}{5\\cm} &= \\dfrac{\\sin 40^\\circ}{7\\cm}\\\\[2pt]&\\Rightarrow\\;\\w BAC = 27{,}33^\\circ\\end{aligned}"}, {"t": "Winkelsumme im Dreieck:", "m": "\\begin{aligned}\\w CBA &= 180^\\circ-40^\\circ-27{,}33^\\circ = 112{,}67^\\circ\\end{aligned}"}, {"t": "Der stumpfe Winkel bei B: Im rechtwinkligen Dreieck aus d, [BE] und dem Lot ist \\(\\w CBA-90°\\) der Winkel an B, d die Ankathete:", "m": "\\begin{aligned}\\cos(112{,}67^\\circ-90^\\circ) &= \\dfrac{d}{2{,}43\\cm}\\\\[3pt]d &= \\erg{2{,}24\\cm}\\end{aligned}"}]}]}, {"id": "tr20htB2", "year": 2020, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "9", "stmt": ["n_2020ht_B2_0"], "note": "Teilaufgaben B 2.1, B 2.2 und B 2.3", "subs": [{"label": "B 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "[AB] = 11 cm zeichnen, ∢BAD = 45° antragen, \\(\\overline{AD}\\) = 11 cm. Senkrechte in B und D schneiden sich in C. E liegt senkrecht über A auf der Parallelen zu AB durch D.", "m": null}], "solimg": "ns_2020ht_B2_B21", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Elemente späterer Teilaufgaben)"}, {"label": "B 2.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Wechselwinkel an Parallelen und rechter Winkel im Drachenviereck:", "m": "\\begin{aligned}\\w EDA &= \\w BAD = 45^\\circ\\quad(\\text{Wechselwinkel, da}\\ [AB]\\parallel[ED])\\\\[3pt]\\w EDC &= \\w EDA+\\w ADC = 45^\\circ+90^\\circ = \\erg{135^\\circ}\\end{aligned}"}, {"t": "Wegen ∢DAE = 90° − 45° = 45° = ∢EDA ist das Dreieck ADE gleichschenklig-rechtwinklig, also \\(\\overline{AE}=\\overline{ED}\\). Länge:", "m": "\\begin{aligned}\\sin 45^\\circ &= \\dfrac{\\s{ED}}{11\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{ED} = \\erg{7{,}78\\cm}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "4", "text": "", "img": null, "sol": [{"t": "AC halbiert ∢BAD. Im rechtwinkligen Dreieck ABC:", "m": "\\begin{aligned}\\tan(0{,}5\\cdot 45^\\circ) &= \\dfrac{\\s{BC}}{11\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{BC} = \\erg{4{,}56\\cm}\\end{aligned}"}, {"t": "Drachenviereck = 2 kongruente rechtwinklige Dreiecke; Fünfeck = Drachen + Dreieck ADE:", "m": "\\begin{aligned}A_{ABCD} &= 2\\cdot0{,}5\\cdot 11\\cdot 4{,}56\\cmq = 50{,}16\\cmq\\\\[3pt]A_{ABCDE} &= (50{,}16+0{,}5\\cdot7{,}78\\cdot7{,}78)\\cmq = 80{,}42\\cmq\\\\[3pt]\\dfrac{50{,}16}{80{,}42} &\\approx \\erg{62{,}37\\,\\%}\\end{aligned}"}]}]}, {"id": "tr20ntA1", "year": 2020, "term": "Nachtermin", "nr": "A 1", "notr": false, "pts": "5", "stmt": ["n_2020nt_A1_0"], "note": null, "subs": [{"label": "A 1.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck ABC ist [AB] die Ankathete von ∢BAC, [AC] die Hypotenuse:", "m": "\\begin{aligned}\\cos 34^\\circ &= \\dfrac{9\\cm}{\\s{AC}}\\\\[2pt]&\\Rightarrow\\;\\s{AC} = \\erg{10{,}86\\cm}\\end{aligned}"}, {"t": "Im Dreieck \\(AP_1M\\) fehlen noch Winkel. Nebenwinkel und Winkelsumme:", "m": "\\begin{aligned}\\w P_1MA &= 180^\\circ-70^\\circ = 110^\\circ\\\\[3pt]\\w AP_1M &= 180^\\circ-34^\\circ-110^\\circ = 36^\\circ\\end{aligned}"}, {"t": "Sinussatz im Dreieck \\(AP_1M\\) mit \\(\\overline{AM}=0{,}5\\cdot 9\\) cm:", "m": "\\begin{aligned}\\dfrac{\\s{AP_1}}{\\sin 110^\\circ} &= \\dfrac{0{,}5\\cdot 9\\cm}{\\sin 36^\\circ}\\\\[3pt]\\s{AP_1} &= \\erg{7{,}19\\cm}\\end{aligned}"}]}, {"label": "A 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Viereck \\(MBCP_n\\) hat die Innenwinkelsumme 360°. Zuerst ∢ACB im Dreieck ABC:", "m": "\\begin{aligned}\\w ACB &= 180^\\circ-90^\\circ-34^\\circ = 56^\\circ\\end{aligned}"}, {"t": "Damit:", "m": "\\begin{aligned}\\w BMP_n+\\w MP_nC+56^\\circ+90^\\circ &= 360^\\circ\\\\[3pt]\\w BMP_n+\\w MP_nC &= \\erg{214^\\circ}\\end{aligned}"}]}]}, {"id": "tr20ntB1", "year": 2020, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "10", "stmt": ["n_2020nt_B1_0"], "note": "Teilaufgaben B 1.1, B 1.2, B 1.3 und B 1.6 (Kreisteile weggelassen)", "subs": [{"label": "B 1.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "Zeichne [AB] = 10 cm, ∢BAD = 100°, \\(\\overline{AD}\\) = 8 cm, Parallele zu AB durch D; C liegt darauf mit \\(\\overline{AC}\\) = 10 cm.", "m": null}, {"t": "Kosinussatz im Dreieck ABD:", "m": "\\begin{aligned}\\s{BD} &= \\sqrt{10^2+8^2-2\\cdot10\\cdot8\\cdot\\cos 100^\\circ}\\cm = \\erg{13{,}85\\cm}\\end{aligned}"}, {"t": "Sinussatz im Dreieck ABD:", "m": "\\begin{aligned}\\dfrac{\\sin\\w DBA}{8\\cm} &= \\dfrac{\\sin 100^\\circ}{13{,}85\\cm}\\\\[2pt]&\\Rightarrow\\;\\w DBA = \\erg{34{,}67^\\circ}\\end{aligned}"}], "solimg": "ns_2020nt_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Elemente der weggelassenen Teilaufgaben)"}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Wegen AB ∥ CD ist ∢ADC = 180° − 100° = 80°. Sinussatz im Dreieck ACD:", "m": "\\begin{aligned}\\dfrac{\\sin\\w DCA}{8\\cm} &= \\dfrac{\\sin(180^\\circ-100^\\circ)}{10\\cm}\\\\[2pt]&\\Rightarrow\\;\\w DCA = \\erg{51{,}98^\\circ}\\end{aligned}"}, {"t": "∢BAC und ∢DCA sind Wechselwinkel an den parallelen Geraden AB und CD, also gilt ∢BAC = ∢DCA = 51,98°.", "m": null}]}, {"label": "B 1.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Viereck in die Dreiecke ABC und ACD zerlegen und jeweils die Sinus-Flächenformel verwenden:", "m": "\\begin{aligned}\\w CAD &= 100^\\circ-51{,}98^\\circ = 48{,}02^\\circ\\\\[3pt]A_{ABCD} &= 0{,}5\\cdot\\s{AB}\\cdot\\s{AC}\\cdot\\sin\\w BAC+0{,}5\\cdot\\s{AC}\\cdot\\s{AD}\\cdot\\sin\\w CAD\\\\[3pt]A_{ABCD} &= (0{,}5\\cdot10\\cdot10\\cdot\\sin 51{,}98^\\circ+0{,}5\\cdot10\\cdot8\\cdot\\sin 48{,}02^\\circ)\\cmq\\\\[3pt]A_{ABCD} &= \\erg{69{,}12\\cmq}\\end{aligned}"}]}, {"label": "B 1.6", "pts": "2", "text": "", "img": null, "sol": [{"t": "G ist der Schnittpunkt der Diagonalen. ∢CGD ist Scheitelwinkel von ∢AGB; Winkelsumme im Dreieck ABG:", "m": "\\begin{aligned}\\w CGD &= 180^\\circ-51{,}98^\\circ-34{,}67^\\circ = \\erg{93{,}35^\\circ}\\end{aligned}"}, {"t": "Der Abstand d(D;[AC]) ist die Länge des Lots von D auf AC. Wegen ∢CGD ≠ 90° ist [DG] nicht das Lot, sondern länger: \\(\\overline{DG}>d(D;[AC])\\).", "m": null}]}]}, {"id": "tr21htB1", "year": 2021, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "14", "stmt": ["n_2021ht_B1_0"], "note": "Teilaufgaben B 1.1, B 1.2, B 1.3 und B 1.4", "subs": [{"label": "B 1.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "Zeichne das Fünfeck: rechter Winkel bei A, ∢AED = 128°; C mit \\(\\overline{CE}\\) = 11 cm und \\(\\overline{CD}\\) = 9 cm (Zirkel).", "m": null}, {"t": "Rechtwinkliges Dreieck ABE:", "m": "\\begin{aligned}\\s{BE} &= \\sqrt{7^2+8^2}\\cm = \\erg{10{,}63\\cm}\\\\[3pt]\\tan\\w AEB &= \\dfrac78\\\\[2pt]&\\Rightarrow\\;\\w AEB = \\erg{41{,}19^\\circ}\\end{aligned}"}], "solimg": "ns_2021ht_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Elemente aus B 1.5)"}, {"label": "B 1.2", "pts": "4", "text": "", "img": null, "sol": [{"t": "Viereck ABCE = Dreieck ABE + Dreieck BCE. Für das zweite Dreieck brauchst du ∢BEC = ∢AED − ∢AEB − ∢CED.", "m": null}, {"t": "∢CED mit dem Kosinussatz im Dreieck CDE:", "m": "\\begin{aligned}9^2 &= 11^2+4^2-2\\cdot11\\cdot4\\cdot\\cos\\w CED\\\\[2pt]&\\Rightarrow\\;\\w CED = 50{,}48^\\circ\\\\[3pt]\\w BEC &= 128^\\circ-41{,}19^\\circ-50{,}48^\\circ = 36{,}33^\\circ\\end{aligned}"}, {"t": "Flächeninhalt:", "m": "\\begin{aligned}A_{ABCE} &= 0{,}5\\cdot\\s{AB}\\cdot\\s{AE}+0{,}5\\cdot\\s{BE}\\cdot\\s{CE}\\cdot\\sin\\w BEC\\\\[3pt]A_{ABCE} &= (0{,}5\\cdot7\\cdot8+0{,}5\\cdot10{,}63\\cdot11\\cdot\\sin 36{,}33^\\circ)\\cmq = \\erg{62{,}64\\cmq}\\end{aligned}"}]}, {"label": "B 1.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Kosinussatz und Sinussatz im Dreieck BCE:", "m": "\\begin{aligned}\\s{BC} &= \\sqrt{10{,}63^2+11^2-2\\cdot10{,}63\\cdot11\\cdot\\cos 36{,}33^\\circ}\\cm = \\erg{6{,}75\\cm}\\\\[3pt]\\dfrac{\\sin\\w ECB}{10{,}63} &= \\dfrac{\\sin 36{,}33^\\circ}{6{,}75}\\\\[2pt]&\\Rightarrow\\;\\w ECB = \\erg{68{,}90^\\circ}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "BCFG ist ein Trapez (FG ∥ BC): \\(A=0{,}5\\cdot(\\overline{BC}+\\overline{FG})\\cdot d(F;BC)\\). Vierstreckensatz mit Zentrum E:", "m": "\\begin{aligned}\\dfrac{\\s{FG}}{6{,}75\\cm} &= \\dfrac{(11-3)\\cm}{11\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{FG} = 4{,}91\\cm\\end{aligned}"}, {"t": "Trapezhöhe im rechtwinkligen Dreieck an F:", "m": "\\begin{aligned}\\sin 68{,}90^\\circ &= \\dfrac{d(F;BC)}{3\\cm}\\\\[2pt]&\\Rightarrow\\;d(F;BC) = 2{,}80\\cm\\end{aligned}"}, {"t": "Flächeninhalt:", "m": "\\begin{aligned}A_{BCFG} &= 0{,}5\\cdot(6{,}75+4{,}91)\\cdot2{,}80\\cmq = \\erg{16{,}32\\cmq}\\end{aligned}"}]}]}, {"id": "tr21ntA1", "year": 2021, "term": "Nachtermin", "nr": "A 1", "notr": false, "pts": "4", "stmt": ["n_2021nt_A1_0"], "note": "Kein Lösungsmuster vorhanden – Lösung selbst erstellt", "subs": [{"label": "A 1", "pts": "4", "text": "", "img": null, "sol": [{"t": "M ist der Diagonalenschnittpunkt, also hat M den Abstand \\(0{,}5\\cdot 11 = 5{,}5\\) cm von CD. Die Höhe h des Dreiecks MFE (von M auf EF):", "m": "\\begin{aligned}h &= (5{,}5-2)\\cm = 3{,}5\\cm\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum M (EF ∥ CD):", "m": "\\begin{aligned}\\dfrac{\\s{EF}}{6\\cm} &= \\dfrac{3{,}5\\cm}{5{,}5\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{EF} = 3{,}82\\cm\\end{aligned}"}, {"t": "Flächeninhalte und Anteil:", "m": "\\begin{aligned}A_{MFE} &= 0{,}5\\cdot 3{,}82\\cdot 3{,}5\\cmq = 6{,}69\\cmq\\\\[3pt]A_{ABCD} &= 6\\cdot 11\\cmq = 66\\cmq\\\\[3pt]\\dfrac{6{,}69}{66} &\\approx \\erg{10{,}14\\,\\%}\\end{aligned}"}]}]}, {"id": "tr21ntB1", "year": 2021, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "13", "stmt": ["n_2021nt_B1_0"], "note": "Teilaufgaben B 1.1, B 1.2, B 1.3 und B 1.4 · Kein Lösungsmuster vorhanden – Lösung selbst erstellt", "subs": [{"label": "B 1.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "Zeichne [AB] = 6 cm, rechter Winkel bei B, \\(\\overline{BD}\\) = 9 cm; C mit \\(\\overline{BC}\\) = 9 cm und \\(\\overline{CD}\\) = 7 cm (Zirkel).", "m": null}, {"t": "[AD] mit Pythagoras im Dreieck ABD:", "m": "\\begin{aligned}\\s{AD} &= \\sqrt{6^2+9^2}\\cm = 10{,}82\\cm\\end{aligned}"}, {"t": "Umfang:", "m": "\\begin{aligned}u &= (6+9+7+10{,}82)\\cm = \\erg{32{,}82\\cm}\\end{aligned}"}]}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Dreieck BCD ist gleichschenklig (\\(\\overline{BC}=\\overline{BD}\\)). Kosinussatz:", "m": "\\begin{aligned}9^2 &= 9^2+7^2-2\\cdot9\\cdot7\\cdot\\cos\\w BDC\\\\[3pt]\\cos\\w BDC &= \\dfrac{49}{126}\\\\[2pt]&\\Rightarrow\\;\\w BDC = \\erg{67{,}11^\\circ}\\end{aligned}"}]}, {"label": "B 1.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Rechtwinkliges Dreieck CDE mit Hypotenuse [CD]:", "m": "\\begin{aligned}\\sin 67{,}11^\\circ &= \\dfrac{\\s{CE}}{7\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{CE} = \\erg{6{,}45\\cm}\\\\[3pt]\\cos 67{,}11^\\circ &= \\dfrac{\\s{DE}}{7\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{DE} = \\erg{2{,}72\\cm}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "[EN] ist das Lot von E auf [BC]. Benötigt: ∢CBD und \\(\\overline{BE}\\):", "m": "\\begin{aligned}\\w CBD &= 180^\\circ-2\\cdot67{,}11^\\circ = 45{,}78^\\circ\\\\[3pt]\\s{BE} &= (9-2{,}72)\\cm = 6{,}28\\cm\\end{aligned}"}, {"t": "Rechtwinkliges Dreieck BNE:", "m": "\\begin{aligned}\\sin 45{,}78^\\circ &= \\dfrac{\\s{EN}}{6{,}28\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{EN} = \\erg{4{,}50\\cm}\\end{aligned}"}]}]}, {"id": "tr1", "year": 2022, "term": "Haupttermin", "nr": "A 2", "notr": false, "pts": "5", "stmt": ["tr_a01_0", "tr_a01_1", "tr_a01_2"], "note": "Teilaufgaben A 2.1 und A 2.2", "subs": [{"label": "A 2.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Zeichne [BD] ein. Im Dreieck ABD kennst du \\(\\overline{AB}\\), \\(\\overline{AD}\\) und ∢ADB. Der Winkel ∢DBA liegt gegenüber von [AD], ∢ADB liegt gegenüber von [AB]. Sinussatz:", "m": "\\begin{aligned}\\dfrac{\\sin\\w DBA}{\\s{AD}} &= \\dfrac{\\sin\\w ADB}{\\s{AB}}\\\\[3pt]\\sin\\w DBA &= \\dfrac{3\\cm\\cdot\\sin 80^\\circ}{8\\cm}\\\\[3pt]\\w DBA &= \\erg{21{,}67^\\circ}\\end{aligned}"}, {"t": "Den dritten Winkel liefert die Winkelsumme im Dreieck.", "m": "\\begin{aligned}\\w BAD &= 180^\\circ-80^\\circ-21{,}67^\\circ = 78{,}33^\\circ\\end{aligned}"}, {"t": "Jetzt nochmal Sinussatz für [BD]. Diese Seite liegt gegenüber von ∢BAD.", "m": "\\begin{aligned}\\s{BD} &= \\dfrac{8\\cm\\cdot\\sin 78{,}33^\\circ}{\\sin 80^\\circ}\\\\[3pt]\\s{BD} &= \\erg{7{,}96\\cm}\\end{aligned}"}], "solimg": "tr_sol_d01", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Die Diagonale [BD] zerlegt das Viereck in die Dreiecke ABD und BCD. Den Winkel bei B im Dreieck BCD bekommst du als Differenz.", "m": "\\begin{aligned}\\w CBD &= 110^\\circ-21{,}67^\\circ = 88{,}33^\\circ\\end{aligned}"}, {"t": "Für beide Dreiecke die Flächenformel \\(A=\\tfrac12\\cdot a\\cdot b\\cdot\\sin\\gamma\\) (zwei Seiten und der eingeschlossene Winkel).", "m": "\\begin{aligned}A &= 0{,}5\\cdot\\s{AB}\\cdot\\s{BD}\\cdot\\sin\\w DBA+0{,}5\\cdot\\s{BD}\\cdot\\s{BC}\\cdot\\sin\\w CBD\\\\[3pt]A &= \\left(0{,}5\\cdot 8\\cdot 7{,}96\\cdot\\sin 21{,}67^\\circ+0{,}5\\cdot 7{,}96\\cdot 8\\cdot\\sin 88{,}33^\\circ\\right)\\cmq\\\\[3pt]A &= \\erg{43{,}58\\cmq}\\end{aligned}"}]}]}, {"id": "tr2", "year": 2022, "term": "Nachtermin", "nr": "A 2", "notr": false, "pts": "2", "stmt": ["tr_a02_0"], "note": null, "subs": [{"label": "A 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Alle drei Seiten sind bekannt, gesucht ist ein Winkel. Dafür nimmst du den Kosinussatz. ∢BAC liegt gegenüber von [BC].", "m": "\\begin{aligned}\\s{BC}^2 &= \\s{AB}^2+\\s{AC}^2-2\\cdot\\s{AB}\\cdot\\s{AC}\\cdot\\cos\\w BAC\\end{aligned}"}, {"t": "Nach cos ∢BAC umstellen und einsetzen.", "m": "\\begin{aligned}\\cos\\w BAC &= \\dfrac{4^2+12^2-10^2}{2\\cdot 4\\cdot 12} = \\dfrac{60}{96}\\\\[3pt]\\w BAC &= \\erg{51{,}32^\\circ}\\end{aligned}"}]}]}, {"id": "tr3", "year": 2023, "term": "Haupttermin", "nr": "A 1", "notr": true, "pts": "3,5", "stmt": ["tr_a03_0"], "note": null, "subs": [{"label": "A 1", "pts": "3,5", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck AED ist [DE] die Gegenkathete und [AE] die Ankathete von ∢BAD. Ohne Taschenrechner: tan 60° = √3.", "m": "\\begin{aligned}\\tan 60^\\circ &= \\dfrac{\\s{DE}}{4\\cm}\\\\[3pt]\\s{DE} &= 4\\cm\\cdot\\sqrt3 = \\erg{4\\sqrt3\\cm}\\end{aligned}"}, {"t": "Das Trapez ist gleichschenklig, deshalb wird links und rechts gleich viel abgeschnitten.", "m": "\\begin{aligned}\\s{DC} &= \\s{AB}-2\\cdot\\s{AE} = (11-8)\\cm = \\erg{3\\cm}\\end{aligned}"}, {"t": "Trapezformel: Mittelwert der parallelen Seiten mal Höhe.", "m": "\\begin{aligned}A &= 0{,}5\\cdot(11+3)\\cdot 4\\sqrt3\\cmq = 7\\cdot 4\\sqrt3\\cmq = \\erg{28\\sqrt3\\cmq}\\end{aligned}"}]}]}, {"id": "tr4", "year": 2023, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "4", "stmt": ["tr_a04_0"], "note": "Teilaufgaben B 1.1 und B 1.2", "subs": [{"label": "B 1.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Zeichne [AB] mit 8 cm und den Halbkreis um M mit r = 4 cm. Q liegt senkrecht über M. P und R liegen je 50° neben Q auf dem Bogen (∢PMR = 100°, MQ ist Symmetrieachse).", "m": null}], "solimg": "tr_sol_d04", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Alle Strecken von M zum Bogen sind Radien. Die Symmetrieachse halbiert ∢PMR.", "m": "\\begin{aligned}\\s{MP} &= \\s{MQ} = 4\\cm;\\quad \\w PMQ = 50^\\circ\\end{aligned}"}, {"t": "[PQ] liegt gegenüber von ∢PMQ: Kosinussatz.", "m": "\\begin{aligned}\\s{PQ} &= \\sqrt{4^2+4^2-2\\cdot 4\\cdot 4\\cdot\\cos 50^\\circ}\\cm = 3{,}38\\cm\\end{aligned}"}, {"t": "Umfang des Drachens: je zweimal die gleichen Seiten.", "m": "\\begin{aligned}u &= 2\\cdot(4+3{,}38)\\cm = \\erg{14{,}76\\cm}\\end{aligned}"}]}]}, {"id": "tr5", "year": 2023, "term": "Nachtermin", "nr": "B 3", "notr": false, "pts": "9,5", "stmt": ["tr_a05_0"], "note": "Teilaufgaben B 3.1 bis B 3.3", "subs": [{"label": "B 3.1", "pts": "3,5", "text": "", "img": null, "sol": [{"t": "Winkelsumme im Viereck ist 360°.", "m": "\\begin{aligned}\\w DCB &= 360^\\circ-65^\\circ-105^\\circ-90^\\circ = \\erg{100^\\circ}\\end{aligned}"}, {"t": "Das Dreieck ABD ist bei A rechtwinklig. Pythagoras:", "m": "\\begin{aligned}\\s{BD} &= \\sqrt{11^2+8^2}\\cm = \\erg{13{,}60\\cm}\\end{aligned}"}], "solimg": "tr_sol_d05", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 3.2", "pts": "4", "text": "", "img": null, "sol": [{"t": "Erst ∢DBA im rechtwinkligen Dreieck ABD mit dem Tangens, dann ∢CBD als Differenz.", "m": "\\begin{aligned}\\tan\\w DBA &= \\dfrac{8}{11}\\;\\Rightarrow\\;\\w DBA = 36{,}03^\\circ\\\\[3pt]\\w CBD &= 65^\\circ-36{,}03^\\circ = 28{,}97^\\circ\\end{aligned}"}, {"t": "Im Dreieck BCD: [DC] liegt gegenüber von ∢CBD, [BD] gegenüber von ∢DCB. Sinussatz:", "m": "\\begin{aligned}\\s{DC} &= \\dfrac{13{,}60\\cm\\cdot\\sin 28{,}97^\\circ}{\\sin 100^\\circ} = \\erg{6{,}69\\cm}\\end{aligned}"}, {"t": "Für [BC] den dritten Winkel ∢BDC bestimmen und dann den Kosinussatz anwenden.", "m": "\\begin{aligned}\\w BDC &= 180^\\circ-100^\\circ-28{,}97^\\circ = 51{,}03^\\circ\\\\[3pt]\\s{BC} &= \\sqrt{13{,}60^2+6{,}69^2-2\\cdot 13{,}60\\cdot 6{,}69\\cdot\\cos 51{,}03^\\circ}\\cm\\\\[3pt]\\s{BC} &= \\erg{10{,}74\\cm}\\end{aligned}"}]}, {"label": "B 3.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Rechtwinkliges Dreieck ABD plus Dreieck BCD mit der Sinus-Flächenformel.", "m": "\\begin{aligned}A &= \\left(0{,}5\\cdot 11\\cdot 8+0{,}5\\cdot 10{,}74\\cdot 13{,}60\\cdot\\sin 28{,}97^\\circ\\right)\\cmq\\\\[3pt]A &= \\erg{79{,}37\\cmq}\\end{aligned}"}]}]}, {"id": "tr6", "year": 2024, "term": "Haupttermin", "nr": "B 4", "notr": false, "pts": "7", "stmt": ["tr_a06_0"], "note": "Teilaufgaben B 4.1 und B 4.2", "subs": [{"label": "B 4.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Zeichne [AB] mit 10 cm, dann um A und B Kreisbögen mit 11 cm, ihr Schnittpunkt ist D. CD ist parallel zu AB, C liegt auf dem Schenkel von ∢CBA = 85°. E liegt 6,5 cm von A entfernt auf dem Schenkel von ∢BAE = 105°. Der Kreisbogen um D mit r = 11 cm verbindet A und B.", "m": null}], "solimg": "tr_sol_d06", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 4.2", "pts": "4", "text": "", "img": null, "sol": [{"t": "AB ∥ CD, die Diagonale [DB] schneidet beide Parallelen. Dann sind ∢DBA und ∢BDC Wechselwinkel und gleich groß.", "m": null}, {"t": "Im gleichschenkligen Dreieck ABD (\\(\\overline{DA}=\\overline{DB}=11\\) cm) gibt der Kosinussatz ∢DBA. Der Winkel liegt gegenüber von [DA].", "m": "\\begin{aligned}\\cos\\w DBA &= \\dfrac{10^2+11^2-11^2}{2\\cdot 10\\cdot 11}\\\\[3pt]\\w DBA &= \\erg{62{,}96^\\circ}\\end{aligned}"}, {"t": "Ergänzungswinkel an den Parallelen:", "m": "\\begin{aligned}\\w DCB &= 180^\\circ-85^\\circ = \\erg{95^\\circ}\\end{aligned}"}, {"t": "Im Dreieck BCD Sinussatz für [CD], mit ∢CBD = 85° − 62,96° = 22,04°.", "m": "\\begin{aligned}\\s{CD} &= \\dfrac{11\\cm\\cdot\\sin 22{,}04^\\circ}{\\sin 95^\\circ} = \\erg{4{,}14\\cm}\\end{aligned}"}]}]}, {"id": "tr7", "year": 2024, "term": "Nachtermin", "nr": "B 3", "notr": false, "pts": "11,5", "stmt": ["tr_a07_0"], "note": "Teilaufgaben B 3.1 bis B 3.4", "subs": [{"label": "B 3.1", "pts": "3,5", "text": "", "img": null, "sol": [{"t": "Im Dreieck ABD sind zwei Winkel bekannt, den dritten gibt die Winkelsumme.", "m": "\\begin{aligned}\\w ADB &= 180^\\circ-80^\\circ-25^\\circ = 75^\\circ\\end{aligned}"}, {"t": "[BD] liegt gegenüber von ∢BAD, [AB] gegenüber von ∢ADB. Sinussatz:", "m": "\\begin{aligned}\\s{BD} &= \\dfrac{10\\cm\\cdot\\sin 80^\\circ}{\\sin 75^\\circ} = \\erg{10{,}20\\cm}\\end{aligned}"}], "solimg": "tr_sol_d07", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 3.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Dreieck BFE ist bei F rechtwinklig. [BF] ist die Ankathete von ∢DBA, [BE] die Hypotenuse.", "m": "\\begin{aligned}\\cos 25^\\circ &= \\dfrac{\\s{BF}}{4\\cm}\\\\[3pt]\\s{BF} &= \\erg{3{,}63\\cm}\\end{aligned}"}]}, {"label": "B 3.3", "pts": "3,5", "text": "", "img": null, "sol": [{"t": "FG ∥ BD: ∢GFA und ∢DBA sind Stufenwinkel, also gleich groß.", "m": null}, {"t": "Vierstreckensatz mit Zentrum A und \\(\\overline{AF}=10-3{,}63=6{,}37\\) cm.", "m": "\\begin{aligned}\\dfrac{\\s{FG}}{10{,}20\\cm} &= \\dfrac{6{,}37\\cm}{10\\cm}\\\\[3pt]\\s{FG} &= \\erg{6{,}50\\cm}\\end{aligned}"}]}, {"label": "B 3.4", "pts": "2,5", "text": "", "img": null, "sol": [{"t": "Im Dreieck BCD sind alle Seiten bekannt. Kosinussatz für ∢DCB (gegenüber von [BD]):", "m": "\\begin{aligned}\\cos\\w DCB &= \\dfrac{4^2+8^2-10{,}20^2}{2\\cdot 4\\cdot 8}\\\\[3pt]\\w DCB &= \\erg{112{,}06^\\circ}\\end{aligned}"}, {"t": "Fläche: zwei Dreiecke mit der Sinus-Flächenformel.", "m": "\\begin{aligned}A &= \\left(0{,}5\\cdot 10\\cdot 10{,}20\\cdot\\sin 25^\\circ+0{,}5\\cdot 4\\cdot 8\\cdot\\sin 112{,}06^\\circ\\right)\\cmq = \\erg{36{,}38\\cmq}\\end{aligned}"}]}]}, {"id": "tr8", "year": 2025, "term": "Haupttermin", "nr": "B 3", "notr": false, "pts": "8", "stmt": ["tr_a08_0"], "note": "Teilaufgaben B 3.1 bis B 3.3", "subs": [{"label": "B 3.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "AB ∥ CD: ∢DCB und ∢CBA sind Ergänzungswinkel (zusammen 180°).", "m": "\\begin{aligned}\\w DCB &= 180^\\circ-65^\\circ = \\erg{115^\\circ}\\end{aligned}"}], "solimg": "tr_sol_d08", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 3.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Im Dreieck BCD die fehlenden Winkel bestimmen.", "m": "\\begin{aligned}\\w CBD &= 65^\\circ-40^\\circ = 25^\\circ\\\\[3pt]\\w BDC &= 180^\\circ-115^\\circ-25^\\circ = 40^\\circ\\end{aligned}"}, {"t": "Sinussatz für [CD] (gegenüber von ∢CBD):", "m": "\\begin{aligned}\\s{CD} &= \\dfrac{10\\cm\\cdot\\sin 25^\\circ}{\\sin 40^\\circ} = \\erg{6{,}57\\cm}\\end{aligned}"}, {"t": "Kosinussatz für [BD] (gegenüber von ∢DCB):", "m": "\\begin{aligned}\\s{BD} &= \\sqrt{10^2+6{,}57^2-2\\cdot 10\\cdot 6{,}57\\cdot\\cos 115^\\circ}\\cm = \\erg{14{,}10\\cm}\\end{aligned}"}]}, {"label": "B 3.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck EBD ist [DE] die Gegenkathete von ∢DBA.", "m": "\\begin{aligned}\\s{DE} &= 14{,}10\\cm\\cdot\\sin 40^\\circ = \\erg{9{,}06\\cm}\\end{aligned}"}, {"t": "Trapezformel:", "m": "\\begin{aligned}A &= 0{,}5\\cdot(12+6{,}57)\\cdot 9{,}06\\cmq = \\erg{84{,}12\\cmq}\\end{aligned}"}]}]}, {"id": "tr9", "year": 2025, "term": "Nachtermin", "nr": "A 3", "notr": true, "pts": "4", "stmt": ["tr_a09_0"], "note": null, "subs": [{"label": "A 3.1", "pts": "1", "text": "", "img": null, "sol": [{"t": "[AB] ist ein Durchmesser des Kreises, C liegt auf dem Kreis. Nach dem Satz des Thales ist der Winkel bei C ein rechter.", "m": "\\begin{aligned}\\w ACB &= \\erg{90^\\circ}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "1", "text": "", "img": null, "sol": [{"t": "Das Dreieck AMC hat drei gleich lange Seiten: \\(\\overline{MA}=\\overline{MC}=r=3\\) cm und \\(\\overline{AC}=3\\) cm. Es ist gleichseitig, also sind alle Winkel 60°.", "m": "\\begin{aligned}\\w BAC &= \\erg{60^\\circ}\\end{aligned}"}]}, {"label": "A 3.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Sinus-Flächenformel mit sin 60° = ½√3:", "m": "\\begin{aligned}A &= 0{,}5\\cdot 6\\cdot 3\\cdot\\sin 60^\\circ\\cmq = 9\\cdot\\tfrac12\\sqrt3\\cmq = \\erg{4{,}5\\sqrt3\\cmq}\\end{aligned}"}]}]}, {"id": "tr10", "year": 2025, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "4,5", "stmt": ["tr_a10_0"], "note": "Teilaufgaben B 1.1 und B 1.2", "subs": [{"label": "B 1.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Zeichne [AB] mit 8 cm, trage an A 30° und an B 70° an. Der Schnittpunkt der Schenkel ist C. D erhältst du als Schnitt der Kreise um A (r = 5 cm) und um C (r = 6 cm).", "m": null}], "solimg": "tr_sol_d10", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2,5", "text": "", "img": null, "sol": [{"t": "Zuerst [AC] im Dreieck ABC: dritter Winkel, dann Sinussatz.", "m": "\\begin{aligned}\\w ACB &= 180^\\circ-70^\\circ-30^\\circ = 80^\\circ\\\\[3pt]\\s{AC} &= \\dfrac{8\\cm\\cdot\\sin 70^\\circ}{\\sin 80^\\circ} = 7{,}63\\cm\\end{aligned}"}, {"t": "Im Dreieck ACD sind jetzt alle Seiten bekannt. Kosinussatz für ∢ADC (gegenüber von [AC]):", "m": "\\begin{aligned}\\cos\\w ADC &= \\dfrac{5^2+6^2-7{,}63^2}{2\\cdot 5\\cdot 6}\\\\[3pt]\\w ADC &= \\erg{87{,}34^\\circ}\\end{aligned}"}]}]}]}, {"id": "rg", "name": "Raumgeometrie", "short": "10.2", "tasks": [{"id": "rg18htA3", "year": 2018, "term": "Haupttermin", "nr": "A 3", "notr": false, "pts": "5", "stmt": ["n_2018ht_A3_0"], "note": null, "subs": [{"label": "A 3.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck MDS ist [MS] die Gegenkathete und [MD] die Ankathete von ∢ADM.", "m": "\\begin{aligned}\\tan 71{,}6^\\circ &= \\dfrac{5\\cm}{\\s{MD}}\\\\[3pt]\\s{MD} &= \\erg{1{,}7\\cm}\\end{aligned}"}, {"t": "\\(\\overline{AN}\\) mit dem Vierstreckensatz (Zentrum S); \\(\\overline{NS}=(5-2)\\) cm.", "m": "\\begin{aligned}\\dfrac{\\s{AN}}{\\s{MD}} &= \\dfrac{\\s{NS}}{\\s{MS}}\\\\[3pt]\\dfrac{\\s{AN}}{1{,}7\\cm} &= \\dfrac{(5-2)\\cm}{5\\cm}\\\\[3pt]\\s{AN} &= \\erg{1{,}0\\cm}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Die Praline ist ein großer Kegel (r = 1,7 cm, h = 5 cm) ohne die Spitze, einen kleinen Kegel (r = 1,0 cm, h = 3 cm).", "m": "\\begin{aligned}V_{\\text{Praline}} &= \\left(\\tfrac13\\cdot 1{,}7^2\\cdot\\pi\\cdot 5-\\tfrac13\\cdot 1{,}0^2\\cdot\\pi\\cdot 3\\right)\\cmk = 12{,}0\\cmk\\end{aligned}"}, {"t": "89 % sind Schokolade, also sind 11 % Füllung.", "m": "\\begin{aligned}V &= (1-0{,}89)\\cdot 12{,}0\\cmk = \\erg{1{,}3\\cmk}\\end{aligned}"}]}]}, {"id": "rg18htB2", "year": 2018, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "17", "stmt": ["n_2018ht_B2_0"], "note": null, "subs": [{"label": "B 2.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "[AC] mit 10 cm auf die Schrägbildachse, [BD] durch M unter 45° mit halber Länge (je 1,5 cm). Senkrechte Kanten 10 cm.", "m": null}, {"t": "Das Dreieck AME ist bei A rechtwinklig mit \\(\\overline{AM}=5\\) cm und \\(\\overline{AE}=10\\) cm.", "m": "\\begin{aligned}\\s{ME} &= \\sqrt{5^2+10^2}\\cm = \\erg{11{,}18\\cm}\\end{aligned}"}, {"t": "∢MEN ist so groß wie ∢AME (Wechselwinkel, EN ∥ AM). Im Dreieck AME:", "m": "\\begin{aligned}\\tan\\varphi &= \\dfrac{\\s{AE}}{\\s{AM}} = \\dfrac{10}{5}\\\\[3pt]\\varphi &= \\erg{63{,}43^\\circ}\\end{aligned}"}], "solimg": "ns_2018ht_B2_B21", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 2.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Zeichne \\(S_1\\) 3 cm von E auf [EM] und das Dreieck \\(S_1GE\\). Der Winkel bei E ist φ, \\(\\overline{EG}=10\\) cm.", "m": "\\begin{aligned}A_{S_1GE} &= 0{,}5\\cdot 3\\cdot 10\\cdot\\sin 63{,}43^\\circ\\cmq = \\erg{13{,}42\\cmq}\\end{aligned}"}, {"t": "Kosinussatz für die gegenüberliegende Seite:", "m": "\\begin{aligned}\\s{S_1G} &= \\sqrt{3^2+10^2-2\\cdot 3\\cdot 10\\cdot\\cos 63{,}43^\\circ}\\cm = \\erg{9{,}06\\cm}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "4", "text": "", "img": null, "sol": [{"t": "Die Grundfläche ist die Raute: \\(\\tfrac12\\cdot\\overline{AC}\\cdot\\overline{BD}\\).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{AC}\\cdot\\s{BD}\\cdot\\s{Q_nS_n}\\end{aligned}"}, {"t": "Höhe mit dem Vierstreckensatz (Zentrum M, \\(Q_nS_n\\parallel AE\\)); \\(\\overline{MS_n}=(11{,}18-x)\\) cm.", "m": "\\begin{aligned}\\dfrac{\\s{Q_nS_n}}{10\\cm} &= \\dfrac{(11{,}18-x)\\cm}{11{,}18\\cm}\\\\[3pt]\\s{Q_nS_n}(x) &= (10-0{,}89x)\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 10\\cdot 6\\cdot(10-0{,}89x)\\cmk = \\erg{(100-8{,}9x)\\cmk}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "Im Dreieck \\(AES_2\\) kennst du \\(\\overline{AE}=10\\) cm und die Winkel. ∢S₂AE = 90° − 54° = 36°. Der Winkel bei E im Dreieck AEM ist 90° − 63,43°.", "m": "\\begin{aligned}\\w ES_2A &= 180^\\circ-36^\\circ-(90^\\circ-63{,}43^\\circ) = 117{,}43^\\circ\\end{aligned}"}, {"t": "Sinussatz: \\(\\overline{ES_2}=x\\) liegt gegenüber von 36°, \\(\\overline{AE}\\) gegenüber von 117,43°.", "m": "\\begin{aligned}\\dfrac{x}{\\sin 36^\\circ} &= \\dfrac{10}{\\sin 117{,}43^\\circ}\\\\[3pt]x &= 6{,}62\\end{aligned}"}, {"t": "In V(x) einsetzen:", "m": "\\begin{aligned}V_{ABCDS_2} &= (100-8{,}9\\cdot 6{,}62)\\cmk = \\erg{41{,}08\\cmk}\\end{aligned}"}]}, {"label": "B 2.5", "pts": "2", "text": "", "img": null, "sol": [{"t": "Volumen des Prismas:", "m": "\\begin{aligned}V_{\\text{Prisma}} &= 0{,}5\\cdot 10\\cdot 6\\cdot 10\\cmk = 300\\cmk\\end{aligned}"}, {"t": "Die Pyramiden haben höchstens 100 cm³ (bei x = 0). Die Hälfte des Prismas wären 150 cm³, das wird nie erreicht.", "m": "\\begin{aligned}V(x) &\\le 100\\cmk < 150\\cmk\\end{aligned}"}]}]}, {"id": "rg18ntA3", "year": 2018, "term": "Nachtermin", "nr": "A 3", "notr": false, "pts": "5", "stmt": ["n_2018nt_A3_0"], "note": null, "subs": [{"label": "A 3", "pts": "5", "text": "", "img": null, "sol": [{"t": "Das Sandvolumen besteht aus einer Halbkugel (r = 10 mm) und einem Zylinder (r = 10 mm, Höhe \\(\\overline{BC}\\)).", "m": null}, {"t": "Höhe des oberen Kegelstücks AB: Im rechtwinkligen Dreieck mit dem Winkel 59° bei B ist der waagrechte Abstand (10 − 0,5·2) mm = 9 mm.", "m": "\\begin{aligned}\\tan 59^\\circ &= \\dfrac{d(A;BF)}{(10-0{,}5\\cdot 2)\\,\\mathrm{mm}}\\\\[3pt]d(A;BF) &= 15\\,\\mathrm{mm}\\end{aligned}"}, {"t": "Die untere Hälfte ist 50 mm hoch: 10 mm Halbkugel, Zylinder, 15 mm Kegelstück.", "m": "\\begin{aligned}\\s{BC} &= (50-10-15)\\,\\mathrm{mm} = 25\\,\\mathrm{mm}\\end{aligned}"}, {"t": "Volumen des Sandes:", "m": "\\begin{aligned}V &= \\left(\\tfrac12\\cdot\\tfrac43\\cdot 10^3\\cdot\\pi+10^2\\cdot\\pi\\cdot 25\\right)\\mathrm{mm}^3 = 9948\\,\\mathrm{mm}^3\\end{aligned}"}, {"t": "Zeit = Volumen : Durchfluss.", "m": "\\begin{aligned}9948\\,\\mathrm{mm}^3 : 50\\,\\tfrac{\\mathrm{mm}^3}{\\mathrm s} &= \\erg{199\\,\\mathrm s}\\end{aligned}"}]}]}, {"id": "rg18ntB2", "year": 2018, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "17", "stmt": ["n_2018nt_B2_0"], "note": null, "subs": [{"label": "B 2.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "[AM] mit 8 cm auf die Schrägbildachse, [BC] durch M unter 45° mit halber Länge (je 2,5 cm). Senkrechte Kanten 9 cm.", "m": null}, {"t": "[AM] halbiert im gleichschenkligen Dreieck den Winkel bei A. Im rechtwinkligen Dreieck AMC:", "m": "\\begin{aligned}\\tan\\tfrac{\\varphi}{2} &= \\dfrac{0{,}5\\cdot 10\\cm}{8\\cm}\\\\[3pt]\\varphi &= \\erg{64{,}01^\\circ}\\end{aligned}"}], "solimg": "ns_2018nt_B2_B21", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Dreieck AMD ist bei A rechtwinklig.", "m": "\\begin{aligned}\\s{MD} &= \\sqrt{8^2+9^2}\\cm = \\erg{12{,}04\\cm}\\end{aligned}"}, {"t": "∢NMD = ∢MDA (Wechselwinkel, MN ∥ AD). [AM] ist Gegenkathete, [AD] Ankathete.", "m": "\\begin{aligned}\\tan\\varepsilon &= \\dfrac{8}{9}\\\\[2pt]&\\Rightarrow\\;\\varepsilon = \\erg{41{,}63^\\circ}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Das Dreieck \\(MH_1S_1\\) ist bei \\(H_1\\) rechtwinklig. \\([S_1H_1]\\) ist Gegenkathete von ε, \\(\\overline{MS_1}=(12{,}04-4)\\) cm die Hypotenuse.", "m": "\\begin{aligned}\\sin 41{,}63^\\circ &= \\dfrac{\\s{S_1H_1}}{(12{,}04-4)\\cm}\\\\[3pt]\\s{S_1H_1} &= \\erg{5{,}34\\cm}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "Grundfläche ist der Drachen \\(MR_nNQ_n\\) mit den Diagonalen \\(\\overline{MN}=9\\) cm und \\(\\overline{Q_nR_n}=10\\) cm. Die Höhe ist \\([S_nH_n]\\).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{MN}\\cdot\\s{Q_nR_n}\\cdot\\s{S_nH_n}\\end{aligned}"}, {"t": "Höhe mit dem Vierstreckensatz (Zentrum M, \\(S_nH_n\\parallel DN\\)).", "m": "\\begin{aligned}\\dfrac{\\s{S_nH_n}}{8\\cm} &= \\dfrac{(12{,}04-x)\\cm}{12{,}04\\cm}\\\\[3pt]\\s{S_nH_n}(x) &= (8-0{,}66x)\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 9\\cdot 10\\cdot(8-0{,}66x)\\cmk = \\erg{(120-9{,}9x)\\cmk}\\end{aligned}"}]}, {"label": "B 2.5", "pts": "3", "text": "", "img": null, "sol": [{"t": "Prisma: Grundfläche · Höhe.", "m": "\\begin{aligned}V_{\\text{Prisma}} &= 0{,}5\\cdot 10\\cdot 8\\cdot 9\\cmk = 360\\cmk\\end{aligned}"}, {"t": "25 % davon gleichsetzen:", "m": "\\begin{aligned}0{,}25\\cdot 360 &= 120-9{,}9x\\\\[3pt]9{,}9x &= 30\\\\[3pt]x &= \\erg{3{,}03}\\end{aligned}"}]}, {"label": "B 2.6", "pts": "3", "text": "", "img": null, "sol": [{"t": "Im Dreieck \\(MS_3N\\) die Winkelsumme:", "m": "\\begin{aligned}\\w S_3NM &= 180^\\circ-110^\\circ-41{,}63^\\circ = 28{,}37^\\circ\\end{aligned}"}, {"t": "Sinussatz: \\(\\overline{MS_3}=(12{,}04-x)\\) cm liegt gegenüber von ∢S₃NM, \\(\\overline{MN}=9\\) cm gegenüber von 110°.", "m": "\\begin{aligned}\\dfrac{12{,}04-x}{\\sin 28{,}37^\\circ} &= \\dfrac{9}{\\sin 110^\\circ}\\\\[3pt]12{,}04-x &= 4{,}55\\\\[3pt]x &= \\erg{7{,}49}\\end{aligned}"}]}]}, {"id": "rg19htA3", "year": 2019, "term": "Haupttermin", "nr": "A 3", "notr": false, "pts": "6", "stmt": ["n_2019ht_A3_0"], "note": null, "subs": [{"label": "A 3.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck AMS ist [AM] die Gegenkathete von ∢ASM, [MS] die Ankathete.", "m": "\\begin{aligned}\\tan 16^\\circ &= \\dfrac{21\\cm}{\\s{MS}}\\\\[3pt]\\s{MS} &= \\erg{73{,}2\\cm}\\end{aligned}"}, {"t": "[HC] ist der Durchmesser des Kegels in Höhe O. Vierstreckensatz mit Zentrum S; \\(\\overline{SO}=73{,}2-(45-5)\\) cm.", "m": "\\begin{aligned}\\dfrac{\\s{HC}}{2\\cdot 21\\cm} &= \\dfrac{[73{,}2-(45-5)]\\cm}{73{,}2\\cm}\\\\[3pt]\\s{HC} &= \\erg{19{,}0\\cm}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "4", "text": "", "img": null, "sol": [{"t": "Der Körper: großer Kegel (r = 21 cm, h = 73,2 cm) minus Kegelspitze oberhalb von O (r = 9,5 cm, h = 33,2 cm) plus Zylinder als Sitzfläche (r = 21 cm, h = 5 cm).", "m": "\\begin{aligned}V_1 &= \\tfrac13\\cdot 21^2\\cdot\\pi\\cdot 73{,}2\\cmk = 33\\,804{,}8\\cmk\\\\[3pt]V_2 &= \\tfrac13\\cdot(0{,}5\\cdot 19{,}0)^2\\cdot\\pi\\cdot 33{,}2\\cmk = 3137{,}7\\cmk\\\\[3pt]V_3 &= 21^2\\cdot\\pi\\cdot 5\\cmk = 6927{,}2\\cmk\\end{aligned}"}, {"t": "Zusammenrechnen:", "m": "\\begin{aligned}V &= (33\\,804{,}8-3137{,}7+6927{,}2)\\cmk = \\erg{37\\,594{,}3\\cmk}\\end{aligned}"}]}]}, {"id": "rg19htB2", "year": 2019, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "17", "stmt": ["n_2019ht_B2_0"], "note": null, "subs": [{"label": "B 2.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "[AC] mit 9 cm auf die Schrägbildachse, M 3 cm rechts von A. [BD] durch M unter 45° mit halber Länge (je 2 cm). Die Höhe [AS] steht in A senkrecht (10 cm).", "m": null}, {"t": "Das Dreieck AMS ist bei A rechtwinklig.", "m": "\\begin{aligned}\\s{MS} &= \\sqrt{3^2+10^2}\\cm = \\erg{10{,}44\\cm}\\\\[3pt]\\tan\\varphi &= \\dfrac{10}{3}\\\\[2pt]&\\Rightarrow\\;\\varphi = \\erg{73{,}30^\\circ}\\end{aligned}"}], "solimg": "ns_2019ht_B2_B21", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch die Pyramide aus B 2.2)"}, {"label": "B 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Für x = 3: \\(P_1\\) liegt 3 cm von S auf [SM]. \\(A_1\\) liegt 4,5 cm links von A. Die Höhe \\([P_1F_1]\\) ist parallel zu [AS].", "m": null}]}, {"label": "B 2.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Im Dreieck \\(MA_1P_1\\): \\(\\overline{MA_1}=(3+4{,}5)\\) cm, \\(\\overline{MP_1}=(10{,}44-3)\\) cm, Winkel bei M ist φ. Kosinussatz:", "m": "\\begin{aligned}\\s{A_1P_1} &= \\sqrt{7{,}5^2+7{,}44^2-2\\cdot 7{,}5\\cdot 7{,}44\\cdot\\cos 73{,}30^\\circ}\\cm = 8{,}92\\cm\\end{aligned}"}, {"t": "Sinussatz: α liegt gegenüber von \\([MP_1]\\).", "m": "\\begin{aligned}\\dfrac{\\sin\\alpha}{10{,}44-3} &= \\dfrac{\\sin 73{,}30^\\circ}{8{,}92}\\\\[3pt]\\alpha &= \\erg{53{,}03^\\circ}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "3", "text": "", "img": null, "sol": [{"t": "Grundfläche: Drachen mit den Diagonalen \\(\\overline{A_nC}=(9+1{,}5x)\\) cm und \\(\\overline{BD}=8\\) cm.", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{A_nC}\\cdot\\s{BD}\\cdot\\s{P_nF_n}\\end{aligned}"}, {"t": "Höhe mit dem Vierstreckensatz (Zentrum M, \\(P_nF_n\\parallel SA\\)).", "m": "\\begin{aligned}\\dfrac{\\s{P_nF_n}}{10\\cm} &= \\dfrac{(10{,}44-x)\\cm}{10{,}44\\cm}\\\\[3pt]\\s{P_nF_n}(x) &= (10-0{,}96x)\\cm\\end{aligned}"}, {"t": "Einsetzen und ausmultiplizieren:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot(9+1{,}5x)\\cdot 8\\cdot(10-0{,}96x)\\cmk\\\\[3pt]&= \\tfrac43\\cdot(90-8{,}64x+15x-1{,}44x^2)\\cmk\\\\[3pt]V(x) &= \\erg{(-1{,}92x^2+8{,}48x+120)\\cmk}\\end{aligned}"}]}, {"label": "B 2.5", "pts": "3", "text": "", "img": null, "sol": [{"t": "Maximum im Scheitel:", "m": "\\begin{aligned}x_S &= -\\dfrac{8{,}48}{2\\cdot(-1{,}92)} = 2{,}21\\\\[3pt]V_{\\max} &= 129{,}36\\cmk\\end{aligned}"}, {"t": "Ursprüngliche Pyramide:", "m": "\\begin{aligned}V_{ABCDS} &= \\tfrac13\\cdot\\tfrac12\\cdot 9\\cdot 8\\cdot 10\\cmk = 120\\cmk\\end{aligned}"}, {"t": "Vergleich:", "m": "\\begin{aligned}\\dfrac{129{,}36}{120}\\cdot 100\\,\\% &= 107{,}80\\,\\%\\\\[2pt]&\\Rightarrow\\;\\erg{\\text{um }7{,}80\\,\\%\\text{ größer}}\\end{aligned}"}]}, {"label": "B 2.6", "pts": "2", "text": "", "img": null, "sol": [{"t": "Prüfe zwei Eigenschaften: V(0) = 120 cm³ und das Maximum liegt über 120 cm³.", "m": null}, {"t": "Graph A hat kein Maximum über 120 cm³. Graph C startet bei x = 0 nicht bei 120 cm³. Also stellen A und C das Volumen nicht dar.", "m": "\\begin{aligned}&\\erg{\\text{Graph A und Graph C}}\\end{aligned}"}]}]}, {"id": "rg19ntA2", "year": 2019, "term": "Nachtermin", "nr": "A 2", "notr": false, "pts": "9", "stmt": ["n_2019nt_A2_0", "n_2019nt_A2_1"], "note": null, "subs": [{"label": "A 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck MCS ist [CS] die Hypotenuse. Satz des Pythagoras:", "m": "\\begin{aligned}\\s{MS} &= \\sqrt{10^2-8^2}\\cm = 6\\cm\\end{aligned}"}, {"t": "Grundfläche ist die Raute (Drachenviereck) mit den Diagonalen [AC] und [BD]:", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{AC}\\cdot\\s{BD}\\cdot\\s{MS}\\\\[3pt]V &= \\tfrac13\\cdot\\tfrac12\\cdot 12\\cdot 9\\cdot 6\\cmk = \\erg{108\\cmk}\\end{aligned}"}]}, {"label": "A 2.2", "pts": "1", "text": "", "img": null, "sol": [{"t": "Für x = 1,5 gilt \\(\\overline{MC_1}=8-2\\cdot1{,}5=5\\) cm und \\(\\overline{MS_1}=6+1{,}5=7{,}5\\) cm. Trage die Punkte ein und verbinde zur Pyramide.", "m": null}], "solimg": "ns_2019nt_A2_A22", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 2.3", "pts": "4", "text": "", "img": null, "sol": [{"t": "Die Grundfläche \\(BC_nD\\) ist ein Dreieck mit Grundlinie [BD] und Höhe \\(\\overline{MC_n}=(8-2x)\\) cm; die Pyramidenhöhe ist \\(\\overline{MS_n}=(6+x)\\) cm:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot(8-2x)\\cdot 9\\cdot(6+x)\\cmk\\\\[3pt]V(x) &= (-3x^2-6x+72)\\cmk\\end{aligned}"}, {"t": "„Um 70 % kleiner“ heißt: Das Volumen beträgt noch 30 % von 108 cm³:", "m": "\\begin{aligned}-3x^2-6x+72 &= 0{,}3\\cdot 108\\\\[3pt]-3x^2-6x+39{,}6 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{6\\pm\\sqrt{36+475{,}2}}{-6}\\\\[3pt]x &= \\erg{2{,}77}\\quad(x=-4{,}77\\ \\text{entfällt})\\end{aligned}"}]}, {"label": "A 2.4", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck \\(MC_3S_3\\) ist \\([MS_3]\\) die Gegenkathete und \\([MC_3]\\) die Ankathete von ∢S<sub>3</sub>C<sub>3</sub>M:", "m": "\\begin{aligned}\\tan 72^\\circ &= \\dfrac{6+x}{8-2x}\\\\[3pt](8-2x)\\cdot\\tan 72^\\circ &= 6+x\\\\[3pt]x\\cdot(1+2\\tan 72^\\circ) &= 8\\tan 72^\\circ-6\\\\[3pt]x &= \\erg{2{,}60}\\end{aligned}"}]}]}, {"id": "rg20htA2", "year": 2020, "term": "Haupttermin", "nr": "A 2", "notr": false, "pts": "9", "stmt": ["n_2020ht_A2_0", "n_2020ht_A2_1"], "note": null, "subs": [{"label": "A 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Dreieck PQS ist rechtwinklig bei Q (Höhe [QS]). Pythagoras:", "m": "\\begin{aligned}\\s{PS} &= \\sqrt{4^2+8^2}\\cm = \\erg{8{,}94\\cm}\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum S (EF ∥ AB); \\(\\overline{RS}=\\overline{PS}-\\overline{PR}\\):", "m": "\\begin{aligned}\\dfrac{\\s{EF}}{6\\cm} &= \\dfrac{(8{,}94-3)\\cm}{8{,}94\\cm}\\\\[3pt]\\s{EF} &= \\erg{3{,}99\\cm}\\end{aligned}"}]}, {"label": "A 2.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Trapezfläche: \\(A=0{,}5\\cdot(\\overline{EF}+\\overline{CD})\\cdot\\overline{QR}\\). Zuerst ∢QPS im rechtwinkligen Dreieck PQS:", "m": "\\begin{aligned}\\tan\\w QPS &= \\dfrac{8}{4}\\\\[2pt]&\\Rightarrow\\;\\w QPS = 63{,}43^\\circ\\end{aligned}"}, {"t": "[QR] mit dem Kosinussatz im Dreieck PQR:", "m": "\\begin{aligned}\\s{QR} &= \\sqrt{3^2+4^2-2\\cdot3\\cdot4\\cdot\\cos 63{,}43^\\circ}\\cm = 3{,}78\\cm\\end{aligned}"}, {"t": "Flächeninhalt:", "m": "\\begin{aligned}A &= 0{,}5\\cdot(3{,}99+10)\\cdot 3{,}78\\cmq = \\erg{26{,}44\\cmq}\\end{aligned}"}]}, {"label": "A 2.3", "pts": "4", "text": "", "img": null, "sol": [{"t": "Zeichne T auf [QS] mit RT ∥ PQ und verbinde E, F, T mit S.", "m": null}, {"t": "Volumen: Grundfläche EFT (Grundlinie [EF], Höhe [RT]) mal Höhe [ST]:", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{EF}\\cdot\\s{RT}\\cdot\\s{ST}\\end{aligned}"}, {"t": "Wegen RT ∥ PQ gilt ∢TRS = ∢QPS = 63,43°. Im rechtwinkligen Dreieck RTS:", "m": "\\begin{aligned}\\cos 63{,}43^\\circ &= \\dfrac{\\s{RT}}{(8{,}94-3)\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{RT} = 2{,}66\\cm\\\\[3pt]\\sin 63{,}43^\\circ &= \\dfrac{\\s{ST}}{(8{,}94-3)\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{ST} = 5{,}31\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot 3{,}99\\cdot 2{,}66\\cdot 5{,}31\\cmk = \\erg{9{,}39\\cmk}\\end{aligned}"}], "solimg": "ns_2020ht_A2_A23", "solcap": "Schrägbild aus dem Lösungsmuster"}]}, {"id": "rg20ntA3", "year": 2020, "term": "Nachtermin", "nr": "A 3", "notr": false, "pts": "5", "stmt": ["n_2020nt_A3_0"], "note": null, "subs": [{"label": "A 3.1", "pts": "1", "text": "", "img": null, "sol": [{"t": "Kegelvolumen mit Radius \\(\\overline{DE}=4\\) cm, nach der Höhe auflösen:", "m": "\\begin{aligned}134\\cmk &= \\tfrac13\\cdot(4\\cm)^2\\cdot\\pi\\cdot\\s{AE}\\\\[3pt]\\s{AE} &= \\dfrac{3\\cdot 134}{16\\pi}\\cm = \\erg{8{,}00\\cm}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "4", "text": "", "img": null, "sol": [{"t": "Der Körper = großer Kegel (ADE) − Kegel (ACF) + Kegel (ABF):", "m": "\\begin{aligned}V &= V_{ADE}-V_{ACF}+V_{ABF}\\end{aligned}"}, {"t": "„25 % kürzer“:", "m": "\\begin{aligned}\\s{AF} &= 0{,}75\\cdot 8{,}00\\cm = 6{,}00\\cm\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum A (CF ∥ DE):", "m": "\\begin{aligned}\\dfrac{\\s{CF}}{4\\cm} &= \\dfrac{6{,}00\\cm}{8{,}00\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{CF} = 3{,}00\\cm\\end{aligned}"}, {"t": "Teilvolumen:", "m": "\\begin{aligned}V_{ACF} &= \\tfrac13\\cdot 3{,}00^2\\cdot\\pi\\cdot 6{,}00\\cmk = 56{,}55\\cmk\\\\[3pt]V_{ABF} &= \\tfrac13\\cdot 8{,}00^2\\cdot\\pi\\cdot 6{,}00\\cmk = 402{,}12\\cmk\\\\[3pt]V &= (134-56{,}55+402{,}12)\\cmk = \\erg{479{,}57\\cmk}\\end{aligned}"}]}]}, {"id": "rg20ntB2", "year": 2020, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "17", "stmt": ["n_2020nt_B2_0"], "note": null, "subs": [{"label": "B 2.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "Schrägbild: [AC] = 13 cm auf der Schrägbildachse, [BD] unter 45° mit halber Länge (6 cm · 0,5 = 3 cm), Höhe [MS] = 12 cm senkrecht.", "m": null}, {"t": "Dreieck MCS ist rechtwinklig bei M:", "m": "\\begin{aligned}\\s{CS} &= \\sqrt{(0{,}5\\cdot13)^2+12^2}\\cm = \\erg{13{,}65\\cm}\\\\[3pt]\\tan\\w SCA &= \\dfrac{12}{0{,}5\\cdot 13}\\\\[2pt]&\\Rightarrow\\;\\w SCA = \\erg{61{,}56^\\circ}\\end{aligned}"}], "solimg": "ns_2020nt_B2_B21", "solcap": "Schrägbild aus dem Lösungsmuster (auch B 2.2)"}, {"label": "B 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(H_1\\) auf [AM] mit \\(\\overline{AH_1}=3\\) cm; \\([P_1Q_1]\\) parallel zu [BD] durch \\(H_1\\); \\(R_1\\) senkrecht über \\(H_1\\) so, dass \\(\\overline{CR_1}=\\overline{CS}\\).", "m": null}]}, {"label": "B 2.3", "pts": "5", "text": "", "img": null, "sol": [{"t": "Volumen: Grundfläche \\(AP_1CQ_1\\) (Diagonalen [AC] und \\([P_1Q_1]\\)) mal Höhe:", "m": "\\begin{aligned}V_1 &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{AC}\\cdot\\s{P_1Q_1}\\cdot\\s{H_1R_1}\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum A:", "m": "\\begin{aligned}\\dfrac{\\s{P_1Q_1}}{12\\cm} &= \\dfrac{3\\cm}{0{,}5\\cdot13\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{P_1Q_1} = 5{,}54\\cm\\end{aligned}"}, {"t": "Pythagoras im rechtwinkligen Dreieck \\(H_1CR_1\\) mit \\(\\overline{CH_1}=(13-3)\\) cm:", "m": "\\begin{aligned}\\s{H_1R_1} &= \\sqrt{13{,}65^2-(13-3)^2}\\cm = 9{,}29\\cm\\end{aligned}"}, {"t": "Einsetzen und mit V vergleichen:", "m": "\\begin{aligned}V_1 &= \\tfrac13\\cdot\\tfrac12\\cdot 13\\cdot 5{,}54\\cdot 9{,}29\\cmk = \\erg{111{,}51\\cmk}\\\\[3pt]V &= \\tfrac13\\cdot\\tfrac12\\cdot 13\\cdot12\\cdot12\\cmk = 312\\cmk\\\\[3pt]\\dfrac{111{,}51}{312} &\\approx \\erg{35{,}74\\,\\%}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "2", "text": "", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck \\(H_2CR_2\\) ist \\(\\overline{CR_2}=13{,}65\\) cm die Hypotenuse:", "m": "\\begin{aligned}\\s{CH_2} &= \\sqrt{13{,}65^2-6^2}\\cm = 12{,}26\\cm\\\\[3pt]\\s{AH_2} &= (13-12{,}26)\\cm = 0{,}74\\cm\\\\[2pt]&\\Rightarrow\\;x = \\erg{0{,}74}\\end{aligned}"}]}, {"label": "B 2.5", "pts": "2", "text": "", "img": null, "sol": [{"t": "Wie in B 2.3, aber allgemein mit \\(\\overline{CH_n}=(13-x)\\) cm:", "m": "\\begin{aligned}\\s{H_nR_n}(x) &= \\sqrt{13{,}65^2-(13-x)^2}\\cm\\\\[3pt]\\s{H_nR_n}(x) &= \\sqrt{186{,}32-169+26x-x^2}\\cm\\\\[3pt]\\s{H_nR_n}(x) &= \\erg{\\sqrt{-x^2+26x+17{,}32}\\cm}\\end{aligned}"}]}, {"label": "B 2.6", "pts": "2", "text": "", "img": null, "sol": [{"t": "Angenommen, es gäbe so eine Pyramide. Im rechtwinkligen Dreieck \\(H_3CR_3\\):", "m": "\\begin{aligned}\\cos 15^\\circ &= \\dfrac{\\s{CH_3}}{13{,}65\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{CH_3} = 13{,}18\\cm > \\s{AC}\\end{aligned}"}, {"t": "Dann läge \\(H_3\\) nicht mehr auf [AM] – Widerspruch. Also gibt es keine solche Pyramide.", "m": null}]}]}, {"id": "rg21htA3", "year": 2021, "term": "Haupttermin", "nr": "A 3", "notr": false, "pts": "5", "stmt": ["n_2021ht_A3_0"], "note": null, "subs": [{"label": "A 3", "pts": "5", "text": "", "img": null, "sol": [{"t": "Körper = Zylinder (Radius 2,5 cm, Höhe 4 cm) − Kegel (Spitze G, Radius 2,5 cm) + kleiner Kegel (Spitze G, Radius 1,2 cm):", "m": "\\begin{aligned}V &= \\s{FK}^2\\cdot\\pi\\cdot\\s{AF}-\\tfrac13\\cdot\\s{FK}^2\\cdot\\pi\\cdot\\s{GK}+\\tfrac13\\cdot\\s{EH}^2\\cdot\\pi\\cdot\\s{GH}\\end{aligned}"}, {"t": "Höhe des großen Kegels im rechtwinkligen Dreieck GFK:", "m": "\\begin{aligned}\\tan 50^\\circ &= \\dfrac{\\s{GK}}{0{,}5\\cdot5\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{GK} = 2{,}98\\cm\\end{aligned}"}, {"t": "Höhe des kleinen Kegels mit dem Vierstreckensatz (Zentrum G):", "m": "\\begin{aligned}\\dfrac{\\s{GH}}{2{,}98\\cm} &= \\dfrac{2{,}4\\cm}{5\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{GH} = 1{,}43\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V &= \\left[2{,}5^2\\pi\\cdot4-\\tfrac13\\cdot2{,}5^2\\pi\\cdot2{,}98+\\tfrac13\\cdot1{,}2^2\\pi\\cdot1{,}43\\right]\\cmk\\\\[3pt]V &= \\erg{61{,}19\\cmk}\\end{aligned}"}]}]}, {"id": "rg21htB2", "year": 2021, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "17", "stmt": ["n_2021ht_B2_0"], "note": null, "subs": [{"label": "B 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "[AM] = 9 cm auf der Schrägbildachse; [BC] unter 45° mit halber Länge (12 cm · 0,5 = 6 cm), M in der Mitte; [MS] = 10 cm senkrecht.", "m": null}], "solimg": "ns_2021ht_B2_B21", "solcap": "Schrägbild aus dem Lösungsmuster (auch B 2.3, B 2.4)"}, {"label": "B 2.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Rechtwinkliges Dreieck AMS:", "m": "\\begin{aligned}\\s{AS} &= \\sqrt{9^2+10^2}\\cm = \\erg{13{,}45\\cm}\\\\[3pt]\\tan\\w MAS &= \\dfrac{10}{9}\\\\[2pt]&\\Rightarrow\\;\\w MAS = \\erg{48{,}01^\\circ}\\end{aligned}"}, {"t": "Volumen:", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot12\\cdot9\\cdot10\\cmk = \\erg{180\\cmk}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Zuerst [DM] mit dem Kosinussatz im Dreieck ADM:", "m": "\\begin{aligned}\\s{DM} &= \\sqrt{9^2+4^2-2\\cdot9\\cdot4\\cdot\\cos 48{,}01^\\circ}\\cm = 6{,}99\\cm\\end{aligned}"}, {"t": "Sinussatz im Dreieck ADM:", "m": "\\begin{aligned}\\dfrac{\\sin\\w DMA}{4} &= \\dfrac{\\sin 48{,}01^\\circ}{6{,}99}\\\\[2pt]&\\Rightarrow\\;\\w DMA = \\erg{25{,}17^\\circ}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(R_1\\) auf [MS] mit \\(\\overline{SR_1}=5\\) cm, Parallele zu [BC] liefert \\(P_1\\), \\(Q_1\\); F ist der Fußpunkt des Lots von D auf [MS].", "m": null}]}, {"label": "B 2.5", "pts": "4", "text": "", "img": null, "sol": [{"t": "Grundfläche \\(P_nMQ_n\\): Grundlinie \\([P_nQ_n]\\), Höhe \\([MR_n]\\) mit \\(\\overline{MR_n}=(10-x)\\) cm.", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{P_nQ_n}\\cdot\\s{MR_n}\\cdot\\s{DF}\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum S:", "m": "\\begin{aligned}\\dfrac{\\s{P_nQ_n}(x)}{12\\cm} &= \\dfrac{x\\cm}{10\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{P_nQ_n}(x) = 1{,}2x\\cm\\\\[3pt]\\dfrac{\\s{DF}}{9\\cm} &= \\dfrac{(13{,}45-4)\\cm}{13{,}45\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{DF} = 6{,}32\\cm\\end{aligned}"}, {"t": "Einsetzen und ausmultiplizieren:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot1{,}2x\\cdot(10-x)\\cdot6{,}32\\cmk\\\\[3pt]V(x) &= \\erg{(-1{,}26x^2+12{,}64x)\\cmk}\\end{aligned}"}]}, {"label": "B 2.6", "pts": "3", "text": "", "img": null, "sol": [{"t": "„Um 90 % kleiner“ heißt: noch 10 % von 180 cm³:", "m": "\\begin{aligned}-1{,}26x^2+12{,}64x &= 0{,}1\\cdot180\\\\[3pt]-1{,}26x^2+12{,}64x-18 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{-12{,}64\\pm\\sqrt{12{,}64^2-4\\cdot1{,}26\\cdot18}}{-2{,}52}\\\\[3pt]x_1 &= \\erg{1{,}72};\\quad x_2 = \\erg{8{,}31}\\end{aligned}"}]}]}, {"id": "rg21ntA3", "year": 2021, "term": "Nachtermin", "nr": "A 3", "notr": false, "pts": "6", "stmt": ["n_2021nt_A3_0"], "note": "Kein Lösungsmuster vorhanden – Lösung selbst erstellt", "subs": [{"label": "A 3.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "N liegt auf dem Halbkreis über [AD]. Nach dem Satz des Thales ist ∢AND = 90°.", "m": null}, {"t": "Wegen der Symmetrie ist das Dreieck BCN gleichschenklig-rechtwinklig; also ∢NBL = 45° und \\(\\overline{NL}=\\overline{BL}=5\\) cm:", "m": "\\begin{aligned}\\s{NL} &= \\s{LM}+\\s{MN}\\\\[3pt]5\\cm &= 3\\cm + r\\\\[2pt]&\\Rightarrow\\;r = \\erg{2\\cm}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Körper = großer Kegel (Radius 5 cm, Höhe 5 cm) − kleiner Kegel (Radius 2 cm, Höhe 2 cm) + Halbkugel (Radius 2 cm):", "m": "\\begin{aligned}V &= \\tfrac13\\cdot5^2\\cdot\\pi\\cdot5-\\tfrac13\\cdot2^2\\cdot\\pi\\cdot2+\\tfrac12\\cdot\\tfrac43\\cdot2^3\\cdot\\pi\\ \\mathrm{cm^3}\\\\[3pt]V &= (130{,}90-8{,}38+16{,}76)\\cmk = \\erg{139{,}28\\cmk}\\end{aligned}"}]}]}, {"id": "rg21ntB2", "year": 2021, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "17", "stmt": ["n_2021nt_B2_0"], "note": "Kein Lösungsmuster vorhanden – Lösung selbst erstellt", "subs": [{"label": "B 2.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "[AC] = 13 cm auf der Schrägbildachse (M bei 9 cm), [BD] unter 45° mit halber Länge (6 cm), [MS] = 8 cm senkrecht.", "m": null}, {"t": "Rechtwinklige Dreiecke AMS und MCS (\\(\\overline{MC}=4\\) cm):", "m": "\\begin{aligned}\\s{AS} &= \\sqrt{9^2+8^2}\\cm = \\erg{12{,}04\\cm}\\\\[3pt]\\tan\\w SCA &= \\dfrac84\\\\[2pt]&\\Rightarrow\\;\\w SCA = \\erg{63{,}43^\\circ}\\end{aligned}"}]}, {"label": "B 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Rechtwinkliges Dreieck AMN:", "m": "\\begin{aligned}\\tan\\w CAF &= \\dfrac{2{,}5}{9}\\\\[2pt]&\\Rightarrow\\;\\w CAF = \\erg{15{,}52^\\circ}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "5", "text": "", "img": null, "sol": [{"t": "Drachenfläche = halbes Produkt der Diagonalen. [AF] mit dem Sinussatz im Dreieck ACF:", "m": "\\begin{aligned}\\w AFC &= 180^\\circ-15{,}52^\\circ-63{,}43^\\circ = 101{,}05^\\circ\\\\[3pt]\\dfrac{\\s{AF}}{\\sin 63{,}43^\\circ} &= \\dfrac{13\\cm}{\\sin 101{,}05^\\circ}\\\\[2pt]&\\Rightarrow\\;\\s{AF} = 11{,}85\\cm\\end{aligned}"}, {"t": "[EG] mit dem Vierstreckensatz (Zentrum S, EG ∥ BD); \\(\\overline{SN}=(8-2{,}5)\\) cm:", "m": "\\begin{aligned}\\dfrac{\\s{EG}}{12\\cm} &= \\dfrac{5{,}5\\cm}{8\\cm}\\\\[2pt]&\\Rightarrow\\;\\s{EG} = 8{,}25\\cm\\end{aligned}"}, {"t": "Flächeninhalt:", "m": "\\begin{aligned}A_{AEFG} &= 0{,}5\\cdot 11{,}85\\cdot 8{,}25\\cmq = \\erg{48{,}88\\cmq}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "\\(P_1\\) auf [AS] mit \\(\\overline{AP_1}=7\\) cm; Lot von \\(P_1\\) auf [AF] liefert \\(Q_1\\).", "m": null}, {"t": "Im rechtwinkligen Dreieck \\(AQ_nP_n\\) ist ∢SAF der Winkel bei A:", "m": "\\begin{aligned}\\tan\\w SAM &= \\dfrac89\\\\[2pt]&\\Rightarrow\\;\\w SAM = 41{,}63^\\circ\\\\[3pt]\\w SAF &= 41{,}63^\\circ-15{,}52^\\circ = 26{,}11^\\circ\\\\[3pt]\\s{P_nQ_n}(x) &= x\\cdot\\sin 26{,}11^\\circ\\cm = \\erg{0{,}44\\cdot x\\cm}\\end{aligned}"}]}, {"label": "B 2.5", "pts": "2", "text": "", "img": null, "sol": [{"t": "Volumen gleich 14 cm³ setzen:", "m": "\\begin{aligned}\\tfrac13\\cdot 48{,}88\\cdot 0{,}44x &= 14\\\\[3pt]x &= \\dfrac{3\\cdot14}{48{,}88\\cdot0{,}44} = \\erg{1{,}95}\\end{aligned}"}]}]}, {"id": "rg1", "year": 2022, "term": "Haupttermin", "nr": "A 1", "notr": false, "pts": "5", "intro": "<p>Die Vorlage eines Kerzenhalters für kugelförmige Kerzen ist ein Rotationskörper mit der Rotationsachse MN. Nebenstehende Skizze zeigt den Axialschnitt dieses Rotationskörpers. Der Punkt C ist der Schnittpunkt der Geraden AB und ED.</p><p>Es gilt: |<span class=\"ov\">AE</span>| = 9 cm; |<span class=\"ov\">GF</span>| = 5 cm; |<span class=\"ov\">BD</span>| = 5 cm; |<span class=\"ov\">CN</span>| = 5,5 cm; r = |<span class=\"ov\">MG</span>| = |<span class=\"ov\">MF</span>|; AE ∥ BD.</p>", "fig": "f01", "figw": 4.6, "bigfig": false, "subs": [{"label": "A 1.1", "pts": "4", "text": "<p>Berechne das Volumen des Rotationskörpers. Runde auf zwei Stellen nach dem Komma.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">CM</span>| = 9,9 cm; Ergebnis: V = 141,21 cm<sup>3</sup>]</p>", "img": null, "sol": [{"t": "Der Körper besteht aus einem großen Kegel (Radius \\(\\s{ME}\\), Höhe \\(\\s{CM}\\)). Davon werden ein kleiner Kegel (Radius \\(\\s{ND}\\), Höhe \\(\\s{CN}\\)) und eine Halbkugel (Radius \\(\\s{MF}\\)) abgezogen.", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\s{ME}^2\\cdot\\pi\\cdot\\s{CM}-\\tfrac13\\cdot\\s{ND}^2\\cdot\\pi\\cdot\\s{CN}-\\tfrac12\\cdot\\tfrac43\\cdot\\s{MF}^3\\cdot\\pi\\end{aligned}"}, {"t": "Die Radien sind jeweils die Hälfte der Durchmesser.", "m": "\\begin{aligned}\\s{ME} &= 0{,}5\\cdot 9\\cm = 4{,}5\\cm\\\\[3pt]\\s{ND} &= 0{,}5\\cdot 5\\cm = 2{,}5\\cm\\\\[3pt]\\s{MF} &= 0{,}5\\cdot 5\\cm = 2{,}5\\cm\\end{aligned}"}, {"t": "Die Höhe \\(\\s{CM}\\) des großen Kegels erhältst du mit dem Vierstreckensatz, weil \\(AE \\parallel BD\\) gilt.", "m": "\\begin{aligned}\\dfrac{\\s{CM}}{\\s{CN}} &= \\dfrac{\\s{ME}}{\\s{ND}}\\\\[3pt]\\dfrac{\\s{CM}}{5{,}5\\cm} &= \\dfrac{4{,}5\\cm}{2{,}5\\cm}\\\\[3pt]\\s{CM} &= 9{,}9\\cm\\end{aligned}"}, {"t": "Werte einsetzen und ausrechnen.", "m": "\\begin{aligned}V &= \\left(\\tfrac13\\cdot 4{,}5^2\\cdot\\pi\\cdot 9{,}9-\\tfrac13\\cdot 2{,}5^2\\cdot\\pi\\cdot 5{,}5-\\tfrac12\\cdot\\tfrac43\\cdot 2{,}5^3\\cdot\\pi\\right)\\cmk\\\\[3pt]V &= \\erg{141{,}21\\cmk}\\end{aligned}"}]}, {"label": "A 1.2", "pts": "1", "text": "<p>Der Kerzenhalter soll aus Marmor gefertigt werden. 1 cm<sup>3</sup> des verwendeten Marmors hat eine Masse von 2,7 g.</p><p>Berechne die Masse des Kerzenhalters. Runde auf ganze Gramm.</p>", "img": null, "sol": [{"t": "Masse = Volumen · Masse pro cm³.", "m": "\\begin{aligned}m &= 141{,}21\\cdot 2{,}7\\,\\mathrm{g}\\\\[3pt]m &= \\erg{381\\,\\mathrm{g}}\\end{aligned}"}]}]}, {"id": "rg2", "year": 2022, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "17", "intro": "<p>Die nebenstehende Skizze zeigt ein Schrägbild des geraden Prismas ABCDEF, dessen Grundfläche das gleichschenklige Dreieck ABC mit der Basis <span class=\"ov\">AB</span> ist. M ist der Mittelpunkt der Strecke <span class=\"ov\">AB</span>.</p><p>Es gilt: |<span class=\"ov\">CM</span>| = 8 cm; |<span class=\"ov\">CF</span>| = 11 cm; |<span class=\"ov\">AB</span>| = 10 cm.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f02", "figw": 3.6, "bigfig": false, "subs": [{"label": "B 2.1", "pts": "4", "text": "<p>Zeichne das Schrägbild des Prismas ABCDEF mit der Strecke <span class=\"ov\">FM</span>, wobei die Strecke <span class=\"ov\">CM</span> auf der Schrägbildachse und der Punkt C links vom Punkt M liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">FM</span> und das Maß des Winkels CFM.</p><p class=\"hint\">[Teilergebnisse: |<span class=\"ov\">FM</span>| = 13,60 cm; ∢CFM = 36,03°]</p>", "img": null, "sol": [{"t": "Zeichne zuerst die Grundfläche: \\([CM]\\) mit 8 cm auf die Schrägbildachse, dann \\([AB]\\) durch M unter 45° mit halber Länge (\\(q=\\tfrac12\\): je 2,5 cm). Senkrecht nach oben kommen die Kanten mit 11 cm.", "m": null}, {"t": "Das Dreieck CMF ist rechtwinklig bei C (die Kante \\([CF]\\) steht senkrecht auf der Grundfläche). Satz des Pythagoras:", "m": "\\begin{aligned}\\s{FM}^2 &= \\s{CM}^2+\\s{CF}^2\\\\[3pt]\\s{FM} &= \\sqrt{8^2+11^2}\\cm\\\\[3pt]\\s{FM} &= \\erg{13{,}60\\cm}\\end{aligned}"}, {"t": "Im rechtwinkligen Dreieck CMF ist \\([CM]\\) die Gegenkathete und \\([CF]\\) die Ankathete von ∢CFM.", "m": "\\begin{aligned}\\tan\\w CFM &= \\dfrac{\\s{CM}}{\\s{CF}} = \\dfrac{8}{11}\\\\[3pt]\\w CFM &= \\erg{36{,}03^\\circ}\\end{aligned}"}], "solimg": "rg_sol_02", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 2.2", "pts": "3", "text": "<p>Für Punkte P<sub>n</sub> auf der Strecke <span class=\"ov\">FM</span> gilt: |<span class=\"ov\">FP<sub>n</sub></span>|(x) = x cm (x ∈ IR; x ∈ [0; 13,60[).</p><p>Zeichne das Dreieck CP<sub>1</sub>F für x = 4 in das Schrägbild zu B 2.1 ein.</p><p>Berechne sodann den Flächeninhalt des Dreiecks CP<sub>1</sub>F sowie die Länge der Strecke <span class=\"ov\">CP<sub>1</sub></span>.</p>", "img": null, "sol": [{"t": "Für x = 4 gilt \\(\\s{FP_1}=4\\cm\\). Trage den Punkt \\(P_1\\) auf \\([FM]\\) ab und zeichne das Dreieck \\(CP_1F\\).", "m": null}, {"t": "Im Dreieck \\(CP_1F\\) kennst du zwei Seiten und den eingeschlossenen Winkel ∢CFM. Flächenformel mit dem Sinus:", "m": "\\begin{aligned}A_{CP_1F} &= 0{,}5\\cdot\\s{CF}\\cdot\\s{FP_1}\\cdot\\sin\\w CFM\\\\[3pt]A_{CP_1F} &= 0{,}5\\cdot 11\\cdot 4\\cdot\\sin 36{,}03^\\circ\\cmq\\\\[3pt]A_{CP_1F} &= \\erg{12{,}94\\cmq}\\end{aligned}"}, {"t": "Die Seite \\([CP_1]\\) liegt dem Winkel ∢CFM gegenüber, also Kosinussatz:", "m": "\\begin{aligned}\\s{CP_1}^2 &= \\s{CF}^2+\\s{FP_1}^2-2\\cdot\\s{CF}\\cdot\\s{FP_1}\\cdot\\cos\\w CFM\\\\[3pt]\\s{CP_1} &= \\sqrt{11^2+4^2-2\\cdot 11\\cdot 4\\cdot\\cos 36{,}03^\\circ}\\cm\\\\[3pt]\\s{CP_1} &= \\erg{8{,}11\\cm}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "1", "text": "<p>Das Dreieck ABC ist die Grundfläche von Pyramiden ABCP<sub>n</sub> mit den Höhen <span class=\"ov\">P<sub>n</sub>K<sub>n</sub></span>, wobei K<sub>n</sub> ∈ <span class=\"ov\">CM</span> gilt.</p><p>Zeichne die Pyramide ABCP<sub>1</sub> und die Höhe <span class=\"ov\">P<sub>1</sub>K<sub>1</sub></span> in das Schrägbild zu B 2.1 ein.</p>", "img": null, "sol": [{"t": "Verbinde \\(P_1\\) mit A, B und C. Die Höhe \\([P_1K_1]\\) ist parallel zu \\([CF]\\) (senkrecht nach unten auf \\([CM]\\)).", "m": null}]}, {"label": "B 2.4", "pts": "3", "text": "<p>Zeige, dass sich das Volumen V der Pyramiden ABCP<sub>n</sub> in Abhängigkeit von x wie folgt darstellen lässt: V(x) = (146,67 − 10,80x) cm<sup>3</sup>.</p>", "img": null, "sol": [{"t": "Grundfläche ist das Dreieck ABC mit Grundseite \\([AB]\\) und Höhe \\([CM]\\). Die Pyramidenhöhe ist \\([P_nK_n]\\).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{AB}\\cdot\\s{CM}\\cdot\\s{P_nK_n}\\end{aligned}"}, {"t": "Die Höhe \\(\\s{P_nK_n}\\) bestimmst du mit dem Vierstreckensatz in der Figur mit Zentrum M, weil \\(P_nK_n \\parallel FC\\). Es gilt \\(\\s{MP_n}=(13{,}60-x)\\cm\\).", "m": "\\begin{aligned}\\dfrac{\\s{P_nK_n}(x)}{\\s{CF}} &= \\dfrac{\\s{MP_n}(x)}{\\s{MF}}\\\\[3pt]\\dfrac{\\s{P_nK_n}(x)}{11\\cm} &= \\dfrac{(13{,}60-x)\\cm}{13{,}60\\cm}\\\\[3pt]\\s{P_nK_n}(x) &= (11-0{,}81x)\\cm\\end{aligned}"}, {"t": "Einsetzen und vereinfachen.", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 10\\cdot 8\\cdot(11-0{,}81x)\\cmk\\\\[3pt]V(x) &= \\erg{(146{,}67-10{,}80x)\\cmk}\\end{aligned}"}]}, {"label": "B 2.5", "pts": "2", "text": "<p>Das Volumen der Pyramide ABCP<sub>2</sub> beträgt 15 % des Volumens des Prismas ABCDEF.</p><p>Ermittle durch Rechnung den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Volumen des Prismas: Grundfläche · Höhe.", "m": "\\begin{aligned}V_{ABCDEF} &= 0{,}5\\cdot 10\\cdot 8\\cdot 11\\cmk = 440\\cmk\\end{aligned}"}, {"t": "15 % davon gleichsetzen mit V(x) und nach x auflösen.", "m": "\\begin{aligned}146{,}67-10{,}80x &= 0{,}15\\cdot 440\\\\[3pt]146{,}67-10{,}80x &= 66\\\\[3pt]-10{,}80x &= -80{,}67\\\\[3pt]x &= \\erg{7{,}47}\\end{aligned}"}]}, {"label": "B 2.6", "pts": "4", "text": "<p>Unter den Punkten P<sub>n</sub> hat der Punkt P<sub>0</sub> die kürzeste Entfernung zu C.</p><p>Zeichne die Pyramide ABCP<sub>0</sub> in das Schrägbild zu B 2.1 ein.</p><p>Berechne sodann das Maß des Winkels AP<sub>0</sub>B.</p>", "img": null, "sol": [{"t": "Die kürzeste Entfernung von C zu \\([FM]\\) ist das Lot. \\(P_0\\) ist also der Lotfußpunkt von C auf \\([FM]\\). Zeichne die Pyramide \\(ABCP_0\\) ein.", "m": null}, {"t": "Im rechtwinkligen Dreieck \\(CP_0F\\) ist \\([FP_0]\\) die Ankathete von ∢CFM.", "m": "\\begin{aligned}\\cos\\w CFM &= \\dfrac{\\s{FP_0}}{\\s{CF}}\\\\[3pt]\\s{FP_0} &= 11\\cm\\cdot\\cos 36{,}03^\\circ = 8{,}90\\cm\\end{aligned}"}, {"t": "Das Dreieck \\(ABP_0\\) ist gleichschenklig, \\([P_0M]\\) halbiert den Winkel. Im rechtwinkligen Dreieck \\(AMP_0\\) gilt:", "m": "\\begin{aligned}\\tan\\w AP_0M &= \\dfrac{\\s{AM}}{\\s{MP_0}} = \\dfrac{0{,}5\\cdot 10}{13{,}60-8{,}90}\\\\[3pt]\\w AP_0M &= 46{,}77^\\circ\\end{aligned}"}, {"t": "Den ganzen Winkel bekommst du durch Verdoppeln.", "m": "\\begin{aligned}\\w AP_0B &= 2\\cdot 46{,}77^\\circ = \\erg{93{,}54^\\circ}\\end{aligned}"}]}]}, {"id": "rg3", "year": 2022, "term": "Nachtermin", "nr": "A 1", "notr": false, "pts": "5", "intro": "<p>Nebenstehende Skizze zeigt den Axialschnitt eines Rotationskörpers mit der Rotationsachse NM. Der Punkt F ist der Schnittpunkt der Geraden AI und BC.</p><p>Es gilt: |<span class=\"ov\">AB</span>| = 8 cm; |<span class=\"ov\">FK</span>| = 1,7 cm; |<span class=\"ov\">CD</span>| = 3 cm; |<span class=\"ov\">DE</span>| = 0,5 cm; r = |<span class=\"ov\">ME</span>| = |<span class=\"ov\">MG</span>| = 2 cm; IH ∥ NM ∥ CD.</p>", "fig": "f03", "figw": 6.0, "bigfig": false, "subs": [{"label": "A 1", "pts": "5", "text": "<p>Berechne das Volumen des Rotationskörpers. Runde auf zwei Stellen nach dem Komma.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">FN</span>| = 2,72 cm]</p>", "img": null, "sol": [{"t": "Zerlege den Körper: großer Kegel (Radius \\(\\s{AN}\\), Höhe \\(\\s{FN}\\)) minus kleiner Kegel (Radius \\(\\s{IK}\\), Höhe \\(\\s{FK}\\)) plus Zylinder (Radius \\(\\s{IK}\\), Höhe \\(\\s{CD}\\)) minus Halbkugel (Radius r).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\s{AN}^2\\cdot\\pi\\cdot\\s{FN}-\\tfrac13\\cdot\\s{IK}^2\\cdot\\pi\\cdot\\s{FK}+\\s{IK}^2\\cdot\\pi\\cdot\\s{CD}-\\tfrac12\\cdot\\tfrac43\\cdot r^3\\cdot\\pi\\end{aligned}"}, {"t": "Radien bestimmen: \\(\\s{AN}\\) ist der halbe Durchmesser \\(\\s{AB}\\), \\(\\s{IK}\\) ist Kugelradius plus \\(\\s{DE}\\).", "m": "\\begin{aligned}\\s{AN} &= 0{,}5\\cdot 8\\cm = 4\\cm\\\\[3pt]\\s{IK} &= (2+0{,}5)\\cm = 2{,}5\\cm\\end{aligned}"}, {"t": "Die Kegelhöhe \\(\\s{FN}\\) folgt aus dem Vierstreckensatz mit Zentrum F.", "m": "\\begin{aligned}\\dfrac{\\s{FN}}{\\s{FK}} &= \\dfrac{\\s{AN}}{\\s{IK}}\\\\[3pt]\\dfrac{\\s{FN}}{1{,}7\\cm} &= \\dfrac{4\\cm}{2{,}5\\cm}\\\\[3pt]\\s{FN} &= 2{,}72\\cm\\end{aligned}"}, {"t": "Alles einsetzen.", "m": "\\begin{aligned}V &= \\left(\\tfrac13\\cdot 4^2\\cdot\\pi\\cdot 2{,}72-\\tfrac13\\cdot 2{,}5^2\\cdot\\pi\\cdot 1{,}7+2{,}5^2\\cdot\\pi\\cdot 3-\\tfrac12\\cdot\\tfrac43\\cdot 2^3\\cdot\\pi\\right)\\cmk\\\\[3pt]V &= \\erg{76{,}60\\cmk}\\end{aligned}"}]}]}, {"id": "rg4", "year": 2022, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "17", "intro": "<p>Die nebenstehende Skizze zeigt ein Schrägbild der Pyramide ABCDS mit der Höhe <span class=\"ov\">MS</span>, deren Grundfläche die Raute ABCD mit dem Diagonalenschnittpunkt M ist.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 12 cm; |<span class=\"ov\">BD</span>| = 10 cm; |<span class=\"ov\">MS</span>| = 8 cm.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f04", "figw": 4.8, "bigfig": false, "subs": [{"label": "B 2.1", "pts": "4", "text": "<p>Zeichne das Schrägbild der Pyramide ABCDS, wobei die Strecke <span class=\"ov\">AC</span> auf der Schrägbildachse und der Punkt A links vom Punkt C liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">CS</span> und das Maß des Winkels MSC.</p><p class=\"hint\">[Teilergebnisse: |<span class=\"ov\">CS</span>| = 10 cm; ∢MSC = 36,87°]</p>", "img": null, "sol": [{"t": "Zeichne \\([AC]\\) mit 12 cm auf die Schrägbildachse. \\([BD]\\) geht durch M unter 45° und wird halbiert dargestellt (je 2,5 cm). Die Höhe \\([MS]\\) steht senkrecht mit 8 cm.", "m": null}, {"t": "Im rechtwinkligen Dreieck MCS gilt der Satz des Pythagoras mit \\(\\s{MC}=0{,}5\\cdot 12\\cm\\).", "m": "\\begin{aligned}\\s{CS}^2 &= \\s{MC}^2+\\s{MS}^2\\\\[3pt]\\s{CS} &= \\sqrt{(0{,}5\\cdot 12)^2+8^2}\\cm\\\\[3pt]\\s{CS} &= \\erg{10\\cm}\\end{aligned}"}, {"t": "\\([MC]\\) ist Gegenkathete, \\([MS]\\) Ankathete von ∢MSC.", "m": "\\begin{aligned}\\tan\\w MSC &= \\dfrac{\\s{MC}}{\\s{MS}} = \\dfrac{0{,}5\\cdot 12}{8}\\\\[3pt]\\w MSC &= \\erg{36{,}87^\\circ}\\end{aligned}"}], "solimg": "rg_sol_04", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 2.2", "pts": "4", "text": "<p>Der Punkt T liegt auf der Strecke <span class=\"ov\">CS</span> mit |<span class=\"ov\">ST</span>| = 3 cm. Punkte P<sub>n</sub> liegen auf der Strecke <span class=\"ov\">MS</span> mit |<span class=\"ov\">MP<sub>n</sub></span>| = x cm (x ∈ IR<sub>0</sub><sup>+</sup>; x ∈ [0; 8[). Zusammen mit den Punkten T und S bilden sie Dreiecke TSP<sub>n</sub>.</p><p>Zeichne die Strecke <span class=\"ov\">P<sub>1</sub>T</span> für x = 2 in das Schrägbild zu B 2.1 ein.</p><p>Ermittle sodann rechnerisch den Flächeninhalt des Dreiecks TSP<sub>1</sub> sowie das Maß des Winkels TP<sub>1</sub>S.</p>", "img": null, "sol": [{"t": "Für x = 2 liegt \\(P_1\\) 2 cm über M, also \\(\\s{SP_1}=(8-2)\\cm=6\\cm\\). Zeichne \\([P_1T]\\) ein.", "m": null}, {"t": "Im Dreieck \\(TSP_1\\) sind \\(\\s{SP_1}\\), \\(\\s{ST}\\) und der eingeschlossene Winkel ∢MSC bekannt.", "m": "\\begin{aligned}A_{TSP_1} &= 0{,}5\\cdot\\s{SP_1}\\cdot\\s{ST}\\cdot\\sin\\w MSC\\\\[3pt]A_{TSP_1} &= 0{,}5\\cdot(8-2)\\cdot 3\\cdot\\sin 36{,}87^\\circ\\cmq\\\\[3pt]A_{TSP_1} &= \\erg{5{,}40\\cmq}\\end{aligned}"}, {"t": "Für den Winkel brauchst du zuerst \\(\\s{P_1T}\\) mit dem Kosinussatz.", "m": "\\begin{aligned}\\s{P_1T} &= \\sqrt{(8-2)^2+3^2-2\\cdot(8-2)\\cdot 3\\cdot\\cos 36{,}87^\\circ}\\cm\\\\[3pt]\\s{P_1T} &= 4{,}02\\cm\\end{aligned}"}, {"t": "Dann Sinussatz: ∢TP₁S liegt gegenüber von \\([ST]\\), ∢MSC gegenüber von \\([P_1T]\\).", "m": "\\begin{aligned}\\dfrac{\\sin\\w TP_1S}{\\s{ST}} &= \\dfrac{\\sin\\w MSC}{\\s{P_1T}}\\\\[3pt]\\dfrac{\\sin\\w TP_1S}{3\\cm} &= \\dfrac{\\sin 36{,}87^\\circ}{4{,}02\\cm}\\\\[3pt]\\w TP_1S &= \\erg{26{,}60^\\circ}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "2", "text": "<p>Für den Winkel STP<sub>2</sub> gilt: ∢STP<sub>2</sub> = 90°.</p><p>Zeichne die Strecke <span class=\"ov\">P<sub>2</sub>T</span> in das Schrägbild zu B 2.1 ein und berechne den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Wenn ∢STP₂ = 90° ist, ist das Dreieck \\(STP_2\\) rechtwinklig bei T. Dann ist \\([ST]\\) die Ankathete von ∢MSC und \\([SP_2]\\) die Hypotenuse mit \\(\\s{SP_2}=(8-x)\\cm\\).", "m": "\\begin{aligned}\\cos\\w MSC &= \\dfrac{\\s{ST}}{\\s{SP_2}}\\\\[3pt]\\cos 36{,}87^\\circ &= \\dfrac{3}{8-x}\\\\[3pt]8-x &= \\dfrac{3}{\\cos 36{,}87^\\circ} = 3{,}75\\\\[3pt]x &= \\erg{4{,}25}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "1", "text": "<p>Die Punkte P<sub>n</sub> sind Mittelpunkte von Strecken <span class=\"ov\">Q<sub>n</sub>R<sub>n</sub></span>, wobei gilt: Q<sub>n</sub> ∈ <span class=\"ov\">BS</span>, R<sub>n</sub> ∈ <span class=\"ov\">DS</span> und <span class=\"ov\">Q<sub>n</sub>R<sub>n</sub></span> ∥ <span class=\"ov\">BD</span>. Die Dreiecke Q<sub>n</sub>R<sub>n</sub>S sind Grundflächen von Pyramiden Q<sub>n</sub>R<sub>n</sub>ST, wobei T die Spitze der Pyramiden mit dem Höhenfußpunkt H ∈ <span class=\"ov\">MS</span> ist.</p><p>Zeichne die Pyramide Q<sub>1</sub>R<sub>1</sub>ST und die Pyramidenhöhe <span class=\"ov\">HT</span> in das Schrägbild zu B 2.1 ein.</p>", "img": null, "sol": [{"t": "Zeichne durch \\(P_1\\) die Parallele zu \\([BD]\\); sie schneidet \\([BS]\\) in \\(Q_1\\) und \\([DS]\\) in \\(R_1\\). Verbinde \\(Q_1\\), \\(R_1\\), S mit T. Die Höhe \\([HT]\\) ist parallel zu \\([MC]\\).", "m": null}]}, {"label": "B 2.5", "pts": "4", "text": "<p>Zeige, dass für das Volumen V der Pyramiden Q<sub>n</sub>R<sub>n</sub>ST in Abhängigkeit von x gilt: V(x) = (0,375x<sup>2</sup> − 6x + 24) cm<sup>3</sup>.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">Q<sub>n</sub>R<sub>n</sub></span>|(x) = (10 − 1,25x) cm]</p>", "img": null, "sol": [{"t": "Die Grundfläche \\(Q_nR_nS\\) ist ein Dreieck mit Grundseite \\([Q_nR_n]\\) und Höhe \\([SP_n]\\). Die Pyramidenhöhe ist \\([HT]\\).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{Q_nR_n}\\cdot\\s{SP_n}\\cdot\\s{HT}\\end{aligned}"}, {"t": "\\(\\s{Q_nR_n}\\) mit dem Vierstreckensatz (Zentrum S, \\(Q_nR_n\\parallel BD\\)).", "m": "\\begin{aligned}\\dfrac{\\s{Q_nR_n}(x)}{\\s{BD}} &= \\dfrac{\\s{SP_n}(x)}{\\s{SM}}\\\\[3pt]\\dfrac{\\s{Q_nR_n}(x)}{10\\cm} &= \\dfrac{(8-x)\\cm}{8\\cm}\\\\[3pt]\\s{Q_nR_n}(x) &= (10-1{,}25x)\\cm\\end{aligned}"}, {"t": "\\(\\s{HT}\\) ebenfalls mit dem Vierstreckensatz (Zentrum S, \\(HT\\parallel MC\\)).", "m": "\\begin{aligned}\\dfrac{\\s{HT}}{\\s{MC}} &= \\dfrac{\\s{ST}}{\\s{SC}}\\\\[3pt]\\dfrac{\\s{HT}}{0{,}5\\cdot 12\\cm} &= \\dfrac{3\\cm}{10\\cm}\\\\[3pt]\\s{HT} &= 1{,}8\\cm\\end{aligned}"}, {"t": "Einsetzen und ausmultiplizieren.", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot(10-1{,}25x)\\cdot(8-x)\\cdot 1{,}8\\cmk\\\\[3pt]V(x) &= 0{,}3\\cdot(80-10x-10x+1{,}25x^2)\\cmk\\\\[3pt]V(x) &= 0{,}3\\cdot(1{,}25x^2-20x+80)\\cmk\\\\[3pt]V(x) &= \\erg{(0{,}375x^2-6x+24)\\cmk}\\end{aligned}"}]}, {"label": "B 2.6", "pts": "2", "text": "<p>Unter den Pyramiden Q<sub>n</sub>R<sub>n</sub>ST hat die Pyramide Q<sub>3</sub>R<sub>3</sub>ST das maximale Volumen.</p><p>Gib den zugehörigen Wert für x und das maximale Volumen an.</p>", "img": null, "sol": [{"t": "Der Graph von V ist eine nach oben geöffnete Parabel mit dem Scheitel bei \\(x=8\\) (\\(V=0{,}375(x-8)^2\\)). Auf \\([0;8[\\) wird V also kleiner, je größer x ist. Das maximale Volumen liegt am linken Rand bei x = 0.", "m": "\\begin{aligned}V(0) &= 24\\cmk\\\\[3pt]&\\Rightarrow\\; x=0;\\; V_{\\max}=\\erg{24\\cmk}\\end{aligned}"}]}]}, {"id": "rg5", "year": 2023, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "4", "intro": "<p>Nebenstehende Skizze zeigt den Axialschnitt eines Rotationskörpers mit der Rotationsachse DJ.</p><p>Es gilt: |<span class=\"ov\">CM</span>| = |<span class=\"ov\">BL</span>| = r = 3 cm; |<span class=\"ov\">ML</span>| = 1,5 cm; |<span class=\"ov\">JL</span>| = 6 cm; |<span class=\"ov\">KL</span>| = 1 cm.</p>", "fig": "f05", "figw": 4.0, "bigfig": false, "subs": [{"label": "B 2", "pts": "4", "text": "<p>Berechne die Länge der Strecke <span class=\"ov\">AK</span> und das Volumen des Rotationskörpers. Runde auf zwei Stellen nach dem Komma.</p><p class=\"hint\">[Teilergebnis: |<span class=\"ov\">AK</span>| = 2,5 cm]</p>", "img": null, "sol": [{"t": "\\(\\s{AK}\\) mit dem Vierstreckensatz: Die Kegelspitze liegt bei J. \\([AK]\\) liegt im Abstand \\(\\s{JK}=(6-1)\\cm\\) von der Spitze, \\([BL]\\) im Abstand 6 cm.", "m": "\\begin{aligned}\\dfrac{\\s{AK}}{\\s{BL}} &= \\dfrac{\\s{JK}}{\\s{JL}}\\\\[3pt]\\dfrac{\\s{AK}}{3\\cm} &= \\dfrac{(6-1)\\cm}{6\\cm}\\\\[3pt]\\s{AK} &= \\erg{2{,}5\\cm}\\end{aligned}"}, {"t": "Der Körper besteht aus Halbkugel (r = 3 cm), Zylinder (r = 3 cm, h = 1,5 cm) und Kegel (r = 3 cm, h = 6 cm). Der kleine Kegel (r = 2,5 cm, h = 5 cm) wird abgezogen.", "m": "\\begin{aligned}V &= \\left[\\tfrac12\\cdot\\tfrac43\\cdot 3^3\\cdot\\pi+3^2\\cdot\\pi\\cdot 1{,}5+\\tfrac13\\cdot 3^2\\cdot\\pi\\cdot 6-\\tfrac13\\cdot 2{,}5^2\\cdot\\pi\\cdot(6-1)\\right]\\cmk\\\\[3pt]V &= \\erg{122{,}78\\cmk}\\end{aligned}"}]}]}, {"id": "rg6", "year": 2023, "term": "Haupttermin", "nr": "B 4", "notr": false, "pts": "16", "intro": "<p>Die nebenstehende Skizze zeigt ein Schrägbild der Pyramide ABCDS mit der Höhe <span class=\"ov\">AS</span>, deren Grundfläche die Raute ABCD ist.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 11 cm; |<span class=\"ov\">BD</span>| = 6 cm; |<span class=\"ov\">AS</span>| = 9 cm.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f06", "figw": 5.4, "bigfig": false, "subs": [{"label": "B 4.1", "pts": "4", "text": "<p>Zeichne das Schrägbild der Pyramide ABCDS, wobei die Strecke <span class=\"ov\">AC</span> auf der Schrägbildachse und der Punkt A links vom Punkt C liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">CS</span> und das Maß des Winkels SCA.</p><p class=\"hint\">[Teilergebnisse: |<span class=\"ov\">CS</span>| = 14,21 cm; ∢SCA = 39,29°]</p>", "img": null, "sol": [{"t": "\\([AC]\\) mit 11 cm auf die Schrägbildachse, \\([BD]\\) durch die Mitte von \\([AC]\\) unter 45° mit halber Länge (je 1,5 cm). Die Höhe \\([AS]\\) steht in A senkrecht (9 cm).", "m": null}, {"t": "Das Dreieck ACS ist rechtwinklig bei A.", "m": "\\begin{aligned}\\s{CS} &= \\sqrt{\\s{AC}^2+\\s{AS}^2} = \\sqrt{11^2+9^2}\\cm\\\\[3pt]\\s{CS} &= \\erg{14{,}21\\cm}\\end{aligned}"}, {"t": "\\([AS]\\) ist Gegenkathete, \\([AC]\\) Ankathete von ∢SCA.", "m": "\\begin{aligned}\\tan\\w SCA &= \\dfrac{\\s{AS}}{\\s{AC}} = \\dfrac{9}{11}\\\\[3pt]\\w SCA &= \\erg{39{,}29^\\circ}\\end{aligned}"}], "solimg": "rg_sol_06", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 4.2", "pts": "4", "text": "<p>Für Punkte P<sub>n</sub> ∈ <span class=\"ov\">CS</span> gilt: |<span class=\"ov\">SP<sub>n</sub></span>|(x) = x cm (x ∈ IR; 0 ≤ x &lt; 14,21). Die Punkte P<sub>n</sub> sind die Spitzen von Pyramiden ABDP<sub>n</sub> mit den Höhen <span class=\"ov\">P<sub>n</sub>F<sub>n</sub></span>.</p><p>Zeichne für x = 3 die Pyramide ABDP<sub>1</sub> und die Höhe <span class=\"ov\">P<sub>1</sub>F<sub>1</sub></span> in das Schrägbild zu B 4.1 ein.</p><p>Berechne sodann das Maß des Winkels SP<sub>1</sub>A.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">AP<sub>1</sub></span>| = 7,47 cm]</p>", "img": null, "sol": [{"t": "Trage \\(\\s{SP_1}=3\\cm\\) auf \\([SC]\\) ab. Verbinde \\(P_1\\) mit A, B, D. Die Höhe \\([P_1F_1]\\) ist parallel zu \\([AS]\\).", "m": null}, {"t": "Winkel ∢ASC im rechtwinkligen Dreieck ACS:", "m": "\\begin{aligned}\\w ASP_1 &= 180^\\circ-90^\\circ-39{,}29^\\circ = 50{,}71^\\circ\\end{aligned}"}, {"t": "\\(\\s{AP_1}\\) mit dem Kosinussatz im Dreieck \\(ASP_1\\).", "m": "\\begin{aligned}\\s{AP_1} &= \\sqrt{9^2+3^2-2\\cdot 9\\cdot 3\\cdot\\cos 50{,}71^\\circ}\\cm = 7{,}47\\cm\\end{aligned}"}, {"t": "Sinussatz für ∢SP₁A (gegenüber von \\([AS]\\)).", "m": "\\begin{aligned}\\dfrac{\\sin\\w SP_1A}{\\s{AS}} &= \\dfrac{\\sin\\w ASP_1}{\\s{AP_1}}\\\\[3pt]\\dfrac{\\sin\\w SP_1A}{9\\cm} &= \\dfrac{\\sin 50{,}71^\\circ}{7{,}47\\cm}\\end{aligned}"}, {"t": "Der Taschenrechner liefert 68,82°. Weil \\([AS]\\) die längste Seite im Dreieck ist, muss der gegenüberliegende Winkel stumpf sein. Du nimmst den zweiten Wert 180° − 68,82°.", "m": "\\begin{aligned}\\w SP_1A &= 180^\\circ-68{,}82^\\circ = \\erg{111{,}18^\\circ}\\end{aligned}"}]}, {"label": "B 4.3", "pts": "3", "text": "<p>Zeige, dass für das Volumen der Pyramiden ABDP<sub>n</sub> in Abhängigkeit von x gilt: V(x) = (−3,47x + 49,5) cm<sup>3</sup>.</p>", "img": null, "sol": [{"t": "Grundfläche ABD ist die halbe Raute: \\(\\tfrac12\\cdot\\s{BD}\\cdot\\tfrac12\\cdot\\s{AC}\\). Höhe ist \\([P_nF_n]\\).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{BD}\\cdot\\tfrac12\\cdot\\s{AC}\\cdot\\s{P_nF_n}\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum C (\\(P_nF_n\\parallel SA\\)), \\(\\s{CP_n}=(14{,}21-x)\\cm\\).", "m": "\\begin{aligned}\\dfrac{\\s{P_nF_n}}{9\\cm} &= \\dfrac{(14{,}21-x)\\cm}{14{,}21\\cm}\\\\[3pt]\\s{P_nF_n}(x) &= (9-0{,}63x)\\cm\\end{aligned}"}, {"t": "Einsetzen.", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 6\\cdot\\tfrac12\\cdot 11\\cdot(9-0{,}63x)\\cmk\\\\[3pt]V(x) &= \\erg{(-3{,}47x+49{,}5)\\cmk}\\end{aligned}"}]}, {"label": "B 4.4", "pts": "3", "text": "<p>Ermittle rechnerisch, für welchen Wert von x das Volumen der zugehörigen Pyramide ABDP<sub>2</sub> um 80 % kleiner ist als das Volumen der Pyramide ABCDS.</p>", "img": null, "sol": [{"t": "Volumen der Pyramide ABCDS:", "m": "\\begin{aligned}V_{ABCDS} &= \\tfrac13\\cdot\\tfrac12\\cdot 6\\cdot 11\\cdot 9\\cmk = 99\\cmk\\end{aligned}"}, {"t": "„Um 80 % kleiner“ heißt: Es bleiben 20 % übrig.", "m": "\\begin{aligned}-3{,}47x+49{,}5 &= (1-0{,}8)\\cdot 99\\\\[3pt]-3{,}47x+49{,}5 &= 19{,}8\\\\[3pt]-3{,}47x &= -29{,}7\\\\[3pt]x &= \\erg{8{,}56}\\end{aligned}"}]}, {"label": "B 4.5", "pts": "2", "text": "<p>Unter den Pyramiden ABDP<sub>n</sub> hat die Pyramide ABDP<sub>0</sub> das größte Volumen.</p><p>Begründe, weshalb das Volumen der Pyramide ABDP<sub>0</sub> halb so groß ist wie das Volumen der Pyramide ABCDS.</p>", "img": null, "sol": [{"t": "V(x) wird größer, je kleiner x ist. Das Maximum liegt also bei x = 0, dort ist \\(P_0=S\\). Dann haben ABCDS und \\(ABDP_0\\) die gleiche Höhe \\([AS]\\). Die Grundfläche ABD ist genau die halbe Raute ABCD.", "m": "\\begin{aligned}A_{ABD} &= 0{,}5\\cdot A_{ABCD}\\;\\Rightarrow\\; V_{ABDP_0} = 0{,}5\\cdot V_{ABCDS}\\end{aligned}"}]}]}, {"id": "rg7", "year": 2023, "term": "Nachtermin", "nr": "B 4", "notr": false, "pts": "16", "intro": "<p>Das Drachenviereck ABCD mit der Symmetrieachse AC und dem Diagonalenschnittpunkt M ist die Grundfläche der Pyramide ABCDS mit der Höhe <span class=\"ov\">MS</span>.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 14 cm; |<span class=\"ov\">CM</span>| = 5 cm; |<span class=\"ov\">BD</span>| = 12 cm; |<span class=\"ov\">MS</span>| = 10 cm.</p><p>Die nebenstehende Skizze zeigt ein Schrägbild der Pyramide ABCDS.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f07", "figw": 5.8, "bigfig": false, "subs": [{"label": "B 4.1", "pts": "4", "text": "<p>Zeichne das Schrägbild der Pyramide ABCDS, wobei <span class=\"ov\">AC</span> auf der Schrägbildachse und der Punkt A links vom Punkt C liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">CS</span> und das Maß des Winkels SCA.</p><p class=\"hint\">[Teilergebnisse: |<span class=\"ov\">CS</span>| = 11,18 cm; ∢SCA = 63,43°]</p>", "img": null, "sol": [{"t": "\\([AC]\\) mit 14 cm auf die Schrägbildachse, M liegt 5 cm vor C. \\([BD]\\) durch M unter 45° mit halber Länge (je 3 cm). Die Höhe \\([MS]\\) steht senkrecht mit 10 cm.", "m": null}, {"t": "Das Dreieck MCS ist rechtwinklig bei M.", "m": "\\begin{aligned}\\s{CS} &= \\sqrt{\\s{MS}^2+\\s{CM}^2} = \\sqrt{10^2+5^2}\\cm\\\\[3pt]\\s{CS} &= \\erg{11{,}18\\cm}\\end{aligned}"}, {"t": "\\([MS]\\) ist Gegenkathete, \\([CM]\\) Ankathete von ∢SCA.", "m": "\\begin{aligned}\\tan\\w SCA &= \\dfrac{\\s{MS}}{\\s{CM}} = \\dfrac{10}{5}\\\\[3pt]\\w SCA &= \\erg{63{,}43^\\circ}\\end{aligned}"}], "solimg": "rg_sol_07", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 4.2", "pts": "4", "text": "<p>Für Punkte P<sub>n</sub> ∈ <span class=\"ov\">CS</span> und T<sub>n</sub> ∈ <span class=\"ov\">AM</span> gilt: |<span class=\"ov\">SP<sub>n</sub></span>|(x) = 0,5 · x cm und |<span class=\"ov\">MT<sub>n</sub></span>|(x) = x cm mit x ∈ IR und 0 &lt; x ≤ 9. Die Punkte P<sub>n</sub> sind die Spitzen von Pyramiden T<sub>n</sub>BCDP<sub>n</sub> mit den Grundflächen T<sub>n</sub>BCD und den Höhen <span class=\"ov\">F<sub>n</sub>P<sub>n</sub></span>.</p><p>Zeichne die Pyramide T<sub>1</sub>BCDP<sub>1</sub> und die Höhe <span class=\"ov\">F<sub>1</sub>P<sub>1</sub></span> für x = 7 in das Schrägbild zu B 4.1 ein.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">P<sub>1</sub>T<sub>1</sub></span>.</p>", "img": null, "sol": [{"t": "Für x = 7: \\(\\s{SP_1}=3{,}5\\cm\\) auf \\([SC]\\), \\(\\s{MT_1}=7\\cm\\) auf \\([MA]\\). Zeichne die Pyramide \\(T_1BCDP_1\\) und die Höhe \\([F_1P_1]\\) parallel zu \\([MS]\\).", "m": null}, {"t": "Im Dreieck \\(CT_1P_1\\) kennst du zwei Seiten und den Winkel bei C.", "m": "\\begin{aligned}\\s{CP_1} &= (11{,}18-0{,}5\\cdot 7)\\cm = 7{,}68\\cm\\\\[3pt]\\s{CT_1} &= (5+7)\\cm = 12\\cm\\end{aligned}"}, {"t": "Kosinussatz:", "m": "\\begin{aligned}\\s{P_1T_1}^2 &= \\s{CP_1}^2+\\s{CT_1}^2-2\\cdot\\s{CP_1}\\cdot\\s{CT_1}\\cdot\\cos\\w SCA\\\\[3pt]\\s{P_1T_1} &= \\sqrt{7{,}68^2+12^2-2\\cdot 7{,}68\\cdot 12\\cdot\\cos 63{,}43^\\circ}\\cm\\\\[3pt]\\s{P_1T_1} &= \\erg{10{,}98\\cm}\\end{aligned}"}]}, {"label": "B 4.3", "pts": "4", "text": "<p>Bestimme durch Rechnung, um wie viel Prozent das Volumen der Pyramide T<sub>1</sub>BCDP<sub>1</sub> kleiner ist als das Volumen der Pyramide ABCDS.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">F<sub>1</sub>P<sub>1</sub></span>| = 6,87 cm]</p>", "img": null, "sol": [{"t": "Volumen der großen Pyramide (Drachen: \\(\\tfrac12\\cdot e\\cdot f\\)).", "m": "\\begin{aligned}V_{ABCDS} &= \\tfrac13\\cdot\\tfrac12\\cdot 14\\cdot 12\\cdot 10\\cmk = 280\\cmk\\end{aligned}"}, {"t": "Die Höhe \\(\\s{F_1P_1}\\) im rechtwinkligen Dreieck \\(CF_1P_1\\) mit dem Sinus.", "m": "\\begin{aligned}\\sin 63{,}43^\\circ &= \\dfrac{\\s{F_1P_1}}{7{,}68\\cm}\\\\[3pt]\\s{F_1P_1} &= 6{,}87\\cm\\end{aligned}"}, {"t": "Volumen der Pyramide \\(T_1BCDP_1\\). Grundfläche ist der Drachen \\(T_1BCD\\) mit den Diagonalen \\([CT_1]\\) und \\([BD]\\).", "m": "\\begin{aligned}V_{T_1BCDP_1} &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{CT_1}\\cdot\\s{BD}\\cdot\\s{F_1P_1}\\\\[3pt]V_{T_1BCDP_1} &= \\tfrac13\\cdot\\tfrac12\\cdot 12\\cdot 12\\cdot 6{,}87\\cmk = 164{,}88\\cmk\\end{aligned}"}, {"t": "Prozentuale Abnahme: Differenz durch Grundwert.", "m": "\\begin{aligned}\\dfrac{280-164{,}88}{280}\\cdot 100\\,\\% &= \\erg{41{,}11\\,\\%}\\end{aligned}"}]}, {"label": "B 4.4", "pts": "2", "text": "<p>Für die Pyramide T<sub>2</sub>BCDP<sub>2</sub> gilt: |<span class=\"ov\">CP<sub>2</sub></span>| = |<span class=\"ov\">CT<sub>2</sub></span>|.</p><p>Berechne den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Setze die beiden Längen gleich: \\(\\s{CP_2}=(11{,}18-0{,}5x)\\cm\\) und \\(\\s{CT_2}=(5+x)\\cm\\).", "m": "\\begin{aligned}11{,}18-0{,}5x &= 5+x\\\\[3pt]6{,}18 &= 1{,}5x\\\\[3pt]x &= \\erg{4{,}12}\\end{aligned}"}]}, {"label": "B 4.5", "pts": "2", "text": "<p>In der Pyramide T<sub>3</sub>BCDP<sub>3</sub> hat der Winkel BT<sub>3</sub>D das Maß 90°.</p><p>Bestimme den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Ein rechter Winkel bei \\(T_3\\) über der Strecke \\([BD]\\) bedeutet: \\(T_3\\) liegt auf dem Thaleskreis über \\([BD]\\) mit Mittelpunkt M. Der Radius ist \\(\\s{BM}\\).", "m": "\\begin{aligned}\\s{MT_3} &= \\s{BM} = 0{,}5\\cdot 12\\cm = 6\\cm\\\\[3pt]x &= \\erg{6}\\end{aligned}"}]}]}, {"id": "rg8", "year": 2024, "term": "Haupttermin", "nr": "A 2", "notr": true, "pts": "2,5", "intro": "<p>Die Raute ABCD mit dem Diagonalenschnittpunkt M ist die Grundfläche der Pyramide ABCDS. Das Schrägbild zeigt diese Pyramide mit ihrer Höhe <span class=\"ov\">MS</span>.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 8 cm; |<span class=\"ov\">BD</span>| = 12 cm; |<span class=\"ov\">MS</span>| = 7 cm.</p><p>In der Zeichnung gilt: q = ½; ω = 45°; <span class=\"ov\">AC</span> liegt auf der Schrägbildachse.</p>", "fig": "f08", "figw": null, "bigfig": true, "subs": [{"label": "A 2.1", "pts": "1,5", "text": "<p>Es entstehen neue Pyramiden ABC<sub>n</sub>DS<sub>n</sub> mit den Höhen <span class=\"ov\">MS<sub>n</sub></span> und den Grundflächen ABC<sub>n</sub>D, wenn man die Strecke <span class=\"ov\">AC</span> über C hinaus um 2x cm verlängert und gleichzeitig die Strecke <span class=\"ov\">MS</span> von S aus um x cm verkürzt (x ∈ IR; 0 &lt; x &lt; 7).</p><p>Zeichne für x = 2 die Pyramide ABC<sub>1</sub>DS<sub>1</sub> in das Schrägbild ein.</p>", "img": null, "sol": [{"t": "Für x = 2: Verlängere \\([AC]\\) über C hinaus um \\(2\\cdot 2\\cm=4\\cm\\). Im Schrägbild liegt \\([AC]\\) auf der Schrägbildachse, also wird in wahrer Länge abgetragen. Das ergibt \\(C_1\\).", "m": null}, {"t": "Verkürze \\([MS]\\) von S aus um 2 cm. Die Höhe steht senkrecht und erscheint ebenfalls in wahrer Länge. Das ergibt \\(S_1\\) mit \\(\\s{MS_1}=5\\cm\\).", "m": null}, {"t": "Verbinde \\(S_1\\) mit A, B, \\(C_1\\) und D und zeichne die Grundfläche \\(ABC_1D\\).", "m": null}]}, {"label": "A 2.2", "pts": "1", "text": "<p>Für das Volumen V der Pyramiden ABC<sub>n</sub>DS<sub>n</sub> in Abhängigkeit von x gilt: V(x) = ⅓ · ½ · 12 · (8 + 2x) · (7 − x) cm<sup>3</sup>.</p><p>Bei welchem der folgenden Terme wurde V(x) richtig umgeformt? Kreuze diesen Term an.</p><p class=\"opt\">☐  V(x) = 2 · (56 − 8x + 14x + 2x<sup>2</sup>) cm<sup>3</sup></p><p class=\"opt\">☐  V(x) = 2 · (56 − 6x − 2x<sup>2</sup>) cm<sup>3</sup></p><p class=\"opt\">☐  V(x) = (16 + 4x) · (7 − x) cm<sup>3</sup></p><p class=\"opt\">☐  V(x) = (16 + 4x) · (14 − 2x) cm<sup>3</sup></p>", "img": null, "sol": [{"t": "Rechne den Term selbst um: Zuerst die Zahlen vor der Klammer zusammenfassen.", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 12\\cdot(8+2x)\\cdot(7-x)\\cmk\\\\[3pt]&= 2\\cdot(8+2x)\\cdot(7-x)\\cmk\\end{aligned}"}, {"t": "Die 2 kannst du in die erste Klammer hineinmultiplizieren. Das ist genau der dritte Term.", "m": "\\begin{aligned}V(x) &= \\erg{(16+4x)\\cdot(7-x)\\cmk}\\end{aligned}"}, {"t": "Kontrolle der anderen Terme: Ausmultipliziert gilt \\((8+2x)(7-x)=56-8x+14x-2x^2=56+6x-2x^2\\). Die Terme 1 und 2 haben falsche Vorzeichen, Term 4 ist doppelt so groß.", "m": null}]}]}, {"id": "rg9", "year": 2024, "term": "Haupttermin", "nr": "A 3", "notr": true, "pts": "4", "intro": "<p>Ein Baumarkt bietet zehn gleich große Christbaumkugeln in einer zylinderförmigen Verpackung an.</p>", "fig": "f09", "figw": 3.6, "bigfig": false, "subs": [{"label": "A 3", "pts": "4", "text": "<p>Ermittle das ungefähre Volumen der Verpackung in Wirklichkeit. Schätze die dafür benötigten Größen anhand des Bildes ab.</p>", "img": null, "sol": [{"t": "Suche im Bild eine Vergleichsgröße, deren wahre Länge du kennst. Zum Beispiel sind drei Finger zusammen etwa 6 cm breit.", "m": null}, {"t": "Daraus schätzt du die Maße der Verpackung ab: Der Durchmesser ist etwa so breit wie die drei Finger, also r ≈ 3 cm. Die Höhe entspricht etwa zehn Kugeln, also h ≈ 60 cm.", "m": null}, {"t": "Volumen des Zylinders. Ohne Taschenrechner nimmst du π ≈ 3.", "m": "\\begin{aligned}V &= r^2\\cdot\\pi\\cdot h\\\\[3pt]V &\\approx 3^2\\cdot 3\\cdot 60\\cmk = 27\\cdot 60\\cmk \\approx 30\\cdot 60\\cmk\\\\[3pt]V &\\approx \\erg{1800\\cmk}\\end{aligned}"}, {"t": "Andere sinnvolle Schätzungen sind auch richtig, wenn der Weg nachvollziehbar ist.", "m": null}]}]}, {"id": "rg10", "year": 2024, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "5", "intro": "<p>Die Vorlage einer Spielfigur ist ein Rotationskörper mit der Rotationsachse MS. Nebenstehende Skizze zeigt grau eingefärbt den zugehörigen Axialschnitt.</p><p>Es gilt: |<span class=\"ov\">MB</span>| = 1 cm; |<span class=\"ov\">TD</span>| = 2 cm; |<span class=\"ov\">TM</span>| = 1,5 cm; |<span class=\"ov\">NT</span>| = 2 cm; |<span class=\"ov\">ST</span>| = 6,5 cm; AH ∥ BC.</p>", "fig": "f10", "figw": 4.2, "bigfig": false, "subs": [{"label": "B 2.1", "pts": "4", "text": "<p>Berechne das Volumen des Rotationskörpers. Runde auf zwei Stellen nach dem Komma.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">NE</span>| = 1,38 cm]</p>", "img": null, "sol": [{"t": "Der Körper besteht aus einem Zylinder (Radius \\(\\s{MB}\\), Höhe \\(\\s{TM}\\)) und einem Kegel (Radius \\(\\s{TD}\\), Höhe \\(\\s{ST}\\)). Die Spitze, ein kleiner Kegel (Radius \\(\\s{NE}\\), Höhe \\(\\s{SN}\\)), fehlt und wird abgezogen.", "m": "\\begin{aligned}V &= \\s{MB}^2\\cdot\\pi\\cdot\\s{TM}+\\tfrac13\\cdot\\s{TD}^2\\cdot\\pi\\cdot\\s{ST}-\\tfrac13\\cdot\\s{NE}^2\\cdot\\pi\\cdot\\s{SN}\\end{aligned}"}, {"t": "Höhe des kleinen Kegels:", "m": "\\begin{aligned}\\s{SN} &= \\s{ST}-\\s{NT} = (6{,}5-2)\\cm = 4{,}5\\cm\\end{aligned}"}, {"t": "Radius \\(\\s{NE}\\) mit dem Vierstreckensatz (Zentrum S).", "m": "\\begin{aligned}\\dfrac{\\s{NE}}{\\s{TD}} &= \\dfrac{\\s{SN}}{\\s{ST}}\\\\[3pt]\\dfrac{\\s{NE}}{2\\cm} &= \\dfrac{4{,}5\\cm}{6{,}5\\cm}\\\\[3pt]\\s{NE} &= 1{,}38\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V &= \\left(1^2\\cdot\\pi\\cdot 1{,}5+\\tfrac13\\cdot 2^2\\cdot\\pi\\cdot 6{,}5-\\tfrac13\\cdot 1{,}38^2\\cdot\\pi\\cdot 4{,}5\\right)\\cmk\\\\[3pt]V &= \\erg{22{,}97\\cmk}\\end{aligned}"}]}, {"label": "B 2.2", "pts": "1", "text": "<p>Die komplette Oberfläche der Spielfigur soll mit einer grauen Schutzfolie beklebt werden.</p><p>Welches Aufkleber-Set ist hierfür passend? Kreuze an.</p>", "img": "f10b", "sol": [{"t": "Überlege, aus welchen Flächen die Oberfläche besteht: Bodenkreis des Zylinders (r = 1 cm), Zylindermantel (Rechteck), Kreisring an der Unterseite des Kegels (zwischen r = 1 cm und r = 2 cm), Mantel des Kegelstumpfs und obere Deckfläche (r = 1,38 cm). Prüfe bei jedem Set, ob genau diese Teile in passender Größe dabei sind.", "m": null}, {"t": "Passend ist das Set 3.", "m": "\\begin{aligned}&\\erg{\\text{Set 3}}\\end{aligned}"}]}]}, {"id": "rg11", "year": 2024, "term": "Nachtermin", "nr": "A 2", "notr": true, "pts": "2", "intro": "<p>Das gleichschenklig-rechtwinklige Dreieck ABC ist die Grundfläche des geraden Prismas ABCDEF mit einem Volumen von 1000 cm<sup>3</sup> (vgl. Skizze).</p><p>Es gilt: |<span class=\"ov\">AB</span>| = |<span class=\"ov\">AC</span>| = 10 cm.</p>", "fig": "f11", "figw": 2.8, "bigfig": false, "subs": [{"label": "A 2", "pts": "2", "text": "<p>Berechne die Länge der Strecke <span class=\"ov\">AD</span>.</p>", "img": null, "sol": [{"t": "Das Volumen eines Prismas ist Grundfläche · Höhe. Die Grundfläche ist das rechtwinklige Dreieck ABC mit den Katheten 10 cm und 10 cm. Die Höhe ist \\(\\s{AD}\\).", "m": "\\begin{aligned}V &= A_{ABC}\\cdot\\s{AD}\\\\[3pt]1000\\cmk &= \\tfrac12\\cdot 10\\cm\\cdot 10\\cm\\cdot\\s{AD}\\\\[3pt]1000\\cmk &= 50\\cmq\\cdot\\s{AD}\\\\[3pt]\\s{AD} &= \\erg{20\\cm}\\end{aligned}"}]}]}, {"id": "rg12", "year": 2024, "term": "Nachtermin", "nr": "B 4", "notr": false, "pts": "16,5", "intro": "<p>Die nebenstehende Skizze zeigt ein Schrägbild des geraden Prismas ABCDEFGH, dessen Grundfläche das Quadrat ABCD mit dem Diagonalenschnittpunkt M ist. Der Punkt N ist der Diagonalenschnittpunkt des Quadrats EFGH.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 10 cm; |<span class=\"ov\">AE</span>| = 8 cm.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f12", "figw": 4.6, "bigfig": false, "subs": [{"label": "B 4.1", "pts": "4,5", "text": "<p>Zeichne das Schrägbild des Prismas ABCDEFGH mit den Strecken <span class=\"ov\">MN</span> und <span class=\"ov\">AN</span>, wobei die Strecke <span class=\"ov\">AC</span> auf der Schrägbildachse und der Punkt A links vom Punkt C liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">AN</span> und das Maß des Winkels CAN.</p><p class=\"hint\">[Teilergebnisse: |<span class=\"ov\">AN</span>| = 9,43 cm; ∢CAN = 57,99°]</p>", "img": null, "sol": [{"t": "\\([AC]\\) mit 10 cm auf die Schrägbildachse, \\([BD]\\) durch M unter 45° mit halber Länge (je 2,5 cm). Senkrechte Kanten 8 cm. N liegt senkrecht über M.", "m": null}, {"t": "Das Dreieck AMN ist rechtwinklig bei M mit \\(\\s{AM}=0{,}5\\cdot 10\\cm\\) und \\(\\s{MN}=8\\cm\\).", "m": "\\begin{aligned}\\s{AN} &= \\sqrt{(0{,}5\\cdot 10)^2+8^2}\\cm\\\\[3pt]\\s{AN} &= \\erg{9{,}43\\cm}\\end{aligned}"}, {"t": "Für ∢CAN ist \\([MN]\\) die Gegenkathete und \\([AM]\\) die Ankathete.", "m": "\\begin{aligned}\\tan\\w CAN &= \\dfrac{\\s{MN}}{\\s{AM}} = \\dfrac{8}{0{,}5\\cdot 10}\\\\[3pt]\\w CAN &= \\erg{57{,}99^\\circ}\\end{aligned}"}], "solimg": "rg_sol_12", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 4.2", "pts": "3", "text": "<p>Punkte P<sub>n</sub> liegen auf der Strecke <span class=\"ov\">AN</span> mit |<span class=\"ov\">AP<sub>n</sub></span>|(x) = x cm (x ∈ IR).</p><p>Die Punkte P<sub>n</sub> bilden zusammen mit Punkten Q<sub>n</sub>, R<sub>n</sub> und S<sub>n</sub> Drachenvierecke P<sub>n</sub>Q<sub>n</sub>R<sub>n</sub>S<sub>n</sub> mit den Diagonalenschnittpunkten L<sub>n</sub>. Diese Drachenvierecke liegen parallel zum Quadrat ABCD. Sie sind die Grundflächen von Pyramiden P<sub>n</sub>Q<sub>n</sub>R<sub>n</sub>S<sub>n</sub>N mit der Spitze N und den Höhen <span class=\"ov\">L<sub>n</sub>N</span>.</p><p>Es gilt: Q<sub>n</sub> ∈ <span class=\"ov\">BF</span>, R<sub>n</sub> ∈ <span class=\"ov\">CG</span>, S<sub>n</sub> ∈ <span class=\"ov\">DH</span>, L<sub>n</sub> ∈ <span class=\"ov\">MN</span>, P<sub>n</sub>R<sub>n</sub> ∥ AC und Q<sub>n</sub>S<sub>n</sub> ∥ BD.</p><p>Zeichne die Pyramide P<sub>1</sub>Q<sub>1</sub>R<sub>1</sub>S<sub>1</sub>N und den Punkt L<sub>1</sub> für x = 4 in das Schrägbild zu B 4.1 ein.</p><p>Gib sodann an, für welche Belegungen von x es Pyramiden P<sub>n</sub>Q<sub>n</sub>R<sub>n</sub>S<sub>n</sub>N gibt.</p>", "img": null, "sol": [{"t": "Trage \\(\\s{AP_1}=4\\cm\\) auf \\([AN]\\) ab. Durch \\(P_1\\) die Parallele zu \\([AC]\\) bis \\([CG]\\) ergibt \\(R_1\\) und \\(L_1\\) auf \\([MN]\\). Durch \\(L_1\\) die Parallele zu \\([BD]\\) ergibt \\(Q_1\\) und \\(S_1\\). Verbinde alles mit N.", "m": null}, {"t": "Für x = 0 ist \\(P_0 = A\\), das geht noch. Bei \\(x = \\s{AN} = 9{,}43\\) fällt \\(P_n\\) mit der Spitze N zusammen und die Pyramide verschwindet.", "m": "\\begin{aligned}&\\erg{0\\le x<9{,}43}\\end{aligned}"}]}, {"label": "B 4.3", "pts": "3", "text": "<p>Zeige, dass für den Flächeninhalt der Grundflächen P<sub>n</sub>Q<sub>n</sub>R<sub>n</sub>S<sub>n</sub> der Pyramiden P<sub>n</sub>Q<sub>n</sub>R<sub>n</sub>S<sub>n</sub>N in Abhängigkeit von x gilt: A(x) = (50 − 2,65x) cm<sup>2</sup>.</p>", "img": null, "sol": [{"t": "Das Drachenviereck hat die Diagonalen \\([P_nR_n]\\) und \\([Q_nS_n]\\). \\([Q_nS_n]\\) ist immer so lang wie \\([BD]\\), also 10 cm.", "m": "\\begin{aligned}A &= 0{,}5\\cdot\\left(\\s{P_nL_n}+\\s{L_nR_n}\\right)\\cdot\\s{Q_nS_n}\\end{aligned}"}, {"t": "\\(\\s{L_nR_n}\\) bleibt immer 5 cm (halbe Diagonale). \\(\\s{P_nL_n}\\) mit dem Vierstreckensatz, Zentrum N.", "m": "\\begin{aligned}\\dfrac{\\s{P_nL_n}}{\\s{AM}} &= \\dfrac{\\s{NP_n}}{\\s{NA}}\\\\[3pt]\\dfrac{\\s{P_nL_n}}{0{,}5\\cdot 10\\cm} &= \\dfrac{(9{,}43-x)\\cm}{9{,}43\\cm}\\\\[3pt]\\s{P_nL_n}(x) &= (5-0{,}53x)\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}A(x) &= 0{,}5\\cdot(5-0{,}53x+0{,}5\\cdot 10)\\cdot 10\\cmq\\\\[3pt]A(x) &= \\erg{(50-2{,}65x)\\cmq}\\end{aligned}"}]}, {"label": "B 4.4", "pts": "4", "text": "<p>Berechne den prozentualen Anteil des Volumens der Pyramide P<sub>1</sub>Q<sub>1</sub>R<sub>1</sub>S<sub>1</sub>N am Volumen des Prismas ABCDEFGH.</p><p class=\"hint\">[Zwischenergebnisse: |<span class=\"ov\">L<sub>1</sub>N</span>| = 4,61 cm; V<sub>P1Q1R1S1N</sub> = 60,54 cm<sup>3</sup>]</p>", "img": null, "sol": [{"t": "Volumen des Prismas (Grundfläche Quadrat mit Diagonale 10 cm: \\(\\tfrac12\\cdot 10\\cdot 10\\)).", "m": "\\begin{aligned}V_{ABCDEFGH} &= \\tfrac12\\cdot 10\\cdot 10\\cdot 8\\cmk = 400\\cmk\\end{aligned}"}, {"t": "Höhe der Pyramide \\(\\s{L_1N}\\) mit dem Vierstreckensatz.", "m": "\\begin{aligned}\\dfrac{\\s{L_1N}}{8\\cm} &= \\dfrac{(9{,}43-4)\\cm}{9{,}43\\cm}\\\\[3pt]\\s{L_1N} &= 4{,}61\\cm\\end{aligned}"}, {"t": "Pyramidenvolumen mit A(4) als Grundfläche.", "m": "\\begin{aligned}V_{P_1Q_1R_1S_1N} &= \\tfrac13\\cdot(50-2{,}65\\cdot 4)\\cdot 4{,}61\\cmk = 60{,}54\\cmk\\end{aligned}"}, {"t": "Prozentualer Anteil:", "m": "\\begin{aligned}\\dfrac{60{,}54}{400}\\cdot 100\\,\\% &= \\erg{15{,}14\\,\\%}\\end{aligned}"}]}, {"label": "B 4.5", "pts": "2", "text": "<p>Unter den Winkeln NR<sub>n</sub>P<sub>n</sub> hat der Winkel NR<sub>0</sub>P<sub>0</sub> das größte Maß.</p><p>Bestimme dieses Winkelmaß.</p>", "img": null, "sol": [{"t": "Im Dreieck \\(P_nR_nN\\) wird der Winkel bei \\(R_n\\) am größten, wenn \\(R_n\\) ganz unten liegt. Das ist bei x = 0 der Fall: \\(P_0 = A\\), \\(R_0 = C\\).", "m": null}, {"t": "Das Dreieck ACN ist gleichschenklig, weil N über M liegt. Die Basiswinkel sind gleich.", "m": "\\begin{aligned}\\w NR_0P_0 &= \\w NCA = \\w CAN = \\erg{57{,}99^\\circ}\\end{aligned}"}]}]}, {"id": "rg13", "year": 2025, "term": "Haupttermin", "nr": "B 4", "notr": false, "pts": "16", "intro": "<p>Die nebenstehende Skizze zeigt ein Schrägbild der Pyramide ABCDS mit der Höhe <span class=\"ov\">MS</span>, deren Grundfläche das Quadrat ABCD mit dem Diagonalenschnittpunkt M ist.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 12 cm; |<span class=\"ov\">MS</span>| = 8,5 cm.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f13", "figw": 5.0, "bigfig": false, "subs": [{"label": "B 4.1", "pts": "4", "text": "<p>Zeichne das Schrägbild der Pyramide ABCDS, wobei die Strecke <span class=\"ov\">AC</span> auf der Schrägbildachse und der Punkt A links vom Punkt C liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">AS</span> sowie das Maß des Winkels MAS.</p><p class=\"hint\">[Teilergebnisse: |<span class=\"ov\">AS</span>| = 10,40 cm; ∢MAS = 54,78°]</p>", "img": null, "sol": [{"t": "\\([AC]\\) mit 12 cm auf die Schrägbildachse. \\([BD]\\) ist beim Quadrat auch 12 cm lang, im Schrägbild unter 45° mit halber Länge (je 3 cm). Die Höhe \\([MS]\\) steht senkrecht mit 8,5 cm.", "m": null}, {"t": "Dreieck AMS ist rechtwinklig bei M.", "m": "\\begin{aligned}\\s{AS} &= \\sqrt{(0{,}5\\cdot 12)^2+8{,}5^2}\\cm\\\\[3pt]\\s{AS} &= \\erg{10{,}40\\cm}\\end{aligned}"}, {"t": "\\([MS]\\) ist Gegenkathete, \\([AM]\\) Ankathete von ∢MAS.", "m": "\\begin{aligned}\\tan\\w MAS &= \\dfrac{8{,}5}{0{,}5\\cdot 12}\\\\[3pt]\\w MAS &= \\erg{54{,}78^\\circ}\\end{aligned}"}], "solimg": "rg_sol_13", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 4.2", "pts": "4", "text": "<p>Für Punkte P<sub>n</sub> ∈ <span class=\"ov\">AS</span> gilt: |<span class=\"ov\">SP<sub>n</sub></span>|(x) = x cm (x ∈ IR; 0 ≤ x &lt; 10,40). Sie sind die Spitzen von Pyramiden AMDP<sub>n</sub> mit den Höhen <span class=\"ov\">P<sub>n</sub>H<sub>n</sub></span>.</p><p>Zeichne für x = 5 die Pyramide AMDP<sub>1</sub> und die Höhe <span class=\"ov\">P<sub>1</sub>H<sub>1</sub></span> in das Schrägbild zu B 4.1 ein.</p><p>Berechne sodann die Länge der Strecke <span class=\"ov\">MP<sub>1</sub></span> sowie den Flächeninhalt des Dreiecks AMP<sub>1</sub>.</p>", "img": null, "sol": [{"t": "Trage \\(\\s{SP_1}=5\\cm\\) auf \\([SA]\\) ab. Zeichne die Pyramide \\(AMDP_1\\) und die Höhe \\([P_1H_1]\\) parallel zu \\([MS]\\).", "m": null}, {"t": "Im Dreieck \\(AMP_1\\) gilt \\(\\s{AM}=6\\cm\\), \\(\\s{AP_1}=(10{,}40-5)\\cm\\) und der Winkel bei A ist ∢MAS. Kosinussatz:", "m": "\\begin{aligned}\\s{MP_1} &= \\sqrt{(0{,}5\\cdot 12)^2+(10{,}40-5)^2-2\\cdot 0{,}5\\cdot 12\\cdot(10{,}40-5)\\cdot\\cos 54{,}78^\\circ}\\cm\\\\[3pt]\\s{MP_1} &= \\erg{5{,}27\\cm}\\end{aligned}"}, {"t": "Flächenformel mit dem Sinus:", "m": "\\begin{aligned}A_{AMP_1} &= \\tfrac12\\cdot 0{,}5\\cdot 12\\cdot(10{,}40-5)\\cdot\\sin 54{,}78^\\circ\\cmq\\\\[3pt]A_{AMP_1} &= \\erg{13{,}23\\cmq}\\end{aligned}"}]}, {"label": "B 4.3", "pts": "4", "text": "<p>Zeige, dass für das Volumen der Pyramiden AMDP<sub>n</sub> in Abhängigkeit von x gilt: V(x) = (−4,92x + 51,00) cm<sup>3</sup>.</p><p>Unter den Pyramiden AMDP<sub>n</sub> hat die Pyramide AMDP<sub>0</sub> das maximale Volumen.</p><p>Gib den zugehörigen Wert von x sowie das maximale Volumen an.</p>", "img": null, "sol": [{"t": "Grundfläche AMD ist ein rechtwinkliges Dreieck mit den Katheten \\(\\s{AM}\\) und \\(\\s{MD}\\) (je 6 cm).", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{AM}\\cdot\\s{MD}\\cdot\\s{P_nH_n}\\end{aligned}"}, {"t": "Höhe mit dem Sinus im rechtwinkligen Dreieck \\(AH_nP_n\\), Hypotenuse \\(\\s{AP_n}=(10{,}40-x)\\cm\\).", "m": "\\begin{aligned}\\sin 54{,}78^\\circ &= \\dfrac{\\s{P_nH_n}}{(10{,}40-x)\\cm}\\\\[3pt]\\s{P_nH_n}(x) &= (8{,}50-0{,}82x)\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 0{,}5\\cdot 12\\cdot 0{,}5\\cdot 12\\cdot(8{,}50-0{,}82x)\\cmk\\\\[3pt]V(x) &= \\erg{(-4{,}92x+51{,}00)\\cmk}\\end{aligned}"}, {"t": "V(x) ist eine fallende Gerade. Das Maximum liegt beim kleinsten x, also x = 0.", "m": "\\begin{aligned}x=0;\\;\\; V_{\\max} &= \\erg{51{,}00\\cmk}\\end{aligned}"}]}, {"label": "B 4.4", "pts": "2,5", "text": "<p>Die Pyramide AMDP<sub>2</sub> hat ein Volumen von 35 cm<sup>3</sup>.</p><p>Berechne den zugehörigen Wert von x.</p><p>Gib sodann das Intervall für x an, so dass gilt: V(x) ≥ 35 cm<sup>3</sup>.</p>", "img": null, "sol": [{"t": "V(x) = 35 setzen und nach x auflösen.", "m": "\\begin{aligned}35 &= -4{,}92x+51{,}00\\\\[3pt]4{,}92x &= 16\\\\[3pt]x &= \\erg{3{,}25}\\end{aligned}"}, {"t": "Da V(x) mit wachsendem x kleiner wird, ist das Volumen für alle x bis 3,25 mindestens 35 cm³.", "m": "\\begin{aligned}&\\erg{x\\in[0;\\,3{,}25]}\\end{aligned}"}]}, {"label": "B 4.5", "pts": "1,5", "text": "<p>Die Höhe der Pyramide AMDP<sub>3</sub> ist halb so lang wie die Höhe der Pyramide ABCDS.</p><p>Begründe, weshalb das Volumen der Pyramide ABCDS achtmal so groß wie das Volumen der Pyramide AMDP<sub>3</sub> ist.</p>", "img": null, "sol": [{"t": "Vergleiche Grundfläche und Höhe. Das Quadrat ABCD besteht aus vier Dreiecken wie AMD. Die Höhe von ABCDS ist doppelt so lang.", "m": "\\begin{aligned}A_{ABCD} &= 4\\cdot A_{AMD}\\\\[3pt]h_{ABCDS} &= 2\\cdot h_{AMDP_3}\\end{aligned}"}, {"t": "Einsetzen in die Volumenformel:", "m": "\\begin{aligned}V_{ABCDS} &= \\tfrac13\\cdot 4\\cdot A_{AMD}\\cdot 2\\cdot h_{AMDP_3} = 8\\cdot\\underbrace{\\tfrac13\\cdot A_{AMD}\\cdot h_{AMDP_3}}_{=V_{AMDP_3}} = \\erg{8\\cdot V_{AMDP_3}}\\end{aligned}"}]}]}, {"id": "rg14", "year": 2025, "term": "Nachtermin", "nr": "B 4", "notr": false, "pts": "16,5", "intro": "<p>Die nebenstehende Skizze zeigt ein Schrägbild der Pyramide ABCDS mit der Höhe <span class=\"ov\">MS</span>. Die Grundfläche dieser Pyramide ist das Drachenviereck ABCD mit dem Diagonalenschnittpunkt M.</p><p>Es gilt: |<span class=\"ov\">AC</span>| = 11 cm; |<span class=\"ov\">AM</span>| = 3,5 cm; |<span class=\"ov\">BD</span>| = 8 cm; |<span class=\"ov\">AS</span>| = 7 cm.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": "f14", "figw": 5.8, "bigfig": false, "subs": [{"label": "B 4.1", "pts": "2", "text": "<p>Zeichne das Schrägbild der Pyramide ABCDS, wobei die Strecke <span class=\"ov\">AC</span> auf der Schrägbildachse und der Punkt A links vom Punkt C liegen soll.</p><p>Für die Zeichnung gilt: q = ½; ω = 45°.</p>", "img": null, "sol": [{"t": "\\([AC]\\) mit 11 cm auf die Schrägbildachse, M liegt 3,5 cm rechts von A. \\([BD]\\) durch M unter 45° mit halber Länge (je 2 cm). S liegt senkrecht über M, so dass \\(\\s{AS}=7\\cm\\) ist. Die Höhe \\(\\s{MS}\\) berechnest du in B 4.2 (6,06 cm).", "m": null}], "solimg": "rg_sol_14", "solcap": "Zeichnung aus dem Lösungsmuster (enthält auch Punkte der folgenden Teilaufgaben)"}, {"label": "B 4.2", "pts": "3", "text": "<p>Berechne das Maß des Winkels CAS und die Längen der Strecken <span class=\"ov\">CS</span> und <span class=\"ov\">MS</span>.</p><p class=\"hint\">[Ergebnisse: ∢CAS = 60°; |<span class=\"ov\">CS</span>| = 9,64 cm; |<span class=\"ov\">MS</span>| = 6,06 cm]</p>", "img": null, "sol": [{"t": "Im rechtwinkligen Dreieck AMS ist \\([AM]\\) die Ankathete und \\([AS]\\) die Hypotenuse.", "m": "\\begin{aligned}\\cos\\w CAS &= \\dfrac{\\s{AM}}{\\s{AS}} = \\dfrac{3{,}5}{7}\\\\[3pt]\\w CAS &= \\erg{60^\\circ}\\end{aligned}"}, {"t": "\\(\\s{CS}\\) mit dem Kosinussatz im Dreieck ACS.", "m": "\\begin{aligned}\\s{CS} &= \\sqrt{11^2+7^2-2\\cdot 11\\cdot 7\\cdot\\cos 60^\\circ}\\cm\\\\[3pt]\\s{CS} &= \\erg{9{,}64\\cm}\\end{aligned}"}, {"t": "\\(\\s{MS}\\) mit dem Satz des Pythagoras im Dreieck AMS.", "m": "\\begin{aligned}\\s{MS} &= \\sqrt{7^2-3{,}5^2}\\cm\\\\[3pt]\\s{MS} &= \\erg{6{,}06\\cm}\\end{aligned}"}]}, {"label": "B 4.3", "pts": "2,5", "text": "<p>Für Punkte P<sub>n</sub> ∈ <span class=\"ov\">CS</span> gilt: |<span class=\"ov\">SP<sub>n</sub></span>|(x) = x cm (x ∈ IR; 0 &lt; x &lt; 9,64). Die Punkte P<sub>n</sub> sind Eckpunkte von Dreiecken AP<sub>n</sub>S.</p><p>Zeichne das Dreieck AP<sub>1</sub>S für x = 3 in das Schrägbild zu B 4.1 ein.</p><p>Begründe, weshalb es unter den Dreiecken AP<sub>n</sub>S kein Dreieck mit einem Flächeninhalt von 35 cm<sup>2</sup> gibt.</p>", "img": null, "sol": [{"t": "Trage \\(\\s{SP_1}=3\\cm\\) auf \\([SC]\\) ab und zeichne das Dreieck \\(AP_1S\\).", "m": null}, {"t": "Jedes Dreieck \\(AP_nS\\) ist ein Teil des Dreiecks ACS, weil \\(P_n\\) auf \\([CS]\\) liegt. Seine Fläche ist also immer kleiner als die von ACS.", "m": "\\begin{aligned}A_{ACS} &= 0{,}5\\cdot 11\\cdot 7\\cdot\\sin 60^\\circ\\cmq = 33{,}34\\cmq\\end{aligned}"}, {"t": "Da schon das ganze Dreieck ACS kleiner als 35 cm² ist, gibt es kein Dreieck \\(AP_nS\\) mit 35 cm².", "m": "\\begin{aligned}A_{AP_nS} &< 33{,}34\\cmq < 35\\cmq\\end{aligned}"}]}, {"label": "B 4.4", "pts": "3", "text": "<p>Die Strecke <span class=\"ov\">AP<sub>0</sub></span> besitzt unter den Strecken <span class=\"ov\">AP<sub>n</sub></span> die minimale Länge.</p><p>Zeichne diese Strecke in das Schrägbild zu B 4.1 ein und berechne deren Länge.</p>", "img": null, "sol": [{"t": "Die kürzeste Strecke von A zu \\([CS]\\) ist das Lot. \\(P_0\\) ist der Lotfußpunkt, also gilt ∢\\(AP_0C\\) = 90°.", "m": null}, {"t": "Zuerst ∢SCA im rechtwinkligen Dreieck MCS:", "m": "\\begin{aligned}\\cos\\w SCA &= \\dfrac{\\s{CM}}{\\s{CS}} = \\dfrac{11-3{,}5}{9{,}64}\\\\[3pt]\\w SCA &= 38{,}92^\\circ\\end{aligned}"}, {"t": "Im rechtwinkligen Dreieck \\(AP_0C\\) ist \\([AP_0]\\) Gegenkathete zu ∢SCA, \\([AC]\\) die Hypotenuse.", "m": "\\begin{aligned}\\sin 38{,}92^\\circ &= \\dfrac{\\s{AP_0}}{11\\cm}\\\\[3pt]\\s{AP_0} &= \\erg{6{,}91\\cm}\\end{aligned}"}]}, {"label": "B 4.5", "pts": "4", "text": "<p>Die Punkte P<sub>n</sub> sind Spitzen von Pyramiden ABCDP<sub>n</sub> mit den Höhen <span class=\"ov\">P<sub>n</sub>H<sub>n</sub></span>.</p><p>Zeichne die Pyramide ABCDP<sub>1</sub> und die zugehörige Höhe <span class=\"ov\">P<sub>1</sub>H<sub>1</sub></span> in das Schrägbild zu B 4.1 ein.</p><p>Zeige, dass für das Volumen der Pyramiden ABCDP<sub>n</sub> in Abhängigkeit von x gilt: V(x) = (88,88 − 9,24x) cm<sup>3</sup>.</p>", "img": null, "sol": [{"t": "Zeichne die Pyramide \\(ABCDP_1\\) und die Höhe \\([P_1H_1]\\) parallel zu \\([MS]\\).", "m": null}, {"t": "Grundfläche ist der Drachen ABCD:", "m": "\\begin{aligned}V &= \\tfrac13\\cdot\\tfrac12\\cdot\\s{AC}\\cdot\\s{BD}\\cdot\\s{P_nH_n}\\end{aligned}"}, {"t": "Vierstreckensatz mit Zentrum C (\\(P_nH_n\\parallel SM\\)), \\(\\s{CP_n}=(9{,}64-x)\\cm\\).", "m": "\\begin{aligned}\\dfrac{\\s{P_nH_n}}{6{,}06\\cm} &= \\dfrac{(9{,}64-x)\\cm}{9{,}64\\cm}\\\\[3pt]\\s{P_nH_n}(x) &= (6{,}06-0{,}63x)\\cm\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}V(x) &= \\tfrac13\\cdot\\tfrac12\\cdot 11\\cdot 8\\cdot(6{,}06-0{,}63x)\\cmk\\\\[3pt]V(x) &= \\erg{(88{,}88-9{,}24x)\\cmk}\\end{aligned}"}]}, {"label": "B 4.6", "pts": "2", "text": "<p>In der Pyramide ABCDP<sub>2</sub> gilt: |<span class=\"ov\">P<sub>2</sub>H<sub>2</sub></span>| = 4 cm.</p><p>Berechne das Volumen der Pyramide ABCDP<sub>2</sub> und den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Mit der gegebenen Höhe 4 cm direkt das Volumen berechnen.", "m": "\\begin{aligned}V_{ABCDP_2} &= \\tfrac13\\cdot\\tfrac12\\cdot 11\\cdot 8\\cdot 4\\cmk = \\erg{58{,}67\\cmk}\\end{aligned}"}, {"t": "Dann V(x) gleichsetzen:", "m": "\\begin{aligned}58{,}67 &= 88{,}88-9{,}24x\\\\[3pt]9{,}24x &= 30{,}21\\\\[3pt]x &= \\erg{3{,}27}\\end{aligned}"}]}]}]}, {"id": "ex", "name": "Exponentialfunktion und Logarithmus", "short": "10.3", "tasks": [{"id": "ex18htA1", "year": 2018, "term": "Haupttermin", "nr": "A 1", "notr": false, "pts": "5", "stmt": ["n_2018ht_A1_0"], "note": null, "subs": [{"label": "A 1.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Setze die x-Werte in \\(y=5000\\cdot 1{,}75^x\\) ein und runde auf Tausender.", "m": "\\begin{aligned}\\begin{array}{c|ccccc}x&0&1&2&3&4\\\\\\hline y&5000&9000&15\\,000&27\\,000&47\\,000\\end{array}\\end{aligned}"}, {"t": "Trage die Punkte ins Koordinatensystem ein und verbinde sie zu einer glatten, immer steiler steigenden Kurve.", "m": null}], "solimg": "ns_2018ht_A1_A11", "solcap": "Graph aus dem Lösungsmuster"}, {"label": "A 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Eine Zunahme um 600 % bedeutet: Zum Anfangswert kommen noch 6-mal 5000 dazu. Das Ergebnis ist das 7-Fache.", "m": "\\begin{aligned}y &= 5000+6\\cdot 5000 = 7\\cdot 5000 = 35\\,000\\end{aligned}"}, {"t": "Geh bei y = 35 000 waagrecht zum Graphen und lies den x-Wert ab.", "m": "\\begin{aligned}x &\\approx \\erg{3{,}5\\text{ Jahre}}\\end{aligned}"}]}, {"label": "A 1.3", "pts": "1", "text": "", "img": null, "sol": [{"t": "Der Wachstumsfaktor ist 1,75 = 1 + 0,75.", "m": "\\begin{aligned}&\\erg{75\\,\\%}\\text{ Zunahme pro Jahr}\\end{aligned}"}]}]}, {"id": "ex18ntA1", "year": 2018, "term": "Nachtermin", "nr": "A 1", "notr": false, "pts": "5", "stmt": ["n_2018nt_A1_0"], "note": null, "subs": [{"label": "A 1.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "x-Werte in \\(y=500\\cdot 1{,}03^x\\) einsetzen und auf Hunderter runden.", "m": "\\begin{aligned}\\begin{array}{c|cccccc}x&0&10&20&35&50&70\\\\\\hline y&500&700&900&1400&2200&4000\\end{array}\\end{aligned}"}, {"t": "Punkte eintragen und zu einer glatten Kurve verbinden.", "m": null}], "solimg": "ns_2018nt_A1_A11", "solcap": "Graph aus dem Lösungsmuster"}, {"label": "A 1.2", "pts": "1", "text": "", "img": null, "sol": [{"t": "Versechsfacht heißt y = 6 · 500 = 3000. Bei y = 3000 waagrecht zum Graphen und den x-Wert ablesen.", "m": "\\begin{aligned}x &\\approx \\erg{61\\text{ Jahre}}\\end{aligned}"}]}, {"label": "A 1.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "In 7 Jahren wird der Bestand 7-mal mit 1,03 multipliziert.", "m": "\\begin{aligned}1{,}03^7 &\\approx 1{,}23 = 1+0{,}23\\\\[3pt]&\\erg{\\text{Zunahme um }23\\,\\%}\\end{aligned}"}]}]}, {"id": "ex19ntA3", "year": 2019, "term": "Nachtermin", "nr": "A 3", "notr": false, "pts": "5", "stmt": ["n_2019nt_A3_0"], "note": null, "subs": [{"label": "A 3.1", "pts": "1", "text": "", "img": null, "sol": [{"t": "Der Wachstumsfaktor ist 0,87 < 1. Pro Kilometer bleiben 87 % übrig:", "m": "\\begin{aligned}1-0{,}87 &= 0{,}13 = \\erg{13\\,\\%}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "1", "text": "", "img": null, "sol": [{"t": "Gehe auf der y-Achse zu 460 hPa, waagrecht zum Graphen und senkrecht hinunter zur x-Achse. Ablesen:", "m": "\\begin{aligned}x &\\approx \\erg{5{,}7\\ \\text{km}}\\end{aligned}"}]}, {"label": "A 3.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Faustregel: 11 km = 2 · 5,5 km, der Luftdruck halbiert sich also zweimal (ein Viertel):", "m": "\\begin{aligned}0{,}25\\cdot 1013\\ \\text{hPa} &\\approx 253\\ \\text{hPa}\\end{aligned}"}, {"t": "Wert mit der Funktionsgleichung für x = 11:", "m": "\\begin{aligned}y &= 1013\\cdot 0{,}87^{11}\\ \\text{hPa} \\approx 219\\ \\text{hPa}\\end{aligned}"}, {"t": "Prozentuale Abweichung bezogen auf den Funktionswert:", "m": "\\begin{aligned}\\dfrac{253-219}{219} &\\approx \\erg{16\\,\\%}\\end{aligned}"}]}]}, {"id": "ex20htA1", "year": 2020, "term": "Haupttermin", "nr": "A 1", "notr": false, "pts": "5", "stmt": ["n_2020ht_A1_0"], "note": null, "subs": [{"label": "A 1.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Setze die x-Werte in \\(y=2000\\cdot1{,}07^x\\) ein und runde auf Ganze:", "m": "\\begin{aligned}x=0:&\\;\\; 2000\\qquad x=5:\\;\\; 2805\\qquad x=10:\\;\\; 3934\\\\[3pt]x=15:&\\;\\; 5518\\qquad x=20:\\;\\; 7739\\qquad x=25:\\;\\; 10855\\end{aligned}"}, {"t": "Trage die Punkte ins Koordinatensystem ein und verbinde sie zu einer glatten Kurve.", "m": null}], "solimg": "ns_2020ht_A1_A11", "solcap": "Graph aus dem Lösungsmuster"}, {"label": "A 1.2", "pts": "1", "text": "", "img": null, "sol": [{"t": "Der Wachstumsfaktor 1,07 bedeutet 100 % + 7 %:", "m": "\\begin{aligned}&1{,}07 = 1+0{,}07\\\\[2pt]&\\Rightarrow\\;\\erg{7\\,\\%}\\end{aligned}"}]}, {"label": "A 1.3", "pts": "1", "text": "", "img": null, "sol": [{"t": "Verfünffacht: 5 · 2000 € = 10 000 €. Waagrecht von 10 000 zum Graphen, dann senkrecht zur x-Achse:", "m": "\\begin{aligned}x &\\approx \\erg{24\\ \\text{Jahre}}\\end{aligned}"}]}, {"label": "A 1.4", "pts": "1", "text": "", "img": null, "sol": [{"t": "Von 2020 bis 2065 vergehen 45 Jahre:", "m": "\\begin{aligned}y &= 2000\\cdot 1{,}07^{2065-2020}\\\\[3pt]y &= 2000\\cdot 1{,}07^{45} \\approx \\erg{42\\,005\\ \\text{€}}\\end{aligned}"}]}]}, {"id": "ex1", "year": 2024, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "6,5", "intro": "<p>Auf einer Internetseite wird jeweils am 1. Januar eines Jahres die Anzahl an Kegelrobben im Wattenmeer bekannt gegeben. Am 1. Januar 2011 wurden 3300 Kegelrobben genannt. Die Anzahl y der Kegelrobben nach x Jahren seit dem 1. Januar 2011 kann näherungsweise durch die Funktion f: y = 3300 · 1,1<sup>x</sup> (x, y ∈ IR<sub>0</sub><sup>+</sup>) beschrieben werden.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 1.1", "pts": "1", "text": "<p>Kreuze an, um wie viel Prozent die Anzahl der Kegelrobben im Wattenmeer laut der Funktion f pro Jahr zunimmt.</p><p class=\"opt\">☐ 0,1 %          ☐ 1,1 %          ☐ 10 %          ☐ 110 %</p>", "img": null, "sol": [{"t": "Der Wachstumsfaktor ist 1,1 = 100 % + 10 %. Pro Jahr kommen also 10 % dazu.", "m": "\\begin{aligned}1{,}1 &= 1+0{,}10\\;\\Rightarrow\\;\\erg{10\\,\\%}\\end{aligned}"}]}, {"label": "B 1.2", "pts": "1,5", "text": "<p>Zeichne den Graphen der Funktion f für x ∈ [0; 8] in das Koordinatensystem ein.</p>", "img": "e01", "sol": [{"t": "Lege eine Wertetabelle an (gerundet) und trage die Punkte ein. Verbinde sie zu einer glatten, steigenden Kurve.", "m": "\\begin{aligned}\\begin{array}{c|ccccccccc}x&0&1&2&3&4&5&6&7&8\\\\\\hline y&3300&3630&3993&4392&4832&5315&5846&6431&7074\\end{array}\\end{aligned}"}], "solimg": "ex_sol_01", "solcap": "Graph aus dem Lösungsmuster"}, {"label": "B 1.3", "pts": "1,5", "text": "<p>Berechne, welche Anzahl an Kegelrobben laut der Funktion f am 1. Januar 2025 bekannt gegeben werden würde. Runde auf Hunderter.</p>", "img": null, "sol": [{"t": "Der 1. Januar 2025 liegt 2025 − 2011 = 14 Jahre nach dem Start. Setze x = 14 ein.", "m": "\\begin{aligned}y &= 3300\\cdot 1{,}1^{2025-2011} = 3300\\cdot 1{,}1^{14}\\\\[3pt]y &\\approx 12\\,531 \\approx \\erg{12\\,500}\\end{aligned}"}, {"t": "Am 1. Januar 2025 würden laut f rund 12 500 Kegelrobben angegeben.", "m": null}]}, {"label": "B 1.4", "pts": "2,5", "text": "<p>Ermittle rechnerisch das Datum, an dem laut der Funktion f erstmals eine Anzahl von mehr als 20 000 Kegelrobben bekannt gegeben werden würde.</p>", "img": null, "sol": [{"t": "Setze y = 20 000 und löse nach x auf. Zuerst durch 3300 teilen, dann logarithmieren.", "m": "\\begin{aligned}20\\,000 &= 3300\\cdot 1{,}1^x\\\\[3pt]1{,}1^x &= \\dfrac{20\\,000}{3300}\\\\[3pt]x &= \\log_{1{,}1}\\left(\\dfrac{20\\,000}{3300}\\right)\\\\[3pt]x &\\approx 18{,}9\\end{aligned}"}, {"t": "Angegeben wird nur am 1. Januar. Nach 18 Jahren (2029) sind es noch weniger als 20 000, erst nach 19 Jahren mehr.", "m": "\\begin{aligned}2011+19 &= 2030\\;\\Rightarrow\\;\\erg{\\text{1. Januar 2030}}\\end{aligned}"}]}]}, {"id": "ex2", "year": 2025, "term": "Haupttermin", "nr": "B 2", "notr": false, "pts": "6", "intro": "<p>Die Staatsverschuldung eines Landes A lag am 01.01.2025 bei 1600 Milliarden Euro. Man nimmt an, dass die Entwicklung der Staatsverschuldung dieses Landes näherungsweise mithilfe der Funktion f: y = 1600 · 1,03<sup>x</sup> (x, y ∈ IR<sub>0</sub><sup>+</sup>) dargestellt werden kann. Dabei gibt x die Anzahl der Jahre seit dem 01.01.2025 und y die Staatsverschuldung in Milliarden Euro an.</p><p>Runde im Folgenden auf Ganze.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 2.1", "pts": "1", "text": "<p>Gib an, um wie viel Prozent die Staatsverschuldung entsprechend der Funktion f jährlich zunimmt.</p>", "img": null, "sol": [{"t": "Wachstumsfaktor 1,03 = 1 + 0,03.", "m": "\\begin{aligned}&\\erg{3\\,\\%}\\text{ pro Jahr}\\end{aligned}"}]}, {"label": "B 2.2", "pts": "2", "text": "<p>Berechne die Staatsverschuldung laut der Funktion f am 01.01.2045.</p>", "img": null, "sol": [{"t": "Vom 01.01.2025 bis zum 01.01.2045 vergehen 20 Jahre.", "m": "\\begin{aligned}y &= 1600\\cdot 1{,}03^{2045-2025} = 1600\\cdot 1{,}03^{20}\\\\[3pt]y &\\approx \\erg{2890}\\text{ Milliarden Euro}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "2", "text": "<p>Berechne, nach wie vielen Jahren sich die Staatsverschuldung im Vergleich zum 01.01.2025 laut der Funktion f erstmals vervierfacht haben wird.</p>", "img": null, "sol": [{"t": "Vervierfacht heißt: y = 4 · 1600. Die 1600 kürzt sich weg.", "m": "\\begin{aligned}4\\cdot 1600 &= 1600\\cdot 1{,}03^x\\\\[3pt]1{,}03^x &= 4\\\\[3pt]x &= \\log_{1{,}03} 4 \\approx 46{,}9\\end{aligned}"}, {"t": "Nach 46 Jahren ist es noch nicht ganz das Vierfache, nach 47 Jahren schon.", "m": "\\begin{aligned}&\\erg{\\text{nach 47 Jahren}}\\end{aligned}"}]}, {"label": "B 2.4", "pts": "1", "text": "<p>Die Staatsverschuldung des Landes B war am 01.01.2025 halb so groß wie die des Landes A, es wird aber die gleiche jährliche prozentuale Zunahme angenommen.</p><p>Kreuze die Aussage an, die laut der Annahmen für den 01.01.2032 zutrifft.</p><p class=\"opt\">☐  Die Staatsverschuldung des Landes B ist weniger als halb so groß wie die des Landes A.</p><p class=\"opt\">☐  Die Staatsverschuldung des Landes B ist immer noch halb so groß wie die des Landes A.</p><p class=\"opt\">☐  Die Staatsverschuldung des Landes B ist mehr als halb so groß wie die des Landes A.</p><p class=\"opt\">☐  Keine der vorherigen Aussagen trifft zu.</p>", "img": null, "sol": [{"t": "Land B: \\(y_B = 800\\cdot 1{,}03^x\\), Land A: \\(y_A = 1600\\cdot 1{,}03^x\\). Der Quotient bleibt immer gleich.", "m": "\\begin{aligned}\\dfrac{y_B}{y_A} &= \\dfrac{800\\cdot 1{,}03^x}{1600\\cdot 1{,}03^x} = \\dfrac12\\end{aligned}"}, {"t": "Also ist die Verschuldung von B auch 2032 noch genau halb so groß.", "m": "\\begin{aligned}&\\erg{\\text{immer noch halb so groß}}\\end{aligned}"}]}]}, {"id": "ex3", "year": 2025, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "5", "intro": "<p>Liane hat sich ein Fahrzeug mit Elektroantrieb (E-Auto) gekauft, das zum Zeitpunkt des Kaufes eine Reichweite von 450 km hatte. Unter der Reichweite ihres E-Autos versteht sie die durchschnittliche Wegstrecke in Kilometer, die es nach vollständiger Ladung des Akkus maximal zurücklegen kann.</p><p>Liane geht davon aus, dass sich die Reichweite y km nach x Jahren seit dem Kauf annähernd mithilfe der Funktion f: y = 450 · 0,97<sup>x</sup> (x, y ∈ IR<sub>0</sub><sup>+</sup>) berechnen lässt.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 2.1", "pts": "1", "text": "<p>Gib an, um wie viel Prozent die Reichweite ihres E-Autos laut der Funktion f pro Jahr abnimmt.</p>", "img": null, "sol": [{"t": "Abnahmefaktor 0,97 = 1 − 0,03.", "m": "\\begin{aligned}&\\erg{3\\,\\%}\\text{ Abnahme pro Jahr}\\end{aligned}"}]}, {"label": "B 2.2", "pts": "2", "text": "<p>Berechne mithilfe der Funktion f die Reichweite von Lianes E-Auto acht Jahre nach dem Kauf.</p><p>Ermittle sodann rechnerisch den prozentualen Anteil dieser Reichweite an der Reichweite ihres E-Autos beim Kauf.</p><p>Runde auf Ganze.</p>", "img": null, "sol": [{"t": "x = 8 einsetzen.", "m": "\\begin{aligned}y &= 450\\cdot 0{,}97^8\\,\\mathrm{km} \\approx \\erg{353\\,\\mathrm{km}}\\end{aligned}"}, {"t": "Anteil an der ursprünglichen Reichweite (450 km):", "m": "\\begin{aligned}\\dfrac{353}{450}\\cdot 100\\,\\% &\\approx \\erg{78\\,\\%}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "2", "text": "<p>Berechne, im wievielten Jahr nach dem Kauf Lianes E-Auto laut der Funktion f nur noch eine Reichweite von 390 km hat.</p>", "img": null, "sol": [{"t": "y = 390 setzen und mit dem Logarithmus nach x auflösen.", "m": "\\begin{aligned}450\\cdot 0{,}97^x &= 390\\\\[3pt]0{,}97^x &= \\dfrac{390}{450}\\\\[3pt]x &= \\log_{0{,}97}\\left(\\dfrac{390}{450}\\right) \\approx 4{,}7\\end{aligned}"}, {"t": "x = 4,7 liegt zwischen 4 und 5 Jahren nach dem Kauf, also im fünften Jahr.", "m": "\\begin{aligned}&\\erg{\\text{im 5. Jahr}}\\end{aligned}"}]}]}]}, {"id": "qu", "name": "Quadratische Funktionen und Gleichungen", "short": "10.4", "tasks": [{"id": "qu18htB1", "year": 2018, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "17", "stmt": ["n_2018ht_B1_0"], "note": null, "subs": [{"label": "B 1.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "P und Q einsetzen:", "m": "\\begin{aligned}\\text{I: }\\; 19 &= 0{,}5\\cdot(-2)^2-2b+c \\;\\Leftrightarrow\\; -2b+c = 17\\\\[3pt]\\text{II: }\\; -5 &= 0{,}5\\cdot 4^2+4b+c \\;\\Leftrightarrow\\; 4b+c = -13\\end{aligned}"}, {"t": "II − I:", "m": "\\begin{aligned}6b &= -30 \\\\[2pt]&\\Rightarrow\\; b = -5\\\\[3pt]c &= 17+2\\cdot(-5) = 7\\\\[3pt]p:\\; y &= \\erg{0{,}5x^2-5x+7}\\end{aligned}"}, {"t": "Zeichne p (Scheitel S(5|−5,5)) und g (y-Achsenabschnitt −2, Steigung 0,5) für \\(x\\in[0;10]\\).", "m": null}], "solimg": "ns_2018ht_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "x = 3: \\(A_1(3|-3{,}5)\\), \\(C_1(3|-0{,}5)\\). x = 6: \\(A_2(6|-5)\\), \\(C_2(6|1)\\). Die Diagonale \\([B_nD_n]\\) ist waagrecht, 2 LE lang und halbiert \\([A_nC_n]\\). B liegt 1 LE rechts, D 1 LE links vom Mittelpunkt.", "m": null}]}, {"label": "B 1.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Rauten gibt es, solange C über A liegt. Grenzen: Schnittpunkte von p und g.", "m": "\\begin{aligned}0{,}5x^2-5x+7 &= 0{,}5x-2\\\\[3pt]0{,}5x^2-5{,}5x+9 &= 0\\quad|\\cdot 2\\\\[3pt]x^2-11x+18 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{11\\pm\\sqrt{121-72}}{2} = \\dfrac{11\\pm 7}{2}\\\\[3pt]x_1=2;\\;\\; x_2 &= 9\\\\[2pt]&\\Rightarrow\\;\\erg{x\\in\\,]2;\\,9[}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "Senkrechte Diagonale: oben (g) minus unten (p).", "m": "\\begin{aligned}\\s{A_nC_n}(x) &= \\left[0{,}5x-2-(0{,}5x^2-5x+7)\\right]\\mathrm{LE} = \\erg{(-0{,}5x^2+5{,}5x-9)\\,\\mathrm{LE}}\\end{aligned}"}, {"t": "Für x = 6:", "m": "\\begin{aligned}\\s{A_2C_2} &= (-0{,}5\\cdot 36+33-9)\\,\\mathrm{LE} = 6\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Die Diagonalen halbieren sich senkrecht. Im rechtwinkligen Teildreieck mit den halben Diagonalen 1 LE und 3 LE gilt:", "m": "\\begin{aligned}\\tan\\tfrac{\\varphi}{2} &= \\dfrac{0{,}5\\cdot\\s{B_2D_2}}{0{,}5\\cdot\\s{A_2C_2}} = \\dfrac{1}{3}\\\\[3pt]\\varphi &= \\erg{36{,}87^\\circ}\\end{aligned}"}, {"t": "Seitenlänge mit Pythagoras:", "m": "\\begin{aligned}\\s{A_2B_2} &= \\sqrt{1^2+3^2}\\,\\mathrm{LE} = \\erg{3{,}16\\,\\mathrm{LE}}\\end{aligned}"}]}, {"label": "B 1.5", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(B_n\\) liegt 1 LE rechts vom Mittelpunkt \\(M_n\\) der Diagonale \\([A_nC_n]\\). Die y-Koordinate von \\(M_n\\) ist der Mittelwert:", "m": "\\begin{aligned}y_M &= \\dfrac{0{,}5x-2+0{,}5x^2-5x+7}{2} = 0{,}25x^2-2{,}25x+2{,}5\\\\[3pt]&\\erg{B_n(x+1\\,|\\,0{,}25x^2-2{,}25x+2{,}5)}\\end{aligned}"}]}, {"label": "B 1.6", "pts": "2", "text": "", "img": null, "sol": [{"t": "Rautenfläche = halbes Produkt der Diagonalen. \\([B_nD_n]\\) ist fest 2 LE, also ist die Fläche maximal, wenn \\([A_nC_n]\\) am längsten ist (Scheitel).", "m": "\\begin{aligned}x_S &= -\\dfrac{5{,}5}{2\\cdot(-0{,}5)} = 5{,}5\\\\[3pt]\\s{A_0C_0} &= -0{,}5\\cdot 5{,}5^2+5{,}5\\cdot 5{,}5-9 = 6{,}13\\,\\mathrm{LE}\\\\[3pt]A_{\\max} &= 0{,}5\\cdot 6{,}13\\cdot 2\\,\\mathrm{FE} = 6{,}13\\,\\mathrm{FE} < 7\\,\\mathrm{FE}\\end{aligned}"}]}]}, {"id": "qu18ntB1", "year": 2018, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "17", "stmt": ["n_2018nt_B1_0"], "note": null, "subs": [{"label": "B 1.1", "pts": "4", "text": "", "img": null, "sol": [{"t": "P und Q einsetzen:", "m": "\\begin{aligned}\\text{I: }\\; 10 &= 0{,}25\\cdot 36-6b+c \\;\\Leftrightarrow\\; -6b+c = 1\\\\[3pt]\\text{II: }\\; -5 &= 0{,}25\\cdot 16+4b+c \\;\\Leftrightarrow\\; 4b+c = -9\\end{aligned}"}, {"t": "II − I:", "m": "\\begin{aligned}10b &= -10 \\\\[2pt]&\\Rightarrow\\; b = -1\\\\[3pt]c &= 1+6\\cdot(-1) = -5\\\\[3pt]p:\\; y &= \\erg{0{,}25x^2-x-5}\\end{aligned}"}, {"t": "Zeichne p (Scheitel S(2|−6)) und g (y-Achsenabschnitt 1, Steigung −0,5) für \\(x\\in[-5;7]\\).", "m": null}], "solimg": "ns_2018nt_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "x = −2: \\(A_1(-2|-2)\\), \\(C_1(-2|2)\\). x = 3: \\(A_2(3|-5{,}75)\\), \\(C_2(3|-0{,}5)\\). \\(B_n\\) liegt auf g, 2 LE rechts von der Achse; \\(D_n\\) ist sein Spiegelpunkt 2 LE links.", "m": null}]}, {"label": "B 1.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(B_n\\) hat die Abszisse x + 2 und liegt auf g. \\(D_n\\) liegt auf gleicher Höhe 2 LE links.", "m": "\\begin{aligned}y_{B_n} &= -0{,}5(x+2)+1\\\\[3pt]&\\erg{D_n\\big(x-2\\,|\\,-0{,}5(x+2)+1\\big)}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "2", "text": "", "img": null, "sol": [{"t": "Länge der senkrechten Diagonale: oben (g) minus unten (p).", "m": "\\begin{aligned}\\s{A_nC_n}(x) &= \\left[-0{,}5x+1-(0{,}25x^2-x-5)\\right]\\mathrm{LE} = (-0{,}25x^2+0{,}5x+6)\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Drachenfläche = halbes Produkt der Diagonalen, \\(\\overline{B_nD_n}=2\\cdot 2\\) LE.", "m": "\\begin{aligned}A(x) &= 0{,}5\\cdot(-0{,}25x^2+0{,}5x+6)\\cdot 2\\cdot 2\\,\\mathrm{FE} = \\erg{(-0{,}5x^2+x+12)\\,\\mathrm{FE}}\\end{aligned}"}]}, {"label": "B 1.5", "pts": "3", "text": "", "img": null, "sol": [{"t": "Maximum im Scheitel:", "m": "\\begin{aligned}x_S &= -\\dfrac{0{,}5}{2\\cdot(-0{,}25)} = 1\\\\[3pt]\\s{A_0C_0} &= -0{,}25+0{,}5+6 = \\erg{6{,}25\\,\\mathrm{LE}}\\end{aligned}"}, {"t": "\\(B_0\\) hat die Abszisse 1 + 2 = 3 und liegt auf g.", "m": "\\begin{aligned}y &= -0{,}5\\cdot 3+1 = -0{,}5\\\\[2pt]&\\Rightarrow\\;\\erg{B_0(3\\,|\\,-0{,}5)}\\end{aligned}"}]}, {"label": "B 1.6", "pts": "3", "text": "", "img": null, "sol": [{"t": "\\(\\overline{B_nD_n}=4\\) LE, also muss \\(\\overline{A_nC_n}=1{,}5\\cdot 4=6\\) LE sein.", "m": "\\begin{aligned}-0{,}25x^2+0{,}5x+6 &= 6\\\\[3pt]-0{,}25x^2+0{,}5x &= 0\\\\[3pt]x\\cdot(-0{,}25x+0{,}5) &= 0\\\\[3pt]&\\erg{x=0\\;\\vee\\;x=2}\\end{aligned}"}]}, {"label": "B 1.7", "pts": "1", "text": "", "img": null, "sol": [{"t": "\\([B_nD_n]\\) ist immer waagrecht und \\([B_nC_n]\\) liegt immer auf g. Der Winkel zwischen g und einer Waagrechten ist immer derselbe, also auch ∢\\(C_nB_nD_n\\).", "m": null}]}]}, {"id": "qu19htA2", "year": 2019, "term": "Haupttermin", "nr": "A 2", "notr": false, "pts": "8", "stmt": ["n_2019ht_A2_0", "n_2019ht_A2_1"], "note": null, "subs": [{"label": "A 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Für x = 3: \\(B_1(3|-5{,}8)\\) auf \\(p_1\\), \\(C_1(3|3{,}7)\\) auf \\(p_2\\). Verbinde mit A(0|1).", "m": null}, {"t": "Länge der senkrechten Strecke: oben (\\(p_2\\)) minus unten (\\(p_1\\)).", "m": "\\begin{aligned}\\s{B_nC_n}(x) &= \\left[-0{,}2x^2+1{,}5x+1-(0{,}4x^2-1{,}8x-4)\\right]\\mathrm{LE}\\\\[3pt]\\s{B_nC_n}(x) &= \\erg{(-0{,}6x^2+3{,}3x+5)\\,\\mathrm{LE}}\\end{aligned}"}], "solimg": "ns_2019ht_A2_A21", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "Setze die Länge gleich 10 und prüfe, ob es eine Lösung gibt.", "m": "\\begin{aligned}-0{,}6x^2+3{,}3x+5 &= 10\\\\[3pt]-0{,}6x^2+3{,}3x-5 &= 0\\\\[3pt]D &= 3{,}3^2-4\\cdot(-0{,}6)\\cdot(-5) = 10{,}89-12 = -1{,}11 < 0\\end{aligned}"}, {"t": "Die Diskriminante ist negativ, die Gleichung hat keine Lösung. Es gibt also kein solches Dreieck.", "m": "\\begin{aligned}L &= \\erg{\\{\\}}\\end{aligned}"}]}, {"label": "A 2.3", "pts": "1", "text": "", "img": null, "sol": [{"t": "Die y-Koordinate des Mittelpunkts ist der Mittelwert der beiden y-Werte.", "m": "\\begin{aligned}y_M &= \\dfrac{-0{,}2x^2+1{,}5x+1+0{,}4x^2-1{,}8x-4}{2}\\\\[3pt]y_M &= \\dfrac{0{,}2x^2-0{,}3x-3}{2} = \\erg{0{,}1x^2-0{,}15x-1{,}5}\\end{aligned}"}]}, {"label": "A 2.4", "pts": "3", "text": "", "img": null, "sol": [{"t": "Bei der Basis \\([B_2C_2]\\) liegt A auf der Mittelsenkrechten der Basis. Diese ist waagrecht durch \\(M_2\\), also gilt \\(y_M=y_A=1\\).", "m": "\\begin{aligned}0{,}1x^2-0{,}15x-1{,}5 &= 1\\quad|\\cdot 10\\\\[3pt]x^2-1{,}5x-25 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{1{,}5\\pm\\sqrt{2{,}25+100}}{2}\\\\[3pt]x_1 &= -4{,}31\\notin\\,]0;6{,}74[;\\quad x_2 = \\erg{5{,}81}\\end{aligned}"}]}]}, {"id": "qu19ntB1", "year": 2019, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "17", "stmt": ["n_2019nt_B1_0"], "note": null, "subs": [{"label": "B 1.1", "pts": "5", "text": "", "img": null, "sol": [{"t": "Die Symmetrieachse geht durch den Scheitel S(4|2):", "m": "\\begin{aligned}&\\erg{x = 4}\\end{aligned}"}, {"t": "Scheitelform aufstellen und P(−2|−7) einsetzen:", "m": "\\begin{aligned}-7 &= a\\cdot(-2-4)^2+2\\\\[3pt]-7 &= 36a+2\\\\[3pt]a &= -0{,}25\\end{aligned}"}, {"t": "Scheitelform ausmultiplizieren:", "m": "\\begin{aligned}y &= -0{,}25\\cdot(x-4)^2+2\\\\[3pt]y &= -0{,}25(x^2-8x+16)+2\\\\[3pt]y &= \\erg{-0{,}25x^2+2x-2}\\end{aligned}"}, {"t": "Zeichne p (Wertetabelle oder Scheitel und Symmetrie) und g (y-Achsenabschnitt 5, Steigung −0,5).", "m": null}], "solimg": "ns_2019nt_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster (auch B 1.2)"}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "x = 4: \\(A_1(4|2)\\), \\(B_1(4|3)\\); x = 8,5: \\(A_2(8{,}5|-3{,}06)\\), \\(B_2(8{,}5|0{,}75)\\). C und D liegen jeweils 4 LE weiter links bzw. rechts (Höhe 4 LE), symmetrisch zur Mittelsenkrechten von [A<sub>n</sub>B<sub>n</sub>] mit \\(\\overline{C_nD_n}=6\\) LE.", "m": null}]}, {"label": "B 1.3", "pts": "2", "text": "", "img": null, "sol": [{"t": "Länge von \\([A_nB_n]\\): y-Wert von g minus y-Wert von p:", "m": "\\begin{aligned}\\s{A_nB_n}(x) &= [(-0{,}5x+5)-(-0{,}25x^2+2x-2)]\\,\\mathrm{LE}\\\\[3pt]\\s{A_nB_n}(x) &= (0{,}25x^2-2{,}5x+7)\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Trapezformel mit h = 4 LE:", "m": "\\begin{aligned}A(x) &= 0{,}5\\cdot(0{,}25x^2-2{,}5x+7+6)\\cdot 4\\ \\mathrm{FE}\\\\[3pt]A(x) &= \\erg{(0{,}5x^2-5x+26)\\ \\mathrm{FE}}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "2", "text": "", "img": null, "sol": [{"t": "Quadratische Ergänzung, um den Scheitel des Terms zu finden:", "m": "\\begin{aligned}A(x) &= 0{,}5(x^2-10x+25-25)+26\\\\[3pt]A(x) &= 0{,}5(x-5)^2+13{,}5\\end{aligned}"}, {"t": "Minimum am Scheitel:", "m": "\\begin{aligned}A_{\\min} &= \\erg{13{,}5\\ \\mathrm{FE}}\\ \\text{für}\\ x=\\erg{5}\\end{aligned}"}]}, {"label": "B 1.5", "pts": "4", "text": "", "img": null, "sol": [{"t": "Flächeninhalt gleich 25 setzen:", "m": "\\begin{aligned}0{,}5x^2-5x+26 &= 25\\quad|\\cdot 2\\\\[3pt]x^2-10x+2 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{10\\pm\\sqrt{100-8}}{2}\\\\[3pt]x_1 &= \\erg{0{,}20};\\quad x_2 = \\erg{9{,}80}\\end{aligned}"}, {"t": "Wären die Trapeze Rechtecke, müsste \\(\\overline{A_nB_n}=\\overline{C_nD_n}=6\\) LE gelten, also A = 6 · 4 FE = 24 FE. Die Trapeze haben aber 25 FE – sie sind also <b>keine</b> Rechtecke.", "m": null}]}, {"label": "B 1.6", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(\\overline{A_1B_1}\\) für x = 4:", "m": "\\begin{aligned}\\s{A_1B_1} &= (0{,}25\\cdot4^2-2{,}5\\cdot4+7)\\,\\mathrm{LE} = 1\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Im rechtwinkligen Teildreieck am Trapezschenkel ist h die Gegenkathete, der halbe Unterschied der Grundseiten die Ankathete von ε:", "m": "\\begin{aligned}\\tan\\varepsilon &= \\dfrac{h}{0{,}5\\cdot(\\s{C_1D_1}-\\s{A_1B_1})}\\\\[3pt]\\tan\\varepsilon &= \\dfrac{4}{0{,}5\\cdot(6-1)} = 1{,}6\\\\[3pt]\\varepsilon &= \\erg{57{,}99^\\circ}\\end{aligned}"}]}]}, {"id": "qu20htB1", "year": 2020, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "17", "stmt": ["n_2020ht_B1_0"], "note": null, "subs": [{"label": "B 1.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Scheitelform mit a = 0,1 und S(5|−4,5) aufstellen und ausmultiplizieren:", "m": "\\begin{aligned}y &= 0{,}1(x-5)^2-4{,}5\\\\[3pt]y &= 0{,}1(x^2-10x+25)-4{,}5\\\\[3pt]y &= \\erg{0{,}1x^2-x-2}\\end{aligned}"}, {"t": "Zeichne p und g für \\(x\\in[-4;9]\\).", "m": null}], "solimg": "ns_2020ht_B1_B11", "solcap": "Zeichnung aus dem Lösungsmuster (auch B 1.2)"}, {"label": "B 1.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "x = −1: \\(A_1(-1|1{,}5)\\), \\(B_1(-1|-0{,}9)\\); x = 4: \\(A_2(4|-1)\\), \\(B_2(4|-4{,}4)\\). \\(D_n\\) entsteht aus \\(A_n\\) durch den Pfeil (2|1); \\(C_n\\) liegt 5 LE senkrecht unter \\(D_n\\).", "m": null}]}, {"label": "B 1.3", "pts": "3", "text": "", "img": null, "sol": [{"t": "Trapeze gibt es, solange g oberhalb von p liegt. Schnittstellen berechnen:", "m": "\\begin{aligned}0{,}1x^2-x-2 &= -0{,}5x+1\\\\[3pt]0{,}1x^2-0{,}5x-3 &= 0\\quad|\\cdot10\\\\[3pt]x^2-5x-30 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{5\\pm\\sqrt{25+120}}{2}\\\\[2pt]&\\Rightarrow\\;x_1=-3{,}52;\\;x_2=8{,}52\\end{aligned}"}, {"t": "Ergebnis:", "m": "\\begin{aligned}&\\erg{x\\in\\,]-3{,}52;\\,8{,}52[}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "Länge \\([A_nB_n]\\): y-Wert von g minus y-Wert von p:", "m": "\\begin{aligned}\\s{A_nB_n}(x) &= [-0{,}5x+1-(0{,}1x^2-x-2)]\\,\\mathrm{LE}\\\\[3pt]\\s{A_nB_n}(x) &= (-0{,}1x^2+0{,}5x+3)\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Die Trapezhöhe ist die x-Komponente des Pfeils, also 2 LE:", "m": "\\begin{aligned}A(x) &= 0{,}5\\cdot(-0{,}1x^2+0{,}5x+3+5)\\cdot 2\\ \\mathrm{FE}\\\\[3pt]A(x) &= (-0{,}1x^2+0{,}5x+8)\\ \\mathrm{FE}\\end{aligned}"}, {"t": "Quadratische Ergänzung:", "m": "\\begin{aligned}A(x) &= -0{,}1(x^2-5x+6{,}25-6{,}25)+8\\\\[3pt]A(x) &= -0{,}1(x-2{,}5)^2+8{,}625\\\\[3pt]A_{\\max} &= \\erg{8{,}63\\ \\mathrm{FE}}\\ \\text{für}\\ x=\\erg{2{,}5}\\end{aligned}"}]}, {"label": "B 1.5", "pts": "2", "text": "", "img": null, "sol": [{"t": "\\(D_3\\) liegt 2 LE rechts von \\(A_3\\). Aus \\(x_{D_3}=0\\) folgt \\(x_{A_3}=x_{B_3}=-2\\):", "m": "\\begin{aligned}y &= 0{,}1\\cdot(-2)^2-(-2)-2 = 0{,}4\\\\[3pt]&\\erg{B_3(-2\\,|\\,0{,}4)}\\end{aligned}"}]}, {"label": "B 1.6", "pts": "3", "text": "", "img": null, "sol": [{"t": "Bei gleichschenkligen Trapezen ragt \\([C_nD_n]\\) oben und unten gleich weit über \\([A_nB_n]\\) hinaus – jeweils um die y-Komponente 1 des Pfeils:", "m": "\\begin{aligned}\\s{A_4B_4} &= \\s{C_nD_n}-2\\cdot1\\,\\mathrm{LE} = (5-2)\\,\\mathrm{LE} = \\erg{3\\,\\mathrm{LE}}\\end{aligned}"}, {"t": "Im Stützdreieck am Schenkel: Gegenkathete 2 (Höhe), Ankathete 1:", "m": "\\begin{aligned}\\tan\\gamma &= \\dfrac21\\\\[2pt]&\\Rightarrow\\;\\gamma = \\erg{63{,}43^\\circ}\\end{aligned}"}]}]}, {"id": "qu20ntA2", "year": 2020, "term": "Nachtermin", "nr": "A 2", "notr": false, "pts": "10", "stmt": ["n_2020nt_A2_0", "n_2020nt_A2_1"], "note": null, "subs": [{"label": "A 2.1", "pts": "2", "text": "", "img": null, "sol": [{"t": "Scheitelform mit a = 0,4 und S(2|−3):", "m": "\\begin{aligned}y &= 0{,}4(x-2)^2-3\\\\[3pt]y &= 0{,}4(x^2-4x+4)-3\\\\[3pt]y &= \\erg{0{,}4x^2-1{,}6x-1{,}4}\\end{aligned}"}, {"t": "Gerade g zeichnen: y-Achsenabschnitt 4, Steigung −0,3.", "m": null}]}, {"label": "A 2.2", "pts": "1", "text": "", "img": null, "sol": [{"t": "x = 2: \\(A_1(2|-3)\\), \\(C_1(2|3{,}4)\\). Die Diagonale \\([B_1D_1]\\) halbiert \\([A_1C_1]\\) senkrecht und ist 4 LE lang: \\(B_1\\) 2 LE rechts, \\(D_1\\) 2 LE links vom Mittelpunkt (2|0,2).", "m": null}], "solimg": "ns_2020nt_A2_A22", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 2.3", "pts": "4", "text": "", "img": null, "sol": [{"t": "Rautenfläche = halbes Produkt der Diagonalen. Länge \\([A_nC_n]\\): oben (g) minus unten (p):", "m": "\\begin{aligned}\\s{A_nC_n}(x) &= [-0{,}3x+4-(0{,}4x^2-1{,}6x-1{,}4)]\\,\\mathrm{LE}\\\\[3pt]\\s{A_nC_n}(x) &= (-0{,}4x^2+1{,}3x+5{,}4)\\,\\mathrm{LE}\\\\[3pt]A(x) &= 0{,}5\\cdot(-0{,}4x^2+1{,}3x+5{,}4)\\cdot 4\\ \\mathrm{FE}\\\\[3pt]A(x) &= \\erg{(-0{,}8x^2+2{,}6x+10{,}8)\\ \\mathrm{FE}}\\end{aligned}"}, {"t": "Größter Flächeninhalt mit quadratischer Ergänzung:", "m": "\\begin{aligned}A(x) &= -0{,}8(x^2-3{,}25x+1{,}625^2-1{,}625^2)+10{,}8\\\\[3pt]A(x) &= -0{,}8(x-1{,}625)^2+12{,}91\\\\[3pt]A_{\\max} &= 12{,}91\\ \\mathrm{FE} < 15\\ \\mathrm{FE}\\end{aligned}"}, {"t": "Der maximale Flächeninhalt ist kleiner als 15 FE – also gibt es <b>keine</b> Raute mit 15 FE.", "m": null}]}, {"label": "A 2.4", "pts": "3", "text": "", "img": null, "sol": [{"t": "Eine Raute ist ein Quadrat, wenn beide Diagonalen gleich lang sind: \\(\\overline{A_nC_n}=4\\) LE.", "m": "\\begin{aligned}-0{,}4x^2+1{,}3x+5{,}4 &= 4\\\\[3pt]-0{,}4x^2+1{,}3x+1{,}4 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{-1{,}3\\pm\\sqrt{1{,}69+2{,}24}}{-0{,}8}\\\\[3pt]x_1 &= -0{,}85;\\quad x_2 = 4{,}10\\end{aligned}"}, {"t": "B liegt 2 LE rechts von A bzw. C:", "m": "\\begin{aligned}x_{B_2} &= -0{,}85+2 = \\erg{1{,}15}\\\\[3pt]x_{B_3} &= 4{,}10+2 = \\erg{6{,}10}\\end{aligned}"}]}]}, {"id": "qu21htA2", "year": 2021, "term": "Haupttermin", "nr": "A 2", "notr": false, "pts": "10", "stmt": ["n_2021ht_A2_0", "n_2021ht_A2_1"], "note": null, "subs": [{"label": "A 2.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Schnittpunkte: Gleichsetzen der Funktionsterme:", "m": "\\begin{aligned}0{,}25x^2-3x+8 &= -0{,}25x+6{,}5\\\\[3pt]0{,}25x^2-2{,}75x+1{,}5 &= 0\\quad|\\cdot4\\\\[3pt]x^2-11x+6 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{11\\pm\\sqrt{121-24}}{2}\\\\[2pt]&\\Rightarrow\\;x_1=0{,}58;\\;x_2=10{,}42\\end{aligned}"}, {"t": "In g einsetzen:", "m": "\\begin{aligned}y_A &= -0{,}25\\cdot0{,}58+6{,}5 = 6{,}36\\\\[2pt]&\\Rightarrow\\;\\erg{A(0{,}58\\,|\\,6{,}36)}\\\\[3pt]y_B &= -0{,}25\\cdot10{,}42+6{,}5 = 3{,}90\\\\[2pt]&\\Rightarrow\\;\\erg{B(10{,}42\\,|\\,3{,}90)}\\end{aligned}"}]}, {"label": "A 2.2", "pts": "2", "text": "", "img": null, "sol": [{"t": "x = 7: \\(P_1(7|-0{,}75)\\), \\(Q_1(7|4{,}75)\\). Mittelpunkt \\(M_1(7|2)\\), Radius \\(0{,}5\\cdot 5{,}5 = 2{,}75\\) LE.", "m": null}], "solimg": "ns_2021ht_A2_A22", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 2.3", "pts": "1", "text": "", "img": null, "sol": [{"t": "Oben (g) minus unten (p):", "m": "\\begin{aligned}\\s{P_nQ_n}(x) &= [-0{,}25x+6{,}5-(0{,}25x^2-3x+8)]\\,\\mathrm{LE}\\\\[3pt]\\s{P_nQ_n}(x) &= \\erg{(-0{,}25x^2+2{,}75x-1{,}5)\\,\\mathrm{LE}}\\end{aligned}"}]}, {"label": "A 2.4", "pts": "2", "text": "", "img": null, "sol": [{"t": "Umfang = Durchmesser · π:", "m": "\\begin{aligned}u(x) &= (-0{,}25x^2+2{,}75x-1{,}5)\\cdot\\pi\\ \\mathrm{LE}\\end{aligned}"}, {"t": "Größter Durchmesser über quadratische Ergänzung:", "m": "\\begin{aligned}-0{,}25x^2+2{,}75x-1{,}5 &= -0{,}25(x-5{,}5)^2+6{,}06\\\\[3pt]u_{\\max} &= 6{,}0625\\cdot\\pi\\ \\mathrm{LE} \\approx \\erg{19{,}05\\ \\mathrm{LE}}\\end{aligned}"}]}, {"label": "A 2.5", "pts": "2", "text": "", "img": null, "sol": [{"t": "Ja. Aus \\(d_3=4\\cdot d_2\\) folgt \\(r_3=4\\cdot r_2\\):", "m": "\\begin{aligned}A_3 &= r_3^2\\cdot\\pi = (4\\cdot r_2)^2\\cdot\\pi = 16\\cdot r_2^2\\cdot\\pi = \\erg{16\\cdot A_2}\\end{aligned}"}]}]}, {"id": "qu21ntA2", "year": 2021, "term": "Nachtermin", "nr": "A 2", "notr": false, "pts": "11", "stmt": ["n_2021nt_A2_0", "n_2021nt_A2_1"], "note": "Kein Lösungsmuster vorhanden – Lösung selbst erstellt", "subs": [{"label": "A 2.1", "pts": "3", "text": "", "img": null, "sol": [{"t": "Normalparabel nach oben (a = 1) mit Scheitel S(1|−4) in Scheitelform, dann ausmultiplizieren:", "m": "\\begin{aligned}y &= (x-1)^2-4\\\\[3pt]y &= x^2-2x+1-4 = \\erg{x^2-2x-3}\\end{aligned}"}, {"t": "Zeichne q mit einer Wertetabelle für \\(x\\in[-2;4]\\).", "m": null}]}, {"label": "A 2.2", "pts": "3", "text": "", "img": null, "sol": [{"t": "Gleichsetzen:", "m": "\\begin{aligned}x^2-2x-3 &= -0{,}5x^2+2x+3\\\\[3pt]1{,}5x^2-4x-6 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{4\\pm\\sqrt{16+36}}{3}\\\\[2pt]&\\Rightarrow\\;x_A=-1{,}07;\\;x_C=3{,}74\\end{aligned}"}, {"t": "In q einsetzen:", "m": "\\begin{aligned}y_A &= (-1{,}07)^2-2\\cdot(-1{,}07)-3 \\approx 0{,}29\\\\[2pt]&\\Rightarrow\\;\\erg{A(-1{,}07\\,|\\,0{,}29)}\\\\[3pt]y_C &= 3{,}74^2-2\\cdot3{,}74-3 \\approx 3{,}49\\\\[2pt]&\\Rightarrow\\;\\erg{C(3{,}74\\,|\\,3{,}49)}\\end{aligned}"}]}, {"label": "A 2.3", "pts": "1", "text": "", "img": null, "sol": [{"t": "x = 1: \\(B_1(1|-4)\\) auf q (Scheitel) und \\(D_1(1|4{,}5)\\) auf p. Verbinde A, \\(B_1\\), C, \\(D_1\\).", "m": null}]}, {"label": "A 2.4", "pts": "4", "text": "", "img": null, "sol": [{"t": "Ein Trapez mit diesen Grundseiten liegt vor, wenn \\([AD_1]\\parallel[B_1C]\\), d. h. die Pfeile Vielfache voneinander sind:", "m": "\\begin{aligned}\\overrightarrow{AD_1} &= \\begin{pmatrix}1+1{,}07\\\\ 4{,}5-0{,}29\\end{pmatrix} = \\begin{pmatrix}2{,}07\\\\ 4{,}21\\end{pmatrix}\\\\[3pt]\\overrightarrow{B_1C} &= \\begin{pmatrix}3{,}74-1\\\\ 3{,}49+4\\end{pmatrix} = \\begin{pmatrix}2{,}74\\\\ 7{,}49\\end{pmatrix}\\end{aligned}"}, {"t": "Vergleich der Steigungen:", "m": "\\begin{aligned}\\dfrac{4{,}21}{2{,}07} &\\approx 2{,}03 \\neq 2{,}73 \\approx \\dfrac{7{,}49}{2{,}74}\\end{aligned}"}, {"t": "Die Pfeile sind nicht parallel – das Viereck ist <b>kein</b> Trapez mit diesen Grundseiten.", "m": null}]}]}, {"id": "qu1", "year": 2022, "term": "Haupttermin", "nr": "A 3", "notr": false, "pts": "4", "intro": "<p>Ein Floh kann bezogen auf seine Körpergröße sehr weit und sehr hoch springen.</p><p>Ein solcher Sprung kann näherungsweise durch die Parabel p: y = −0,1x<sup>2</sup> + 3,5x (G = IR<sub>0</sub><sup>+</sup> × IR<sub>0</sub><sup>+</sup>) beschrieben werden. Dabei entspricht x cm der horizontal gemessenen Entfernung vom Absprungpunkt P(0 | 0) und y cm der zugehörigen Höhe über dem Boden. Der Floh landet im Punkt Q(x<sub>Q</sub> | 0) auf dem Boden.</p>", "fig": "q01", "figw": 5.6, "bigfig": false, "subs": [{"label": "A 3.1", "pts": "3", "text": "<p>Berechne die Koordinaten des Scheitelpunkts S der Parabel p.</p><p>Zeichne sodann die Parabel p für x ∈ [0; x<sub>Q</sub>] in das Koordinatensystem ein.</p>", "img": "q01k", "sol": [{"t": "Für \\(y=ax^2+bx+c\\) liegt der Scheitel bei \\(S\\left(-\\frac{b}{2a}\\,\\middle|\\, c-\\frac{b^2}{4a}\\right)\\). Hier ist a = −0,1, b = 3,5, c = 0.", "m": "\\begin{aligned}x_S &= -\\dfrac{3{,}5}{2\\cdot(-0{,}1)} = 17{,}5\\\\[3pt]y_S &= 0-\\dfrac{3{,}5^2}{4\\cdot(-0{,}1)} = 30{,}625\\\\[3pt]&\\erg{S(17{,}5\\,|\\,30{,}625)}\\end{aligned}"}, {"t": "Der Landepunkt Q ist die zweite Nullstelle. Wegen der Symmetrie zum Scheitel liegt er bei \\(x_Q=2\\cdot 17{,}5=35\\). Zeichne die Parabel durch P(0|0), S und Q(35|0). Hilfspunkte findest du mit einer Wertetabelle, z. B. (10|25) und (25|25).", "m": null}], "solimg": "qu_sol_01", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 3.2", "pts": "1", "text": "<p>Gib die maximale Höhe und die Weite dieses Sprungs an. Runde auf ganze Zentimeter.</p><p class=\"opt\">maximale Höhe: __________ cm          Weite: __________ cm</p>", "img": null, "sol": [{"t": "Die maximale Höhe ist die y-Koordinate des Scheitels, die Weite ist der Abstand von P zu Q.", "m": "\\begin{aligned}\\text{maximale Höhe} &\\approx \\erg{31\\,\\mathrm{cm}}\\\\[3pt]\\text{Weite} &= \\erg{35\\,\\mathrm{cm}}\\end{aligned}"}]}]}, {"id": "qu2", "year": 2022, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "16", "intro": "<p>Die Parabel p mit dem Scheitelpunkt S(3 | 5) hat eine Gleichung der Form y = −0,5x<sup>2</sup> + bx + c mit G = IR × IR und b, c ∈ IR.</p><p>Die Gerade g hat die Gleichung y = −0,25x − 3 mit G = IR × IR.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 1.1", "pts": "3", "text": "<p>Zeige rechnerisch, dass die Parabel p die Gleichung y = −0,5x<sup>2</sup> + 3x + 0,5 hat.</p><p>Zeichne sodann die Parabel p und die Gerade g für x ∈ [−2; 8] in ein Koordinatensystem ein.</p><p>Für die Zeichnung: Längeneinheit 1 cm; −2 ≤ x ≤ 10; −8 ≤ y ≤ 6</p>", "img": null, "sol": [{"t": "Mit dem Scheitel kannst du sofort die Scheitelform aufschreiben (a = −0,5).", "m": "\\begin{aligned}y &= -0{,}5\\cdot(x-3)^2+5\\end{aligned}"}, {"t": "Ausmultiplizieren mit der binomischen Formel:", "m": "\\begin{aligned}y &= -0{,}5\\cdot(x^2-6x+9)+5\\\\[3pt]y &= -0{,}5x^2+3x-4{,}5+5\\\\[3pt]y &= \\erg{-0{,}5x^2+3x+0{,}5}\\end{aligned}"}, {"t": "Zeichne p mit einer Wertetabelle für \\(x\\in[-2;8]\\) und g mit dem y-Achsenabschnitt −3 und der Steigung −0,25.", "m": null}], "solimg": "qu_sol_02", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "<p>Punkte B<sub>n</sub>(x | −0,25x − 3) auf der Geraden g und Punkte D<sub>n</sub>(x | −0,5x<sup>2</sup> + 3x + 0,5) auf der Parabel p haben dieselbe Abszisse x. Sie sind zusammen mit Punkten A<sub>n</sub> und C<sub>n</sub> Eckpunkte von Drachenvierecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>D<sub>n</sub> mit den Symmetrieachsen A<sub>n</sub>C<sub>n</sub> und den Diagonalenschnittpunkten M<sub>n</sub>.</p><p>Es gilt: |<span class=\"ov\">M<sub>n</sub>A<sub>n</sub></span>| = 2 LE; |<span class=\"ov\">M<sub>n</sub>C<sub>n</sub></span>| = 4 LE; y<sub>Dn</sub> &gt; y<sub>Bn</sub>.</p><p>Zeichne das Drachenviereck A<sub>1</sub>B<sub>1</sub>C<sub>1</sub>D<sub>1</sub> für x = 0 und das Drachenviereck A<sub>2</sub>B<sub>2</sub>C<sub>2</sub>D<sub>2</sub> für x = 6 in das Koordinatensystem zu B 1.1 ein.</p>", "img": null, "sol": [{"t": "Für x = 0: \\(B_1(0|-3)\\), \\(D_1(0|0{,}5)\\). Für x = 6: \\(B_2(6|-4{,}5)\\), \\(D_2(6|0{,}5)\\). Die Symmetrieachse \\(A_nC_n\\) ist waagrecht. M liegt so, dass \\(A_n\\) 2 LE links und \\(C_n\\) 4 LE rechts von \\(M_n\\) liegen. Bei einem Drachen halbiert die Symmetrieachse die andere Diagonale, deshalb ist \\(M_n\\) die Mitte von \\([B_nD_n]\\).", "m": null}]}, {"label": "B 1.3", "pts": "1", "text": "<p>Begründe, weshalb der Flächeninhalt der Dreiecke A<sub>n</sub>B<sub>n</sub>D<sub>n</sub> stets halb so groß wie der Flächeninhalt der Dreiecke B<sub>n</sub>C<sub>n</sub>D<sub>n</sub> ist.</p>", "img": null, "sol": [{"t": "Beide Dreiecke haben die gemeinsame Grundseite \\([B_nD_n]\\). Die Höhe von \\(A_nB_nD_n\\) ist \\(\\s{M_nA_n}=2\\) LE, die von \\(B_nC_nD_n\\) ist \\(\\s{M_nC_n}=4\\) LE. Halbe Höhe bei gleicher Grundseite ergibt halbe Fläche.", "m": "\\begin{aligned}A_{A_nB_nD_n} &= \\tfrac12\\cdot\\s{B_nD_n}\\cdot 2 = \\tfrac12\\cdot\\left(\\tfrac12\\cdot\\s{B_nD_n}\\cdot 4\\right) = \\tfrac12\\cdot A_{B_nC_nD_n}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "3", "text": "<p>Ermittle rechnerisch, für welche Werte von x es Drachenvierecke A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>D<sub>n</sub> gibt.</p>", "img": null, "sol": [{"t": "Drachen gibt es, solange \\(D_n\\) über \\(B_n\\) liegt. Die Grenzen sind die Schnittpunkte von p und g.", "m": "\\begin{aligned}-0{,}5x^2+3x+0{,}5 &= -0{,}25x-3\\\\[3pt]-0{,}5x^2+3{,}25x+3{,}5 &= 0\\quad|\\cdot(-2)\\\\[3pt]x^2-6{,}5x-7 &= 0\\end{aligned}"}, {"t": "Lösungsformel:", "m": "\\begin{aligned}x_{1,2} &= \\dfrac{6{,}5\\pm\\sqrt{6{,}5^2+4\\cdot 7}}{2} = \\dfrac{6{,}5\\pm\\sqrt{70{,}25}}{2}\\\\[3pt]x_1 &= -0{,}94;\\quad x_2 = 7{,}44\\\\[3pt]&\\erg{x\\in\\,]-0{,}94;\\,7{,}44[}\\end{aligned}"}]}, {"label": "B 1.5", "pts": "4", "text": "<p>Unter den Drachenvierecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>D<sub>n</sub> hat das Drachenviereck A<sub>0</sub>B<sub>0</sub>C<sub>0</sub>D<sub>0</sub> den maximalen Flächeninhalt.</p><p>Berechne diesen Flächeninhalt und den zugehörigen Wert für x.</p><p class=\"hint\">[Zwischenergebnis: |<span class=\"ov\">B<sub>n</sub>D<sub>n</sub></span>|(x) = (−0,5x<sup>2</sup> + 3,25x + 3,5) LE]</p>", "img": null, "sol": [{"t": "Drachenfläche = halbes Produkt der Diagonalen. \\([A_nC_n]\\) ist immer 2 + 4 = 6 LE lang.", "m": "\\begin{aligned}A &= 0{,}5\\cdot\\s{A_nC_n}\\cdot\\s{B_nD_n}\\\\[3pt]\\s{A_nC_n} &= (2+4)\\,\\mathrm{LE} = 6\\,\\mathrm{LE}\\end{aligned}"}, {"t": "\\(\\s{B_nD_n}\\) ist die Differenz der y-Koordinaten (oben minus unten).", "m": "\\begin{aligned}\\s{B_nD_n}(x) &= \\left[-0{,}5x^2+3x+0{,}5-(-0{,}25x-3)\\right]\\mathrm{LE}\\\\[3pt]\\s{B_nD_n}(x) &= (-0{,}5x^2+3{,}25x+3{,}5)\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}A(x) &= 0{,}5\\cdot 6\\cdot(-0{,}5x^2+3{,}25x+3{,}5)\\,\\mathrm{FE}\\\\[3pt]A(x) &= (-1{,}5x^2+9{,}75x+10{,}5)\\,\\mathrm{FE}\\end{aligned}"}, {"t": "Das Maximum liegt im Scheitel der nach unten geöffneten Parabel.", "m": "\\begin{aligned}x_S &= -\\dfrac{9{,}75}{2\\cdot(-1{,}5)} = 3{,}25\\\\[3pt]A_{\\max} &= -1{,}5\\cdot 3{,}25^2+9{,}75\\cdot 3{,}25+10{,}5 = 26{,}34\\\\[3pt]&\\erg{A_{\\max}=26{,}34\\,\\mathrm{FE}\\text{ für }x=3{,}25}\\end{aligned}"}]}, {"label": "B 1.6", "pts": "3", "text": "<p>Unter den Drachenvierecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>D<sub>n</sub> gibt es zwei Drachenvierecke A<sub>3</sub>B<sub>3</sub>C<sub>3</sub>D<sub>3</sub> und A<sub>4</sub>B<sub>4</sub>C<sub>4</sub>D<sub>4</sub>, die bei C<sub>3</sub> bzw. C<sub>4</sub> rechtwinklig sind.</p><p>Begründe, warum |<span class=\"ov\">B<sub>3</sub>D<sub>3</sub></span>| = |<span class=\"ov\">B<sub>4</sub>D<sub>4</sub></span>| = 8 LE gilt.</p><p>Berechne sodann die x-Koordinaten von B<sub>3</sub> und B<sub>4</sub>.</p>", "img": null, "sol": [{"t": "Ist der Drachen bei \\(C_n\\) rechtwinklig, sind die Dreiecke \\(B_nC_nM_n\\) und \\(D_nC_nM_n\\) gleichschenklig-rechtwinklig. Deshalb gilt \\(\\s{M_nB_n}=\\s{M_nD_n}=\\s{M_nC_n}=4\\) LE.", "m": "\\begin{aligned}\\s{B_3D_3} &= \\s{B_4D_4} = 2\\cdot\\s{M_nC_n} = 8\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Gleichsetzen mit dem Term aus B 1.5:", "m": "\\begin{aligned}-0{,}5x^2+3{,}25x+3{,}5 &= 8\\\\[3pt]-0{,}5x^2+3{,}25x-4{,}5 &= 0\\quad|\\cdot(-2)\\\\[3pt]x^2-6{,}5x+9 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{6{,}5\\pm\\sqrt{42{,}25-36}}{2} = \\dfrac{6{,}5\\pm 2{,}5}{2}\\\\[3pt]&\\erg{x=2\\;\\vee\\;x=4{,}5}\\end{aligned}"}]}]}, {"id": "qu3", "year": 2022, "term": "Nachtermin", "nr": "A 3", "notr": false, "pts": "5", "intro": "<p>An zwei Türmen sind auf einer Höhe von jeweils 15 m über dem Boden Plattformen angebracht. Zwischen den beiden 30 m voneinander entfernten Plattformen ist eine Brücke gespannt.</p><p>Der Verlauf der Brücke zwischen den Punkten A(0 | 15) und B(30 | 15) kann näherungsweise durch eine Parabel p beschrieben werden. Diese hat eine Gleichung der Form y = ax<sup>2</sup> + bx + c (G = IR<sub>0</sub><sup>+</sup> × IR<sub>0</sub><sup>+</sup>; a, b, c ∈ IR; a ≠ 0) und den Scheitelpunkt S(15 | 12,75). Dabei entspricht x m der horizontal gemessenen Entfernung vom Punkt A und y m der Höhe über dem Boden.</p>", "fig": "q03", "figw": 6.4, "bigfig": false, "subs": [{"label": "A 3.1", "pts": "3", "text": "<p>Zeige rechnerisch, dass für die Gleichung der Parabel p gilt: y = 0,01x<sup>2</sup> − 0,3x + 15 (G = IR<sub>0</sub><sup>+</sup> × IR<sub>0</sub><sup>+</sup>).</p>", "img": null, "sol": [{"t": "Mit dem Scheitel S(15|12,75) setzt du die Scheitelform an. Der Punkt A(0|15) liegt auf p und liefert a.", "m": "\\begin{aligned}y &= a\\cdot(x-15)^2+12{,}75\\\\[3pt]15 &= a\\cdot(0-15)^2+12{,}75\\\\[3pt]2{,}25 &= 225a\\\\[3pt]a &= 0{,}01\\end{aligned}"}, {"t": "In die allgemeine Form umrechnen:", "m": "\\begin{aligned}y &= 0{,}01\\cdot(x^2-30x+225)+12{,}75\\\\[3pt]y &= 0{,}01x^2-0{,}3x+2{,}25+12{,}75\\\\[3pt]y &= \\erg{0{,}01x^2-0{,}3x+15}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "2", "text": "<p>Eine Person überquert die Brücke von A nach B. Sie geht bereits wieder aufwärts. Bei einer Höhe von 13 Metern über dem Boden bleibt sie stehen. Diese Position entspricht dem Punkt D auf der Parabel p.</p><p>Berechne die x-Koordinate des Punktes D.</p>", "img": null, "sol": [{"t": "y = 13 setzen und die quadratische Gleichung lösen.", "m": "\\begin{aligned}13 &= 0{,}01x^2-0{,}3x+15\\\\[3pt]0 &= 0{,}01x^2-0{,}3x+2\\quad|\\cdot 100\\\\[3pt]0 &= x^2-30x+200\\\\[3pt]x_{1,2} &= \\dfrac{30\\pm\\sqrt{900-800}}{2} = \\dfrac{30\\pm 10}{2}\\\\[3pt]x_1 &= 10;\\quad x_2 = 20\\end{aligned}"}, {"t": "„Sie geht bereits wieder aufwärts“ heißt: Sie ist schon hinter dem tiefsten Punkt (x = 15). Also gilt nur x = 20.", "m": "\\begin{aligned}&\\erg{x_D=20}\\end{aligned}"}]}]}, {"id": "qu4", "year": 2022, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "17", "intro": "<p>Die Parabel p verläuft durch die Punkte P(−2 | 2,8) und Q(7 | 1). Sie hat eine Gleichung der Form y = −0,2x<sup>2</sup> + bx + c mit G = IR × IR und b, c ∈ IR.</p><p>Die Gerade g hat die Gleichung y = −0,2x − 1 mit G = IR × IR.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 1.1", "pts": "4", "text": "<p>Zeige durch Berechnung der Werte für b und c, dass die Parabel p die Gleichung y = −0,2x<sup>2</sup> + 0,8x + 5,2 hat.</p><p>Zeichne sodann die Parabel p und die Gerade g für x ∈ [−4; 9] in ein Koordinatensystem ein.</p><p>Für die Zeichnung: Längeneinheit 1 cm; −4 ≤ x ≤ 9; −4 ≤ y ≤ 7</p>", "img": null, "sol": [{"t": "P und Q einsetzen ergibt ein Gleichungssystem für b und c.", "m": "\\begin{aligned}\\text{I: }\\; 2{,}8 &= -0{,}2\\cdot(-2)^2+b\\cdot(-2)+c \\;\\Leftrightarrow\\; -2b+c = 3{,}6\\\\[3pt]\\text{II: }\\; 1 &= -0{,}2\\cdot 7^2+7b+c \\;\\Leftrightarrow\\; 7b+c = 10{,}8\\end{aligned}"}, {"t": "II − I eliminiert c:", "m": "\\begin{aligned}9b &= 7{,}2 \\;\\Rightarrow\\; b = 0{,}8\\\\[3pt]c &= 3{,}6+2\\cdot 0{,}8 = 5{,}2\\\\[3pt]p:\\; y &= \\erg{-0{,}2x^2+0{,}8x+5{,}2}\\end{aligned}"}, {"t": "Zeichne p mit einer Wertetabelle auf \\([-4;9]\\) (Scheitel bei x = 2, y = 6). Die Gerade g hat den y-Achsenabschnitt −1 und die Steigung −0,2.", "m": null}], "solimg": "qu_sol_04", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "<p>Punkte A<sub>n</sub>(x | −0,2x<sup>2</sup> + 0,8x + 5,2) auf der Parabel p und Punkte B<sub>n</sub>(x | −0,2x − 1) auf der Geraden g haben dieselbe Abszisse x. Punkte D<sub>n</sub> liegen auch auf der Parabel p und haben eine um drei größere Abszisse als die Punkte A<sub>n</sub>. Zusammen mit Punkten C<sub>n</sub> entstehen für x ∈ ]−3,60; 8,60[ Trapeze A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>D<sub>n</sub>.</p><p>Es gilt: <span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span> ∥ <span class=\"ov\">C<sub>n</sub>D<sub>n</sub></span> und |<span class=\"ov\">C<sub>n</sub>D<sub>n</sub></span>| = 4 LE.</p><p>Zeichne die Trapeze A<sub>1</sub>B<sub>1</sub>C<sub>1</sub>D<sub>1</sub> für x = −1 und A<sub>2</sub>B<sub>2</sub>C<sub>2</sub>D<sub>2</sub> für x = 3 in das Koordinatensystem zu B 1.1 ein.</p>", "img": null, "sol": [{"t": "Für x = −1: \\(A_1(-1|4{,}2)\\), \\(B_1(-1|-0{,}8)\\), \\(D_1(2|6)\\). Für x = 3: \\(A_2(3|5{,}8)\\), \\(B_2(3|-1{,}6)\\), \\(D_2(6|2{,}8)\\). \\(C_n\\) liegt 4 LE senkrecht unter \\(D_n\\), weil \\(C_nD_n\\parallel A_nB_n\\).", "m": null}]}, {"label": "B 1.3", "pts": "4", "text": "<p>Zeige, dass für den Flächeninhalt der Trapeze A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>D<sub>n</sub> in Abhängigkeit von der Abszisse x der Punkte A<sub>n</sub> gilt: A(x) = (−0,3x<sup>2</sup> + 1,5x + 15,3) FE.</p><p>Bestimme sodann den maximalen Flächeninhalt dieser Trapeze sowie den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Trapezfläche: Mittelwert der parallelen Seiten mal Abstand. Der Abstand der senkrechten Seiten ist der x-Unterschied, also 3 LE.", "m": "\\begin{aligned}A &= 0{,}5\\cdot\\left(\\s{A_nB_n}+\\s{C_nD_n}\\right)\\cdot 3\\end{aligned}"}, {"t": "\\(\\s{A_nB_n}\\) ist der Unterschied der y-Werte:", "m": "\\begin{aligned}\\s{A_nB_n}(x) &= \\left[-0{,}2x^2+0{,}8x+5{,}2-(-0{,}2x-1)\\right]\\mathrm{LE}\\\\[3pt]\\s{A_nB_n}(x) &= (-0{,}2x^2+x+6{,}2)\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Einsetzen:", "m": "\\begin{aligned}A(x) &= 0{,}5\\cdot(-0{,}2x^2+x+6{,}2+4)\\cdot 3\\,\\mathrm{FE}\\\\[3pt]A(x) &= \\erg{(-0{,}3x^2+1{,}5x+15{,}3)\\,\\mathrm{FE}}\\end{aligned}"}, {"t": "Maximum im Scheitel:", "m": "\\begin{aligned}x_S &= -\\dfrac{1{,}5}{2\\cdot(-0{,}3)} = 2{,}5\\\\[3pt]A_{\\max} &= -0{,}3\\cdot 2{,}5^2+1{,}5\\cdot 2{,}5+15{,}3 = 17{,}18\\\\[3pt]&\\erg{A_{\\max}=17{,}18\\,\\mathrm{FE}\\text{ für }x=2{,}5}\\end{aligned}"}]}, {"label": "B 1.4", "pts": "2", "text": "<p>Der Flächeninhalt der Trapeze A<sub>3</sub>B<sub>3</sub>C<sub>3</sub>D<sub>3</sub> und A<sub>4</sub>B<sub>4</sub>C<sub>4</sub>D<sub>4</sub> beträgt jeweils 16,5 FE.</p><p>Ermittle die zugehörigen Werte für x.</p>", "img": null, "sol": [{"t": "A(x) = 16,5 setzen.", "m": "\\begin{aligned}16{,}5 &= -0{,}3x^2+1{,}5x+15{,}3\\\\[3pt]0 &= -0{,}3x^2+1{,}5x-1{,}2\\quad|:(-0{,}3)\\\\[3pt]0 &= x^2-5x+4\\\\[3pt]x_{1,2} &= \\dfrac{5\\pm\\sqrt{25-16}}{2} = \\dfrac{5\\pm 3}{2}\\\\[3pt]&\\erg{x=1\\;\\vee\\;x=4}\\end{aligned}"}]}, {"label": "B 1.5", "pts": "2", "text": "<p>Zeige rechnerisch, dass für die y-Koordinate der Punkte D<sub>n</sub> in Abhängigkeit von der Abszisse x der Punkte A<sub>n</sub> gilt: y<sub>Dn</sub> = −0,2x<sup>2</sup> − 0,4x + 5,8.</p>", "img": null, "sol": [{"t": "\\(D_n\\) liegt auf p und hat die Abszisse x + 3. Setze x + 3 für x in die Parabelgleichung ein.", "m": "\\begin{aligned}y_{D_n} &= -0{,}2\\cdot(x+3)^2+0{,}8\\cdot(x+3)+5{,}2\\\\[3pt]&= -0{,}2\\cdot(x^2+6x+9)+0{,}8x+2{,}4+5{,}2\\\\[3pt]&= -0{,}2x^2-1{,}2x-1{,}8+0{,}8x+7{,}6\\\\[3pt]y_{D_n} &= \\erg{-0{,}2x^2-0{,}4x+5{,}8}\\end{aligned}"}]}, {"label": "B 1.6", "pts": "3", "text": "<p>Die Strecke <span class=\"ov\">A<sub>5</sub>D<sub>5</sub></span> im Trapez A<sub>5</sub>B<sub>5</sub>C<sub>5</sub>D<sub>5</sub> ist parallel zur x-Achse.</p><p>Berechne den Flächeninhalt dieses Trapezes.</p><p class=\"hint\">[Zwischenergebnis: x<sub>A5</sub> = 0,5]</p>", "img": null, "sol": [{"t": "\\([A_5D_5]\\) parallel zur x-Achse heißt: gleiche y-Koordinaten.", "m": "\\begin{aligned}-0{,}2x^2+0{,}8x+5{,}2 &= -0{,}2x^2-0{,}4x+5{,}8\\\\[3pt]1{,}2x &= 0{,}6\\\\[3pt]x &= 0{,}5\\end{aligned}"}, {"t": "In A(x) einsetzen:", "m": "\\begin{aligned}A(0{,}5) &= (-0{,}3\\cdot 0{,}5^2+1{,}5\\cdot 0{,}5+15{,}3)\\,\\mathrm{FE} = \\erg{15{,}98\\,\\mathrm{FE}}\\end{aligned}"}]}]}, {"id": "qu5", "year": 2023, "term": "Haupttermin", "nr": "A 2", "notr": true, "pts": "2", "intro": "<p>Die Funktion p hat eine Gleichung der Form y = −0,5x<sup>2</sup> + bx + c (b, c, x, y ∈ IR). Ihr Graph ist eine Parabel mit dem Scheitelpunkt S(−2 | 1,5).</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 2.1", "pts": "1", "text": "<p>Gib die Gleichung der Parabel in der Scheitelpunktsform an.</p>", "img": null, "sol": [{"t": "Scheitelform: \\(y=a\\cdot(x-x_S)^2+y_S\\). Mit a = −0,5 und S(−2|1,5):", "m": "\\begin{aligned}y &= -0{,}5\\cdot(x-(-2))^2+1{,}5\\\\[3pt]y &= \\erg{-0{,}5\\cdot(x+2)^2+1{,}5}\\end{aligned}"}]}, {"label": "A 2.2", "pts": "1", "text": "<p>Kreuze die Wertemenge der Funktion p an.</p><p class=\"opt\">☐ {y | y ≥ −2}          ☐ {y | y ≤ −2}          ☐ {y | y ≥ 1,5}          ☐ {y | y ≤ 1,5}</p>", "img": null, "sol": [{"t": "a = −0,5 < 0: Die Parabel ist nach unten geöffnet. Der Scheitel ist der höchste Punkt, also kommen nur y-Werte bis 1,5 vor.", "m": "\\begin{aligned}W &= \\erg{\\{y\\,|\\,y\\le 1{,}5\\}}\\end{aligned}"}]}]}, {"id": "qu6", "year": 2023, "term": "Haupttermin", "nr": "B 3", "notr": false, "pts": "15,5", "intro": "<p>Die Parabel p verläuft durch die Punkte P(6 | 6) und Q(8 | 3). Sie hat eine Gleichung der Form y = −0,25x<sup>2</sup> + bx + c (b, c, x, y ∈ IR).</p><p>Die Gerade g hat die Gleichung y = ⅕x − 1 (x, y ∈ IR).</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 3.1", "pts": "4", "text": "<p>Zeige durch Berechnung der Werte für b und c, dass die Parabel die Gleichung y = −0,25x<sup>2</sup> + 2x + 3 hat.</p><p>Zeichne sodann die Parabel p und die Gerade g für x ∈ [−2; 10] in ein Koordinatensystem ein.</p><p>Für die Zeichnung: Längeneinheit 1 cm; −2 ≤ x ≤ 11; −2 ≤ y ≤ 7</p>", "img": null, "sol": [{"t": "P und Q einsetzen:", "m": "\\begin{aligned}\\text{I: }\\; 6 &= -0{,}25\\cdot 6^2+6b+c \\;\\Leftrightarrow\\; 6b+c = 15\\\\[3pt]\\text{II: }\\; 3 &= -0{,}25\\cdot 8^2+8b+c \\;\\Leftrightarrow\\; 8b+c = 19\\end{aligned}"}, {"t": "II − I:", "m": "\\begin{aligned}2b &= 4 \\;\\Rightarrow\\; b=2\\\\[3pt]c &= 15-6\\cdot 2 = 3\\\\[3pt]p:\\; y &= \\erg{-0{,}25x^2+2x+3}\\end{aligned}"}, {"t": "Zeichne p (Scheitel S(4|7)) und g (y-Achsenabschnitt −1, Steigung ⅕) für \\(x\\in[-2;10]\\).", "m": null}], "solimg": "qu_sol_06", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 3.2", "pts": "2", "text": "<p>Punkte A<sub>n</sub>(x | ⅕x − 1) auf der Geraden g und Punkte C<sub>n</sub>(x | −0,25x<sup>2</sup> + 2x + 3) auf der Parabel p haben dieselbe Abszisse x und sind zusammen mit Punkten B<sub>n</sub> Eckpunkte von gleichseitigen Dreiecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>. Es gilt: y<sub>Cn</sub> &gt; y<sub>An</sub>.</p><p>Zeichne die Dreiecke A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> für x = 0 und A<sub>2</sub>B<sub>2</sub>C<sub>2</sub> für x = 5 in das Koordinatensystem zu B 3.1 ein.</p>", "img": null, "sol": [{"t": "Für x = 0: \\(A_1(0|-1)\\), \\(C_1(0|3)\\). Für x = 5: \\(A_2(5|0)\\), \\(C_2(5|6{,}75)\\). \\(B_n\\) ergänzt das gleichseitige Dreieck rechts von der Strecke \\([A_nC_n]\\). Konstruiere mit dem Zirkel (Radius \\(\\s{A_nC_n}\\) um \\(A_n\\) und \\(C_n\\)).", "m": null}]}, {"label": "B 3.3", "pts": "3", "text": "<p>Ermittle rechnerisch, für welche Belegungen von x es Dreiecke A<sub>n</sub>B<sub>n</sub>C<sub>n</sub> gibt.</p>", "img": null, "sol": [{"t": "Dreiecke gibt es, solange \\(C_n\\) über \\(A_n\\) liegt. Grenzen sind die Schnittpunkte von p und g.", "m": "\\begin{aligned}\\tfrac15x-1 &= -0{,}25x^2+2x+3\\\\[3pt]0 &= -0{,}25x^2+1{,}8x+4\\quad|\\cdot(-4)\\\\[3pt]0 &= x^2-7{,}2x-16\\\\[3pt]x_{1,2} &= \\dfrac{7{,}2\\pm\\sqrt{51{,}84+64}}{2}\\\\[3pt]x_1 &= -1{,}78;\\quad x_2 = 8{,}98\\\\[3pt]&\\erg{x\\in\\,]-1{,}78;\\,8{,}98[}\\end{aligned}"}]}, {"label": "B 3.4", "pts": "1", "text": "<p>Zeige durch Rechnung, dass für die Länge der Strecken <span class=\"ov\">A<sub>n</sub>C<sub>n</sub></span> in Abhängigkeit von x gilt: |<span class=\"ov\">A<sub>n</sub>C<sub>n</sub></span>|(x) = (−0,25x<sup>2</sup> + 1,8x + 4) LE.</p>", "img": null, "sol": [{"t": "Länge der senkrechten Strecke = y-Wert oben minus y-Wert unten.", "m": "\\begin{aligned}\\s{A_nC_n}(x) &= \\left[-0{,}25x^2+2x+3-\\left(\\tfrac15x-1\\right)\\right]\\mathrm{LE}\\\\[3pt]\\s{A_nC_n}(x) &= \\erg{(-0{,}25x^2+1{,}8x+4)\\,\\mathrm{LE}}\\end{aligned}"}]}, {"label": "B 3.5", "pts": "3", "text": "<p>Ermittle die maximale Streckenlänge |<span class=\"ov\">A<sub>0</sub>C<sub>0</sub></span>| sowie den zugehörigen Wert für x.</p><p>Berechne sodann den maximalen Flächeninhalt A<sub>max</sub> der Dreiecke A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>.</p>", "img": null, "sol": [{"t": "Maximum im Scheitel der Parabel von B 3.4:", "m": "\\begin{aligned}x_S &= -\\dfrac{1{,}8}{2\\cdot(-0{,}25)} = 3{,}6\\\\[3pt]\\s{A_0C_0} &= -0{,}25\\cdot 3{,}6^2+1{,}8\\cdot 3{,}6+4 = \\erg{7{,}24\\,\\mathrm{LE}}\\end{aligned}"}, {"t": "Fläche eines gleichseitigen Dreiecks mit Seite a: \\(A=\\frac{a^2}{4}\\sqrt3\\).", "m": "\\begin{aligned}A_{\\max} &= \\dfrac{7{,}24^2}{4}\\cdot\\sqrt3\\,\\mathrm{FE} = \\erg{22{,}70\\,\\mathrm{FE}}\\end{aligned}"}]}, {"label": "B 3.6", "pts": "2,5", "text": "<p>Die Winkel zwischen der Geraden g und den Strecken <span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span> haben jeweils das gleiche Maß.</p><p>Berechne das zugehörige Maß φ, für das gilt: φ &lt; 90°.</p>", "img": null, "sol": [{"t": "Zuerst der Steigungswinkel α von g. Die Steigung ist ⅕.", "m": "\\begin{aligned}\\tan\\alpha &= \\tfrac15 \\;\\Rightarrow\\; \\alpha = 11{,}31^\\circ\\end{aligned}"}, {"t": "\\([A_nC_n]\\) ist senkrecht, im gleichseitigen Dreieck ist ∢\\(B_nA_nC_n\\) = 60°. Von der Senkrechten zur x-Achse sind es 90°. Ziehe den 60°-Winkel und den Steigungswinkel ab.", "m": "\\begin{aligned}\\varphi &= 90^\\circ-11{,}31^\\circ-60^\\circ = \\erg{18{,}69^\\circ}\\end{aligned}"}]}]}, {"id": "qu7", "year": 2023, "term": "Nachtermin", "nr": "A 1", "notr": true, "pts": "2,5", "intro": "<p>Die Parabel p hat die Gleichung y = −0,25 · (x + 1)<sup>2</sup> + 3 (x, y ∈ IR).</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 1.1", "pts": "1", "text": "<p>Gib die Koordinaten des Scheitelpunkts S an.</p>", "img": null, "sol": [{"t": "Aus der Scheitelform \\(y=a\\cdot(x-x_S)^2+y_S\\) liest du direkt ab: \\(x_S=-1\\) (Vorzeichen umdrehen!) und \\(y_S=3\\).", "m": "\\begin{aligned}&\\erg{S(-1\\,|\\,3)}\\end{aligned}"}]}, {"label": "A 1.2", "pts": "1,5", "text": "<p>Zeichne die Parabel p für x ∈ [−5; 3] in das Koordinatensystem ein.</p>", "img": "q07k", "sol": [{"t": "Wertetabelle mit Hilfe der Symmetrie zum Scheitel:", "m": "\\begin{aligned}\\begin{array}{c|ccccccccc}x&-5&-4&-3&-2&-1&0&1&2&3\\\\\\hline y&-1&0{,}75&2&2{,}75&3&2{,}75&2&0{,}75&-1\\end{array}\\end{aligned}"}, {"t": "Punkte eintragen und zu einer nach unten geöffneten Parabel verbinden.", "m": null}], "solimg": "qu_sol_07", "solcap": "Zeichnung aus dem Lösungsmuster"}]}, {"id": "qu8", "year": 2023, "term": "Nachtermin", "nr": "A 2", "notr": true, "pts": "2", "intro": "", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 2", "pts": "2", "text": "<p>Löse die Gleichung 0,5x<sup>2</sup> + x − 4 = 0 (x ∈ IR).</p>", "img": null, "sol": [{"t": "Mit 2 multiplizieren, damit vor x² eine 1 steht.", "m": "\\begin{aligned}0{,}5x^2+x-4 &= 0\\quad|\\cdot 2\\\\[3pt]x^2+2x-8 &= 0\\end{aligned}"}, {"t": "Lösungsformel (oder Faktorisieren: \\((x+4)(x-2)=0\\)):", "m": "\\begin{aligned}x_{1,2} &= \\dfrac{-2\\pm\\sqrt{4+32}}{2} = \\dfrac{-2\\pm 6}{2}\\\\[3pt]&\\erg{x=-4\\;\\vee\\;x=2}\\end{aligned}"}]}]}, {"id": "qu9", "year": 2023, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "6", "intro": "<p>Gegeben sind die Parabel p mit der Gleichung y = 0,25x<sup>2</sup> − x + 2 (x, y ∈ IR) und die Gerade g mit der Gleichung y = 0,25x − 1 (x, y ∈ IR).</p>", "fig": "q09", "figw": null, "bigfig": true, "subs": [{"label": "B 2.1", "pts": "2", "text": "<p>Punkte A<sub>n</sub>(x | 0,25x − 1) auf der Geraden g und Punkte B<sub>n</sub>(x | 0,25x<sup>2</sup> − x + 2) auf der Parabel p haben dieselbe Abszisse x. Sie sind zusammen mit Punkten C<sub>n</sub> Eckpunkte von Dreiecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>.</p><p>Es gilt: <img class=\"inl\" src=\"img/vec.png\" alt=\"\"></p><p>Zeichne die Dreiecke A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> für x = 0 und A<sub>2</sub>B<sub>2</sub>C<sub>2</sub> für x = 4 in das Koordinatensystem ein.</p>", "img": null, "sol": [{"t": "Für x = 0: \\(A_1(0|-1)\\), \\(B_1(0|2)\\). Für x = 4: \\(A_2(4|0)\\), \\(B_2(4|2)\\). \\(C_n\\) erhältst du, indem du von \\(A_n\\) aus 4 nach links und 3 nach oben gehst (Pfeil \\(\\binom{-4}{3}\\)).", "m": null}]}, {"label": "B 2.2", "pts": "1", "text": "<p>Zeige rechnerisch, dass für die Länge der Strecken <span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span> in Abhängigkeit von der Abszisse x der Punkte A<sub>n</sub> gilt: |<span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span>|(x) = (0,25x<sup>2</sup> − 1,25x + 3) LE.</p>", "img": null, "sol": [{"t": "Senkrechte Strecke: y-Wert oben minus y-Wert unten.", "m": "\\begin{aligned}\\s{A_nB_n}(x) &= \\left[0{,}25x^2-x+2-(0{,}25x-1)\\right]\\mathrm{LE}\\\\[3pt]\\s{A_nB_n}(x) &= \\erg{(0{,}25x^2-1{,}25x+3)\\,\\mathrm{LE}}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "3", "text": "<p>Die Dreiecke A<sub>3</sub>B<sub>3</sub>C<sub>3</sub> und A<sub>4</sub>B<sub>4</sub>C<sub>4</sub> sind gleichschenklig mit der Basis <span class=\"ov\">B<sub>3</sub>C<sub>3</sub></span> bzw. <span class=\"ov\">B<sub>4</sub>C<sub>4</sub></span>.</p><p>Berechne die zugehörigen Werte von x. Runde auf zwei Stellen nach dem Komma.</p>", "img": null, "sol": [{"t": "Gleichschenklig mit Basis \\([B_nC_n]\\) heißt: \\(\\s{A_nB_n}=\\s{A_nC_n}\\). Die Länge von \\([A_nC_n]\\) ist immer die Länge des Pfeils.", "m": "\\begin{aligned}\\s{A_nC_n} &= \\sqrt{(-4)^2+3^2}\\,\\mathrm{LE} = 5\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Gleichsetzen:", "m": "\\begin{aligned}0{,}25x^2-1{,}25x+3 &= 5\\quad|\\cdot 4\\\\[3pt]x^2-5x-8 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{5\\pm\\sqrt{25+32}}{2}\\\\[3pt]&\\erg{x=-1{,}27\\;\\vee\\;x=6{,}27}\\end{aligned}"}]}]}, {"id": "qu10", "year": 2024, "term": "Haupttermin", "nr": "A 1", "notr": true, "pts": "3", "intro": "<p>Im folgenden Koordinatensystem ist die Parabel p gezeichnet (x, y ∈ IR).</p>", "fig": "q10", "figw": null, "bigfig": true, "subs": [{"label": "A 1.1", "pts": "2", "text": "<p>Gib die Gleichung der Parabel p in der Scheitelpunktsform an. Entnimm der Zeichnung die dazu erforderlichen Informationen.</p>", "img": null, "sol": [{"t": "Lies den Scheitel aus der Zeichnung ab: S(4|5).", "m": "\\begin{aligned}y &= a\\cdot(x-4)^2+5\\end{aligned}"}, {"t": "Geh vom Scheitel eine Einheit nach rechts: Die Parabel liegt dort 3 Einheiten tiefer. Also ist a = −3.", "m": "\\begin{aligned}y &= \\erg{-3\\cdot(x-4)^2+5}\\end{aligned}"}]}, {"label": "A 1.2", "pts": "1", "text": "<p>Gib die Gleichung einer Geraden an, die keinen gemeinsamen Punkt mit der Parabel p hat.</p>", "img": null, "sol": [{"t": "Eine Gerade, die ganz über der Parabel verläuft, schneidet sie nicht. Zum Beispiel y = x + 5: Am Scheitel (x = 4) ist die Gerade schon bei 9.", "m": "\\begin{aligned}&\\text{z. B. }\\erg{y=x+5}\\end{aligned}"}, {"t": "Kontrolle: Gleichsetzen ergibt \\(3x^2-23x+48=0\\). Die Diskriminante \\(23^2-4\\cdot 3\\cdot 48=-47\\) ist negativ, also gibt es keinen Schnittpunkt.", "m": null}]}]}, {"id": "qu11", "year": 2024, "term": "Haupttermin", "nr": "B 3", "notr": false, "pts": "15", "intro": "<p>Die Parabel p mit dem Scheitelpunkt S(2 | −7) verläuft durch den Punkt P(4 | −5). Sie hat eine Gleichung der Form y = ax<sup>2</sup> + bx + c mit a ∈ IR \\ {0} und b, c, x, y ∈ IR.</p><p>Die Gerade g hat die Gleichung y = 0,5x mit x, y ∈ IR.</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 3.1", "pts": "5", "text": "<p>Zeige durch Rechnung, dass für die Gleichung der Parabel p gilt: y = 0,5x<sup>2</sup> − 2x − 5.</p><p>Zeichne sodann die Parabel p sowie die Gerade g für x ∈ [−3; 7] in ein Koordinatensystem.</p><p>Für die Zeichnung: Längeneinheit 1 cm; −3 ≤ x ≤ 7; −7 ≤ y ≤ 6</p>", "img": null, "sol": [{"t": "Scheitelform mit S(2|−7) ansetzen und P(4|−5) einsetzen, um a zu bestimmen.", "m": "\\begin{aligned}y &= a\\cdot(x-2)^2-7\\\\[3pt]-5 &= a\\cdot(4-2)^2-7\\\\[3pt]2 &= 4a \\;\\Rightarrow\\; a = 0{,}5\\end{aligned}"}, {"t": "In die allgemeine Form umrechnen:", "m": "\\begin{aligned}y &= 0{,}5\\cdot(x^2-4x+4)-7\\\\[3pt]y &= \\erg{0{,}5x^2-2x-5}\\end{aligned}"}, {"t": "Zeichne p (nach oben geöffnet, Scheitel S(2|−7)) und g (Ursprungsgerade mit Steigung 0,5) für \\(x\\in[-3;7]\\).", "m": null}], "solimg": "qu_sol_11", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 3.2", "pts": "2", "text": "<p>Punkte A<sub>n</sub>(x | 0,5x<sup>2</sup> − 2x − 5) auf der Parabel p und Punkte B<sub>n</sub>(x | 0,5x) auf der Geraden g haben dieselbe Abszisse x. Sie sind für x ∈ ]−1,53; 6,53[ zusammen mit Punkten C<sub>n</sub> die Eckpunkte von Dreiecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub>. Die Punkte C<sub>n</sub> liegen ebenfalls auf der Geraden g und ihre Abszisse ist stets um 3 kleiner als die Abszisse x der Punkte B<sub>n</sub>.</p><p>Zeichne die Dreiecke A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> für x = 2 und A<sub>2</sub>B<sub>2</sub>C<sub>2</sub> für x = 5,5 in das Koordinatensystem zu B 3.1 ein.</p>", "img": null, "sol": [{"t": "Für x = 2: \\(A_1(2|-7)\\), \\(B_1(2|1)\\), \\(C_1(-1|-0{,}5)\\). Für x = 5,5: \\(A_2(5{,}5|-0{,}875)\\), \\(B_2(5{,}5|2{,}75)\\), \\(C_2(2{,}5|1{,}25)\\). \\(C_n\\) liegt auf g, 3 Einheiten links von \\(B_n\\).", "m": null}]}, {"label": "B 3.3", "pts": "1", "text": "<p>Zeige rechnerisch, dass für die Länge der Strecken <span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span> in Abhängigkeit von x gilt: |<span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span>|(x) = (−0,5x<sup>2</sup> + 2,5x + 5) LE.</p>", "img": null, "sol": [{"t": "Hier liegt \\(B_n\\) oben (Gerade) und \\(A_n\\) unten (Parabel).", "m": "\\begin{aligned}\\s{A_nB_n}(x) &= \\left[0{,}5x-(0{,}5x^2-2x-5)\\right]\\mathrm{LE}\\\\[3pt]\\s{A_nB_n}(x) &= \\erg{(-0{,}5x^2+2{,}5x+5)\\,\\mathrm{LE}}\\end{aligned}"}]}, {"label": "B 3.4", "pts": "2,5", "text": "<p>Unter den Strecken <span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span> hat die Strecke <span class=\"ov\">A<sub>0</sub>B<sub>0</sub></span> die maximale Länge.</p><p>Berechne die Länge der Strecke <span class=\"ov\">A<sub>0</sub>B<sub>0</sub></span> sowie den zugehörigen Flächeninhalt des Dreiecks A<sub>0</sub>B<sub>0</sub>C<sub>0</sub>.</p>", "img": null, "sol": [{"t": "Maximum im Scheitel:", "m": "\\begin{aligned}x_S &= -\\dfrac{2{,}5}{2\\cdot(-0{,}5)} = 2{,}5\\\\[3pt]\\s{A_0B_0} &= -0{,}5\\cdot 2{,}5^2+2{,}5\\cdot 2{,}5+5 = \\erg{8{,}13\\,\\mathrm{LE}}\\end{aligned}"}, {"t": "Im Dreieck ist \\([A_0B_0]\\) die Grundseite. Die Höhe ist der waagrechte Abstand von \\(C_0\\) zu dieser senkrechten Seite, also immer 3 LE.", "m": "\\begin{aligned}A &= 0{,}5\\cdot 8{,}13\\cdot 3\\,\\mathrm{FE} = \\erg{12{,}20\\,\\mathrm{FE}}\\end{aligned}"}]}, {"label": "B 3.5", "pts": "1,5", "text": "<p>In allen Dreiecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub> haben die Winkel C<sub>n</sub>B<sub>n</sub>A<sub>n</sub> das gleiche Maß.</p><p>Berechne das zugehörige Maß β.</p><p class=\"hint\">[Ergebnis: β = 63,43°]</p>", "img": null, "sol": [{"t": "\\([B_nA_n]\\) ist senkrecht. Der Winkel zwischen g und der Waagrechten ist der Steigungswinkel mit tan = 0,5. Der Winkel β zur Senkrechten ergänzt ihn zu 90°.", "m": "\\begin{aligned}\\tan(90^\\circ-\\beta) &= 0{,}5\\\\[3pt]90^\\circ-\\beta &= 26{,}57^\\circ\\\\[3pt]\\beta &= \\erg{63{,}43^\\circ}\\end{aligned}"}]}, {"label": "B 3.6", "pts": "3", "text": "<p>Unter den Dreiecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub> gibt es die gleichschenkligen Dreiecke A<sub>3</sub>B<sub>3</sub>C<sub>3</sub> mit der Basis <span class=\"ov\">A<sub>3</sub>C<sub>3</sub></span> sowie A<sub>4</sub>B<sub>4</sub>C<sub>4</sub> mit der Basis <span class=\"ov\">A<sub>4</sub>C<sub>4</sub></span>.</p><p>Begründe rechnerisch, dass die Länge der Schenkel bei diesen gleichschenkligen Dreiecken stets 3,35 LE beträgt.</p><p>Berechne anschließend die zugehörigen Werte für x.</p>", "img": null, "sol": [{"t": "Basis \\([A_3C_3]\\) heißt: Die Schenkel \\([B_3A_3]\\) und \\([B_3C_3]\\) sind gleich lang. \\(\\s{B_nC_n}\\) ist für alle Dreiecke gleich, weil \\(C_n\\) immer 3 Einheiten links auf g liegt.", "m": null}, {"t": "Länge von \\([B_nC_n]\\) im Steigungsdreieck: waagrechte Kathete 3 LE, Winkel zur Senkrechten β.", "m": "\\begin{aligned}\\sin 63{,}43^\\circ &= \\dfrac{3\\,\\mathrm{LE}}{\\s{B_nC_n}}\\\\[3pt]\\s{B_nC_n} &= 3{,}35\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Gleichsetzen mit \\(\\s{A_nB_n}(x)\\):", "m": "\\begin{aligned}-0{,}5x^2+2{,}5x+5 &= 3{,}35\\quad|\\cdot(-2)\\\\[3pt]x^2-5x-3{,}3 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{5\\pm\\sqrt{25+13{,}2}}{2}\\\\[3pt]&\\erg{x=-0{,}59\\;\\vee\\;x=5{,}59}\\end{aligned}"}]}]}, {"id": "qu12", "year": 2024, "term": "Nachtermin", "nr": "A 3", "notr": true, "pts": "1,5", "intro": "<p>Die Parabel p hat die Gleichung y = 0,5x<sup>2</sup> − 3 (x, y ∈ IR).</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 3", "pts": "1,5", "text": "<p>Zeichne die Parabel p für x ∈ [−3; 3] in das Koordinatensystem ein.</p>", "img": "q12k", "sol": [{"t": "Der Scheitel ist S(0|−3). Wertetabelle (symmetrisch zur y-Achse):", "m": "\\begin{aligned}\\begin{array}{c|ccccccc}x&-3&-2&-1&0&1&2&3\\\\\\hline y&1{,}5&-1&-2{,}5&-3&-2{,}5&-1&1{,}5\\end{array}\\end{aligned}"}, {"t": "Punkte eintragen und zu einer nach oben geöffneten Parabel verbinden.", "m": null}], "solimg": "qu_sol_12", "solcap": "Zeichnung aus dem Lösungsmuster"}]}, {"id": "qu13", "year": 2024, "term": "Nachtermin", "nr": "A 4", "notr": true, "pts": "2", "intro": "<p>Die Parabel q hat die Gleichung y = −0,5x<sup>2</sup> + 2x + 1 (x, y ∈ IR).</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 4", "pts": "2", "text": "<p>Berechne die Koordinaten des Scheitelpunktes der Parabel q.</p>", "img": null, "sol": [{"t": "Scheitelformel für \\(y=ax^2+bx+c\\) mit a = −0,5, b = 2, c = 1:", "m": "\\begin{aligned}x_S &= -\\dfrac{b}{2a} = -\\dfrac{2}{2\\cdot(-0{,}5)} = 2\\\\[3pt]y_S &= c-\\dfrac{b^2}{4a} = 1-\\dfrac{2^2}{4\\cdot(-0{,}5)} = 1+2 = 3\\\\[3pt]&\\erg{S(2\\,|\\,3)}\\end{aligned}"}]}]}, {"id": "qu14", "year": 2025, "term": "Haupttermin", "nr": "A 2", "notr": true, "pts": "4,5", "intro": "<p>Die Parabel p mit dem Scheitelpunkt S(2 | 3) verläuft durch den Punkt P(0 | 1). Sie hat eine Gleichung der Form y = a · (x − x<sub>S</sub>)<sup>2</sup> + y<sub>S</sub> (a, x, y ∈ IR; a ≠ 0).</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 2.1", "pts": "2", "text": "<p>Zeige, dass gilt: a = −0,5.</p>", "img": null, "sol": [{"t": "Scheitel einsetzen, dann den Punkt P(0|1):", "m": "\\begin{aligned}y &= a\\cdot(x-2)^2+3\\\\[3pt]1 &= a\\cdot(0-2)^2+3\\\\[3pt]-2 &= 4a\\\\[3pt]a &= \\erg{-0{,}5}\\end{aligned}"}]}, {"label": "A 2.2", "pts": "1,5", "text": "<p>Zeichne die Parabel p für x ∈ [−1; 5] in das Koordinatensystem ein.</p>", "img": "q14k", "sol": [{"t": "Wertetabelle mit \\(y=-0{,}5(x-2)^2+3\\), symmetrisch um x = 2:", "m": "\\begin{aligned}\\begin{array}{c|ccccccc}x&-1&0&1&2&3&4&5\\\\\\hline y&-1{,}5&1&2{,}5&3&2{,}5&1&-1{,}5\\end{array}\\end{aligned}"}, {"t": "Punkte eintragen und verbinden.", "m": null}], "solimg": "qu_sol_14", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "A 2.3", "pts": "1", "text": "<p>Kreuze an, welche Gleichung ebenfalls die Parabel p beschreibt.</p><p class=\"opt\">☐  y = 0,5x<sup>2</sup> + 2x + 3</p><p class=\"opt\">☐  y = −0,5x<sup>2</sup> + 2x + 3</p><p class=\"opt\">☐  y = 0,5x<sup>2</sup> + 2x + 1</p><p class=\"opt\">☐  y = −0,5x<sup>2</sup> + 2x + 1</p>", "img": null, "sol": [{"t": "Scheitelform ausmultiplizieren:", "m": "\\begin{aligned}y &= -0{,}5\\cdot(x^2-4x+4)+3\\\\[3pt]y &= -0{,}5x^2+2x-2+3\\\\[3pt]y &= \\erg{-0{,}5x^2+2x+1}\\end{aligned}"}]}]}, {"id": "qu15", "year": 2025, "term": "Haupttermin", "nr": "A 3", "notr": true, "pts": "2", "intro": "<p>Die Parabel q ist der Graph der Funktion f: y = 2x<sup>2</sup> + 4x + 8 (x, y ∈ IR).</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 3", "pts": "2", "text": "<p>Berechne die y-Koordinate des Scheitelpunktes der Parabel q.</p><p>Gib sodann die Wertemenge der Funktion f an.</p>", "img": null, "sol": [{"t": "y-Koordinate des Scheitels mit a = 2, b = 4, c = 8:", "m": "\\begin{aligned}y_S &= c-\\dfrac{b^2}{4a} = 8-\\dfrac{4^2}{4\\cdot 2} = 8-2 = \\erg{6}\\end{aligned}"}, {"t": "a = 2 > 0: Die Parabel ist nach oben geöffnet, der Scheitel ist der tiefste Punkt.", "m": "\\begin{aligned}W &= \\erg{\\{y\\,|\\,y\\ge 6\\}}\\end{aligned}"}]}]}, {"id": "qu16", "year": 2025, "term": "Nachtermin", "nr": "B 3", "notr": false, "pts": "15", "intro": "<p>Die Parabel p verläuft durch die Punkte P(−5 | −14) und Q(−1 | 2). Sie hat eine Gleichung der Form y = −0,4x<sup>2</sup> + bx + c (b, c, x, y ∈ IR).</p><p>Die Gerade g hat die Gleichung y = 0,25x − 0,5 (x, y ∈ IR).</p><p>Runde im Folgenden auf zwei Stellen nach dem Komma.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 3.1", "pts": "4", "text": "<p>Zeige durch Berechnung der Werte für b und c, dass die Parabel p die Gleichung y = −0,4x<sup>2</sup> + 1,6x + 4 hat.</p><p>Zeichne sodann die Parabel p und die Gerade g für x ∈ [−3; 7] in ein Koordinatensystem.</p><p>Für die Zeichnung: Längeneinheit 1 cm; −3 ≤ x ≤ 7; −5 ≤ y ≤ 6</p>", "img": null, "sol": [{"t": "P und Q einsetzen:", "m": "\\begin{aligned}\\text{I: }\\; -14 &= -0{,}4\\cdot(-5)^2-5b+c \\;\\Leftrightarrow\\; -5b+c = -4\\\\[3pt]\\text{II: }\\; 2 &= -0{,}4\\cdot(-1)^2-b+c \\;\\Leftrightarrow\\; -b+c = 2{,}4\\end{aligned}"}, {"t": "II − I:", "m": "\\begin{aligned}4b &= 6{,}4 \\;\\Rightarrow\\; b = 1{,}6\\\\[3pt]c &= 2{,}4+1{,}6 = 4\\\\[3pt]p:\\; y &= \\erg{-0{,}4x^2+1{,}6x+4}\\end{aligned}"}, {"t": "Zeichne p (Scheitel S(2|5,6)) und g (y-Achsenabschnitt −0,5, Steigung 0,25) für \\(x\\in[-3;7]\\).", "m": null}], "solimg": "qu_sol_16", "solcap": "Zeichnung aus dem Lösungsmuster"}, {"label": "B 3.2", "pts": "2", "text": "<p>Punkte C<sub>n</sub>(x | −0,4x<sup>2</sup> + 1,6x + 4) auf der Parabel p und Punkte M<sub>n</sub>(x | 0,25x − 0,5) auf der Geraden g haben dieselbe Abszisse x.</p><p>Für x ∈ [−2,06; 5,44] sind die Strecken <span class=\"ov\">C<sub>n</sub>M<sub>n</sub></span> Höhen von gleichschenkligen Dreiecken A<sub>n</sub>B<sub>n</sub>C<sub>n</sub> mit den Basen <span class=\"ov\">A<sub>n</sub>B<sub>n</sub></span>.</p><p>Es gilt: |<span class=\"ov\">M<sub>n</sub>A<sub>n</sub></span>| = |<span class=\"ov\">M<sub>n</sub>B<sub>n</sub></span>| = 2 LE.</p><p>Zeichne die Dreiecke A<sub>1</sub>B<sub>1</sub>C<sub>1</sub> für x = −1 und A<sub>2</sub>B<sub>2</sub>C<sub>2</sub> für x = 3 sowie die zugehörigen Höhen <span class=\"ov\">C<sub>1</sub>M<sub>1</sub></span> und <span class=\"ov\">C<sub>2</sub>M<sub>2</sub></span> in das Koordinatensystem zu B 3.1 ein.</p>", "img": null, "sol": [{"t": "Für x = −1: \\(C_1(-1|2)\\), \\(M_1(-1|-0{,}75)\\). Für x = 3: \\(C_2(3|5{,}2)\\), \\(M_2(3|0{,}25)\\). Die Basis \\([A_nB_n]\\) ist waagrecht, \\(A_n\\) und \\(B_n\\) liegen je 2 LE links und rechts von \\(M_n\\).", "m": null}]}, {"label": "B 3.3", "pts": "3", "text": "<p>Zeige rechnerisch, dass für die Länge der Strecken <span class=\"ov\">C<sub>n</sub>M<sub>n</sub></span> in Abhängigkeit von x gilt: |<span class=\"ov\">C<sub>n</sub>M<sub>n</sub></span>|(x) = (−0,4x<sup>2</sup> + 1,35x + 4,5) LE.</p><p>Ermittle sodann die maximale Streckenlänge |<span class=\"ov\">C<sub>0</sub>M<sub>0</sub></span>| und den zugehörigen Wert für x.</p>", "img": null, "sol": [{"t": "Senkrechte Strecke: oben minus unten.", "m": "\\begin{aligned}\\s{C_nM_n}(x) &= \\left[-0{,}4x^2+1{,}6x+4-(0{,}25x-0{,}5)\\right]\\mathrm{LE}\\\\[3pt]\\s{C_nM_n}(x) &= \\erg{(-0{,}4x^2+1{,}35x+4{,}5)\\,\\mathrm{LE}}\\end{aligned}"}, {"t": "Maximum im Scheitel:", "m": "\\begin{aligned}x_S &= -\\dfrac{1{,}35}{2\\cdot(-0{,}4)} = 1{,}69\\\\[3pt]\\s{C_0M_0} &= \\erg{5{,}64\\,\\mathrm{LE}}\\text{ für }x=1{,}69\\end{aligned}"}]}, {"label": "B 3.4", "pts": "2", "text": "<p>Die Dreiecke A<sub>3</sub>B<sub>3</sub>C<sub>3</sub> und A<sub>4</sub>B<sub>4</sub>C<sub>4</sub> sind gleichschenklig-rechtwinklig.</p><p>Begründe, dass gilt: |<span class=\"ov\">C<sub>3</sub>M<sub>3</sub></span>| = |<span class=\"ov\">C<sub>4</sub>M<sub>4</sub></span>| = 2 LE.</p><p>Berechne sodann den Flächeninhalt der Dreiecke A<sub>3</sub>B<sub>3</sub>C<sub>3</sub> und A<sub>4</sub>B<sub>4</sub>C<sub>4</sub>.</p>", "img": null, "sol": [{"t": "Die Höhe \\([C_nM_n]\\) teilt das gleichschenklig-rechtwinklige Dreieck in zwei gleichschenklig-rechtwinklige Hälften. Deshalb ist die Höhe so lang wie die halbe Basis.", "m": "\\begin{aligned}\\s{C_3M_3} &= \\s{M_3A_3} = 2\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Fläche: halbe Basis · Höhe.", "m": "\\begin{aligned}A &= \\tfrac12\\cdot 4\\cdot 2\\,\\mathrm{FE} = \\erg{4\\,\\mathrm{FE}}\\end{aligned}"}]}, {"label": "B 3.5", "pts": "3", "text": "<p>Die Dreiecke A<sub>5</sub>B<sub>5</sub>C<sub>5</sub> und A<sub>6</sub>B<sub>6</sub>C<sub>6</sub> sind gleichseitig.</p><p>Berechne die zugehörigen Werte für x.</p>", "img": null, "sol": [{"t": "Höhe im gleichseitigen Dreieck mit Seite a = 4: \\(h=\\frac a2\\sqrt3\\).", "m": "\\begin{aligned}\\s{C_5M_5} &= \\dfrac{4}{2}\\sqrt3\\,\\mathrm{LE} = 2\\sqrt3\\,\\mathrm{LE}\\end{aligned}"}, {"t": "Gleichsetzen und lösen:", "m": "\\begin{aligned}-0{,}4x^2+1{,}35x+4{,}5 &= 2\\sqrt3\\\\[3pt]-0{,}4x^2+1{,}35x+1{,}04 &= 0\\\\[3pt]x_{1,2} &= \\dfrac{-1{,}35\\pm\\sqrt{1{,}35^2+4\\cdot 0{,}4\\cdot 1{,}04}}{2\\cdot(-0{,}4)}\\\\[3pt]&\\erg{x=-0{,}64\\;\\vee\\;x=4{,}02}\\end{aligned}"}]}, {"label": "B 3.6", "pts": "1", "text": "<p>Für das Dreieck A<sub>7</sub>B<sub>7</sub>C<sub>7</sub> gilt: A<sub>7</sub>(0 | 0).</p><p>Gib die Koordinaten des Punktes C<sub>7</sub> an.</p>", "img": null, "sol": [{"t": "\\(A_7\\) liegt 2 LE links von \\(M_7\\) auf gleicher Höhe. Also gilt \\(M_7(2|0)\\). Probe: \\(0{,}25\\cdot 2-0{,}5=0\\) ✓. Damit ist x = 2.", "m": null}, {"t": "\\(C_7\\) liegt auf p über \\(M_7\\):", "m": "\\begin{aligned}y &= -0{,}4\\cdot 2^2+1{,}6\\cdot 2+4 = 5{,}6\\\\[3pt]&\\erg{C_7(2\\,|\\,5{,}6)}\\end{aligned}"}]}]}]}, {"id": "za", "name": "Daten und Zufall", "short": "10.5", "tasks": [{"id": "za1", "year": 2023, "term": "Haupttermin", "nr": "A 3", "notr": true, "pts": "5,5", "intro": "<p>Die Tasten C, D, E, G und A eines Klaviers können mithilfe einer Software angeschlagen werden. Dabei werden Melodien erzeugt, indem vier Tasten zufällig nacheinander angeschlagen werden.</p><p>Beispiel für eine solche Melodie: A – C – D – C</p>", "fig": "z01", "figw": 5.4, "bigfig": false, "subs": [{"label": "A 3.1", "pts": "1,5", "text": "<p>Zeige rechnerisch, dass 625 verschiedene Melodien erzeugt werden können.</p>", "img": null, "sol": [{"t": "Für jeden der vier Anschläge gibt es 5 Tasten zur Auswahl (Wiederholung erlaubt). Zählprinzip: multiplizieren.", "m": "\\begin{aligned}5\\cdot 5\\cdot 5\\cdot 5 &= \\erg{625}\\end{aligned}"}]}, {"label": "A 3.2", "pts": "1", "text": "<p>Gib die Wahrscheinlichkeit dafür an, dass die Melodie A – C – D – C entsteht.</p>", "img": null, "sol": [{"t": "Genau eine der 625 gleich wahrscheinlichen Melodien ist günstig.", "m": "\\begin{aligned}P &= \\erg{\\dfrac{1}{625}}\\end{aligned}"}]}, {"label": "A 3.3", "pts": "1", "text": "<p>Gib die Wahrscheinlichkeit dafür an, dass eine Melodie entsteht, bei der viermal dieselbe Taste angeschlagen wird.</p>", "img": null, "sol": [{"t": "Günstig sind CCCC, DDDD, EEEE, GGGG, AAAA, also 5 Melodien.", "m": "\\begin{aligned}P &= \\erg{\\dfrac{5}{625}}\\end{aligned}"}]}, {"label": "A 3.4", "pts": "2", "text": "<p>Für eine bestimmte Melodie werden folgende Vorgaben in der Software eingestellt: Als erstes wird die Taste C und als zweites die Taste A angeschlagen. Zudem soll jede Taste höchstens einmal angeschlagen werden.</p><p>Ergänze im Baumdiagramm die zugehörigen Tasten.</p>", "img": "z01t", "sol": [{"t": "C und A sind schon verbraucht. Für den 3. Ton bleiben D, E, G. Für den 4. Ton bleiben jeweils die zwei anderen übrig.", "m": null}], "solimg": "za_sol_01", "solcap": "Baumdiagramm aus dem Lösungsmuster"}]}, {"id": "za2", "year": 2023, "term": "Nachtermin", "nr": "A 4", "notr": true, "pts": "3", "intro": "<p>Für ein Spiel sind Tierbilder in drei Teile zerschnitten worden und können nun entweder wieder zu den ursprünglichen Tieren oder zu Fantasietieren zusammengesetzt werden. Die zusammengesetzten Bilder sind immer in die Bereiche Kopf, Rumpf und Beine unterteilt (vgl. Abbildung).</p><p>Im Spiel gibt es folgende Tiere: Kuh, Hase, Löwe, Gans und Tiger.</p>", "fig": "z02", "figw": 6.2, "bigfig": false, "subs": [{"label": "A 4.1", "pts": "1", "text": "<p>Zeige rechnerisch, dass 125 verschiedene Tierbilder erzeugt werden können.</p>", "img": null, "sol": [{"t": "Kopf, Rumpf und Beine können je von einem der 5 Tiere stammen.", "m": "\\begin{aligned}5\\cdot 5\\cdot 5 &= \\erg{125}\\end{aligned}"}]}, {"label": "A 4.2", "pts": "1", "text": "<p>Gib die Wahrscheinlichkeit dafür an, dass man bei einer zufällig ausgewählten Kombination ein Fantasietier erhält.</p>", "img": null, "sol": [{"t": "Nur 5 der 125 Bilder sind ursprüngliche Tiere (alle drei Teile vom selben Tier). Der Rest sind Fantasietiere.", "m": "\\begin{aligned}P &= \\dfrac{125-5}{125} = \\erg{\\dfrac{120}{125}}\\end{aligned}"}]}, {"label": "A 4.3", "pts": "1", "text": "<p>Kreuze die Wahrscheinlichkeit dafür an, dass bei einer zufällig ausgewählten Kombination ein Bild entsteht, das nur aus Raubtier-Teilen besteht.</p><p class=\"opt\"><img class=\"inl\" src=\"img/zopt.png\" alt=\"\"></p>", "img": null, "sol": [{"t": "Raubtiere sind Löwe und Tiger. Für jeden der drei Bereiche gibt es also 2 Möglichkeiten.", "m": "\\begin{aligned}P &= \\dfrac{2\\cdot 2\\cdot 2}{125} = \\erg{\\dfrac{8}{125}}\\end{aligned}"}]}]}, {"id": "za3", "year": 2023, "term": "Nachtermin", "nr": "B 1", "notr": false, "pts": "5", "intro": "<p>In einem Supermarkt werden regionale („R“) und nichtregionale („nR“) Produkte angeboten. Dabei beträgt der Anteil der regionalen Produkte p % (p ∈ IR<sup>+</sup>).</p><p>Alle Produkte sind entweder biologisch („B“) oder nichtbiologisch („nB“) erzeugt. 20 % der regionalen Produkte des Supermarkts sind biologisch erzeugt. Bei den nichtregionalen Produkten sind dies nur 5 %.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 1.1", "pts": "2,5", "text": "<p>Zeichne ein zugehöriges Baumdiagramm, in dem alle prozentualen Anteile ersichtlich sind.</p>", "img": null, "sol": [{"t": "Erste Stufe: regional (p %) oder nicht regional (100 % − p %). Zweite Stufe: biologisch oder nicht, mit 20 %/80 % bzw. 5 %/95 %. Die Wahrscheinlichkeiten an jedem Knoten ergeben zusammen 100 %.", "m": null}], "solimg": "za_sol_03", "solcap": "Baumdiagramm aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "1,5", "text": "<p>In diesem Supermarkt findet eine Warenkontrolle statt. Bei der zufälligen Auswahl eines Produktes erhält man mit einer Wahrscheinlichkeit von 6 % ein regionales, biologisch erzeugtes Produkt.</p><p>Berechne den Anteil p % aller regionalen Produkte dieses Supermarkts in Prozent.</p>", "img": null, "sol": [{"t": "Pfadregel: Entlang des Pfades R → B multiplizieren und gleich 6 % setzen.", "m": "\\begin{aligned}0{,}06 &= \\dfrac{p}{100}\\cdot 0{,}2\\\\[3pt]p &= \\dfrac{0{,}06}{0{,}2}\\cdot 100 = \\erg{30}\\\\[3pt]&\\text{Anteil regionaler Produkte: }30\\,\\%\\end{aligned}"}]}, {"label": "B 1.3", "pts": "1", "text": "<p>Dieser Supermarkt bietet insgesamt 15 000 Produkte an.</p><p>Berechne die Anzahl der regionalen, biologisch erzeugten Produkte.</p>", "img": null, "sol": [{"t": "6 % aller 15 000 Produkte sind regional und biologisch.", "m": "\\begin{aligned}0{,}06\\cdot 15\\,000 &= \\erg{900}\\end{aligned}"}]}]}, {"id": "za4", "year": 2024, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "6,5", "intro": "<p>Manchmal werden zu Fasching Krapfen zum Spaß mit Senf gefüllt. Von zwölf Krapfen sind zwei mit Senf („S“) und zehn mit Marmelade („M“) gefüllt.</p><p>Martin nimmt sich von den zwölf Krapfen zwei zufällig ausgewählte.</p>", "fig": "z04", "figw": 4.4, "bigfig": false, "subs": [{"label": "B 1.1", "pts": "2,5", "text": "<p>Zeichne ein zugehöriges Baumdiagramm, in dem alle Anteile ersichtlich sind.</p>", "img": null, "sol": [{"t": "Ziehen ohne Zurücklegen: Auf der ersten Stufe sind es 2 von 12 (S) bzw. 10 von 12 (M). Auf der zweiten Stufe sind noch 11 Krapfen da, und es fehlt einer der zuerst gezogenen Sorte.", "m": null}], "solimg": "za_sol_04", "solcap": "Baumdiagramm aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "<p>Berechne die Wahrscheinlichkeit P dafür, dass mindestens einer der beiden ausgewählten Krapfen mit Senf gefüllt ist.</p><p class=\"hint\">[Ergebnis: <img class=\"inl\" src=\"img/p722.png\" alt=\"\">]</p>", "img": null, "sol": [{"t": "„Mindestens einer mit Senf“ sind die Pfade SS, SM und MS. Pfadregel (multiplizieren) und Summenregel (addieren):", "m": "\\begin{aligned}P &= \\dfrac{2}{12}\\cdot\\dfrac{1}{11}+\\dfrac{2}{12}\\cdot\\dfrac{10}{11}+\\dfrac{10}{12}\\cdot\\dfrac{2}{11}\\\\[3pt]P &= \\dfrac{2+20+20}{132} = \\erg{\\dfrac{7}{22}}\\end{aligned}"}]}, {"label": "B 1.3", "pts": "2", "text": "<p>Martin vermutet, dass mit einer Wahrscheinlichkeit von mehr als 70 % keiner der beiden ausgewählten Krapfen mit Senf gefüllt ist.</p><p>Beurteile diese Vermutung.</p>", "img": null, "sol": [{"t": "„Keiner mit Senf“ ist das Gegenereignis von „mindestens einer mit Senf“.", "m": "\\begin{aligned}P(\\text{MM}) &= 1-\\dfrac{7}{22} = \\dfrac{15}{22}\\approx 68\\,\\%\\end{aligned}"}, {"t": "68 % < 70 %, also stimmt Martins Vermutung nicht.", "m": "\\begin{aligned}&\\erg{\\text{Vermutung ist falsch}}\\end{aligned}"}]}]}, {"id": "za5", "year": 2024, "term": "Nachtermin", "nr": "A 1", "notr": true, "pts": "4", "intro": "<p>In einem Säckchen befinden sich sechs Kugeln gleicher Art. Drei Kugeln sind als Niete („N“), eine Kugel ist als Joker („J“) und zwei Kugeln sind als Gewinn („G“) gekennzeichnet. Man zieht zufällig eine Kugel. Beim Joker darf man ein zweites Mal ziehen. Ansonsten darf man keine weitere Kugel ziehen. Es werden keine Kugeln zurück ins Säckchen gelegt.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 1.1", "pts": "2", "text": "<p>Zeichne ein zugehöriges Baumdiagramm, in dem alle Anteile ersichtlich sind.</p>", "img": null, "sol": [{"t": "Erste Stufe mit 6 Kugeln: N mit 3/6, J mit 1/6, G mit 2/6. Nur nach dem Joker geht es weiter. Dann sind noch 5 Kugeln da: N mit 3/5, G mit 2/5.", "m": null}], "solimg": "za_sol_05", "solcap": "Baumdiagramm aus dem Lösungsmuster"}, {"label": "A 1.2", "pts": "2", "text": "<p>Berechne die Wahrscheinlichkeit dafür, dass man am Ende eine als Gewinn gekennzeichnete Kugel gezogen hat.</p>", "img": null, "sol": [{"t": "Gewinn am Ende über zwei Pfade: sofort G, oder erst J und dann G.", "m": "\\begin{aligned}P &= \\dfrac{2}{6}+\\dfrac{1}{6}\\cdot\\dfrac{2}{5}\\\\[3pt]P &= \\dfrac{10}{30}+\\dfrac{2}{30} = \\erg{\\dfrac{12}{30}}\\end{aligned}"}]}]}, {"id": "za6", "year": 2024, "term": "Nachtermin", "nr": "B 2", "notr": false, "pts": "4,5", "intro": "<p>Eine zehnte Klasse hat für ihren Abschluss rote („r“) und schwarze („s“) T-Shirts bestellt. Die T-Shirts gibt es ohne Namensaufdruck („oN“) oder mit Namensaufdruck („mN“).</p><p>In der Lieferung beträgt der Anteil der roten T-Shirts p % (p ∈ IR<sup>+</sup>).</p><p>Von den roten T-Shirts wurden 24 % ohne Namensaufdruck geliefert. Bei den schwarzen T-Shirts ist dieser Anteil doppelt so groß.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 2.1", "pts": "1,5", "text": "<p>Ergänze im Baumdiagramm die zugehörigen Anteile.</p>", "img": "z06", "sol": [{"t": "Erste Stufe: rot p %, schwarz (100 − p) %. Bei rot: oN 24 %, mN 76 %. Bei schwarz ist der oN-Anteil doppelt so groß: 48 %, also mN 52 %.", "m": null}], "solimg": "za_sol_06", "solcap": "Baumdiagramm aus dem Lösungsmuster"}, {"label": "B 2.2", "pts": "1", "text": "<p>Der Anteil der roten T-Shirts ohne Namensaufdruck liegt bei 18 %.</p><p>Zeige, dass der Anteil p % der roten T-Shirts 75 % beträgt.</p>", "img": null, "sol": [{"t": "Pfad r → oN multiplizieren und gleich 18 % setzen.", "m": "\\begin{aligned}\\dfrac{p}{100}\\cdot\\dfrac{24}{100} &= \\dfrac{18}{100}\\\\[3pt]p &= \\dfrac{18}{24}\\cdot 100 = \\erg{75}\\end{aligned}"}]}, {"label": "B 2.3", "pts": "2", "text": "<p>Sissi öffnet das gelieferte Paket und nimmt ein zufällig ausgewähltes T-Shirt heraus.</p><p>Berechne die Wahrscheinlichkeit dafür, dass es ein T-Shirt mit Namensaufdruck ist.</p>", "img": null, "sol": [{"t": "Mit Namensaufdruck über die Pfade r → mN und s → mN.", "m": "\\begin{aligned}P &= \\dfrac{75}{100}\\cdot\\dfrac{76}{100}+\\dfrac{25}{100}\\cdot\\dfrac{52}{100}\\\\[3pt]P &= 0{,}57+0{,}13 = \\erg{0{,}7}\\end{aligned}"}]}]}, {"id": "za7", "year": 2025, "term": "Haupttermin", "nr": "A 1", "notr": true, "pts": "3", "intro": "<p>An einer Realschule wählen die Mädchen („M“) und Jungen („J“) der Jahrgangsstufe 6 ihre Wahlpflichtfächergruppe. Einige der Kinder entscheiden sich für die Wahlpflichtfächergruppe III a („IIIa“), alle anderen entscheiden sich nicht für die Wahlpflichtfächergruppe III a („nIIIa“). Das Baumdiagramm zeigt die jeweiligen Anteile.</p>", "fig": "z07", "figw": null, "bigfig": true, "subs": [{"label": "A 1.1", "pts": "2", "text": "<p>Für die Schülerzeitung wird ein zufällig ausgewähltes Kind der Jahrgangsstufe 6 zu seiner Wahl befragt.</p><p>Bestätige rechnerisch: Es ist mit einer Wahrscheinlichkeit von 26 % ein Kind ausgewählt worden, das sich für die Wahlpflichtfächergruppe III a entschieden hat.</p>", "img": null, "sol": [{"t": "Die Pfade M → IIIa und J → IIIa addieren.", "m": "\\begin{aligned}P &= \\dfrac{60}{100}\\cdot\\dfrac{30}{100}+\\dfrac{40}{100}\\cdot\\dfrac{20}{100}\\\\[3pt]P &= \\dfrac{18}{100}+\\dfrac{8}{100} = \\erg{\\dfrac{26}{100}=26\\,\\%}\\end{aligned}"}]}, {"label": "A 1.2", "pts": "1", "text": "<p>An dieser Schule besuchen 150 Kinder die Jahrgangsstufe 6.</p><p>Gib an, wie viele dieser Kinder sich für die Wahlpflichtfächergruppe III a entschieden haben.</p>", "img": null, "sol": [{"t": "26 % von 150 Kindern:", "m": "\\begin{aligned}0{,}26\\cdot 150 &= \\erg{39}\\end{aligned}"}]}]}, {"id": "za8", "year": 2025, "term": "Haupttermin", "nr": "B 1", "notr": false, "pts": "5", "intro": "<p>In einer Schale liegen 20 Schokoladenkugeln, die sich nur durch die Füllungen unterscheiden. Sechs Kugeln sind mit Nougat („N“), fünf mit Krokant („K“) und die anderen mit Marzipan („M“) gefüllt.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "B 1.1", "pts": "2", "text": "<p>Wilma hat sich zwei zufällig ausgewählte Kugeln genommen und isst sie.</p><p>Vervollständige das dazugehörige Baumdiagramm.</p>", "img": "z08", "sol": [{"t": "Erste Stufe: N 6/20, K 5/20, M 9/20. Auf der zweiten Stufe sind noch 19 Kugeln da, und von der zuerst gezogenen Sorte fehlt eine (z. B. nach N: N 5/19, K 5/19, M 9/19).", "m": null}], "solimg": "za_sol_08", "solcap": "Baumdiagramm aus dem Lösungsmuster"}, {"label": "B 1.2", "pts": "2", "text": "<p>Wilma mag kein Marzipan.</p><p>Berechne die Wahrscheinlichkeit dafür, dass Wilma keine Kugel mit Marzipanfüllung gegessen hat.</p>", "img": null, "sol": [{"t": "Kein Marzipan heißt: beide Kugeln N oder K. Pfade NN, NK, KN, KK addieren.", "m": "\\begin{aligned}P &= \\dfrac{6}{20}\\cdot\\dfrac{5}{19}+\\dfrac{6}{20}\\cdot\\dfrac{5}{19}+\\dfrac{5}{20}\\cdot\\dfrac{6}{19}+\\dfrac{5}{20}\\cdot\\dfrac{4}{19}\\\\[3pt]P &= \\dfrac{30+30+30+20}{380} = \\dfrac{110}{380} = \\erg{\\dfrac{11}{38}}\\end{aligned}"}]}, {"label": "B 1.3", "pts": "1", "text": "<p>Wilma hatte Glück, weil in ihren beiden Kugeln kein Marzipan war.</p><p>Jetzt nimmt ihr Bruder Fred eine ebenfalls zufällig ausgewählte Kugel aus der Schale.</p><p>Gib die Wahrscheinlichkeit dafür an, dass diese Kugel mit Marzipan gefüllt ist.</p>", "img": null, "sol": [{"t": "Wilma hat zwei Kugeln ohne Marzipan gegessen. In der Schale sind noch 18 Kugeln, davon alle 9 mit Marzipan.", "m": "\\begin{aligned}P &= \\erg{\\dfrac{9}{18}}\\end{aligned}"}]}]}, {"id": "za9", "year": 2025, "term": "Nachtermin", "nr": "A 1", "notr": true, "pts": "4,5", "intro": "<p>In einer Studie sollte für das Medikament A („A“) und das Medikament B („B“) geprüft werden, ob sie wirksam („w“) oder nicht wirksam („nw“) sind. Von den Personen, die an der Studie teilnahmen, bekamen 40 % das Medikament A und die anderen das Medikament B verabreicht. Bei 68 % der Personen, die das Medikament B einnahmen, war dieses wirksam. Betrachtet man die Personen, die das Medikament A einnahmen, so war es bei p % (p ∈ IR<sup>+</sup>) wirksam.</p>", "fig": null, "figw": null, "bigfig": false, "subs": [{"label": "A 1.1", "pts": "2,5", "text": "<p>Zeichne ein zugehöriges Baumdiagramm, in dem alle prozentualen Anteile ersichtlich sind.</p>", "img": null, "sol": [{"t": "Erste Stufe: A 40 %, B 60 %. Bei A: wirksam p %, nicht wirksam (100 − p) %. Bei B: wirksam 68 %, nicht wirksam 32 %.", "m": null}], "solimg": "za_sol_09", "solcap": "Baumdiagramm aus dem Lösungsmuster"}, {"label": "A 1.2", "pts": "2", "text": "<p>Von allen Personen, die an der Studie teilnahmen, wird eine Person zufällig ausgewählt. Dabei erhält man mit einer Wahrscheinlichkeit von 30 % eine Person, die das Medikament A einnahm und bei der dieses zugleich wirksam war.</p><p>Berechne den Wert von p.</p>", "img": null, "sol": [{"t": "Pfad A → w gleich 30 % setzen.", "m": "\\begin{aligned}\\dfrac{40}{100}\\cdot\\dfrac{p}{100} &= \\dfrac{30}{100}\\\\[3pt]p &= \\dfrac{30}{40}\\cdot 100 = \\erg{75}\\end{aligned}"}]}]}, {"id": "za10", "year": 2025, "term": "Nachtermin", "nr": "A 2", "notr": true, "pts": "3", "intro": "<p>Das folgende Baumdiagramm zeigt einen Zufallsversuch zum Ziehen von Losen mit den entsprechenden Wahrscheinlichkeiten.</p>", "fig": "z10", "figw": null, "bigfig": true, "subs": [{"label": "A 2.1", "pts": "2", "text": "<p>Beschreibe einen Zufallsversuch, der zum Baumdiagramm passt.</p>", "img": null, "sol": [{"t": "Lies aus den Brüchen ab: Erst sind 11 Lose da (5 Gewinne, 1 Freilos, 5 Nieten). Nach dem Freilos sind es noch 10 (5 Gewinne, 5 Nieten). Es wird also ohne Zurücklegen gezogen.", "m": null}, {"t": "Ein passender Versuch: In einem Gefäß liegen 5 Gewinnlose, 1 Freilos und 5 Nieten. Man zieht ein Los. Bei einem Freilos zieht man noch ein weiteres Los.", "m": null}]}, {"label": "A 2.2", "pts": "1", "text": "<p>Gib die Wahrscheinlichkeit dafür an, dass man beim Durchführen des Zufallsversuchs sofort einen Gewinn oder zuerst ein Freilos und dann einen Gewinn erhält.</p>", "img": null, "sol": [{"t": "Die beiden Pfade addieren:", "m": "\\begin{aligned}P &= \\dfrac{5}{11}+\\dfrac{1}{11}\\cdot\\dfrac{5}{10} = \\dfrac{10}{22}+\\dfrac{1}{22} = \\dfrac{11}{22} = \\erg{\\dfrac12}\\end{aligned}"}]}]}]}];
window.AP_IMG={"tr_a09_0": [1300, 762], "f07": [623, 561], "n_2020nt_B2_0": [1451, 1776], "f12": [461, 509], "f06": [570, 537], "tr_a04_0": [1300, 585], "n_2020nt_B1_0": [1451, 1179], "ns_2019nt_B2_B22": [910, 487], "f08": [853, 987], "ns_2021ht_B1_B11": [799, 769], "q12k": [699, 897], "vec": [524, 216], "ns_2021ht_A2_A22": [813, 754], "ns_2020ht_A1_A11": [303, 261], "n_2019ht_A2_0": [1451, 1405], "rg_sol_06": [938, 868], "f02": [364, 479], "z08": [1100, 632], "ns_2018nt_B1_B11": [910, 1040], "qu_sol_07": [1000, 955], "z10": [1100, 440], "rg_sol_02": [838, 1189], "qu_sol_02": [1000, 1155], "n_2021ht_A2_1": [1451, 744], "n_2021nt_A3_0": [1451, 824], "ns_2018ht_A1_A11": [461, 473], "n_2021nt_B1_0": [1451, 1219], "tr_sol_d08": [1000, 780], "tr_a07_0": [1300, 1221], "qu_sol_14": [1000, 846], "n_2019nt_B1_0": [1451, 1626], "ns_2018nt_B2_B21": [792, 877], "tr_sol_d06": [983, 914], "qu_sol_16": [883, 962], "ns_2019ht_B1_B11": [809, 688], "n_2019ht_A2_1": [1451, 453], "n_2020nt_A2_0": [1451, 1374], "q09": [1100, 491], "n_2018nt_B2_0": [1451, 1733], "n_2020nt_A1_0": [1451, 638], "n_2019nt_A1_0": [1451, 476], "ns_2020ht_B2_B21": [823, 575], "ns_2020nt_B1_B11": [832, 567], "ns_2018nt_A1_A11": [655, 398], "p722": [261, 126], "n_2020nt_A3_0": [1451, 1031], "f03": [664, 467], "n_2020ht_B2_0": [1451, 1005], "f05": [432, 776], "ex_sol_01": [777, 678], "tr_a06_0": [1300, 872], "n_2020ht_B1_0": [1451, 1689], "tr_sol_d04": [697, 398], "n_2019ht_A1_0": [1451, 893], "n_2021nt_A2_0": [1451, 1320], "z04": [475, 423], "n_2019nt_A2_0": [1451, 1558], "ns_2020ht_A2_A23": [592, 698], "zopt": [2157, 129], "n_2021ht_A3_0": [1451, 650], "n_2019nt_B2_0": [1451, 1095], "za_sol_04": [1000, 399], "ns_2019nt_A2_A22": [875, 665], "za_sol_01": [1000, 422], "tr_a02_0": [1300, 1306], "za_sol_05": [1000, 410], "n_2018nt_B1_0": [1451, 1778], "n_2019nt_A2_1": [1451, 322], "n_2018ht_A2_0": [1451, 1018], "tr_a10_0": [1300, 471], "z02": [970, 565], "n_2018nt_A1_0": [1451, 1071], "za_sol_06": [1000, 407], "tr_sol_d05": [936, 821], "rg_sol_07": [1000, 899], "ns_2018ht_B2_B21": [828, 926], "rg_sol_04": [1000, 838], "f14": [627, 449], "n_2020ht_A3_0": [1451, 690], "q01": [585, 395], "ns_2020ht_B1_B11": [964, 787], "n_2019nt_A3_0": [1451, 1146], "ns_2020nt_B2_B21": [946, 1028], "n_2018ht_A3_0": [1451, 770], "tr_a01_1": [1300, 210], "n_2018ht_B1_0": [1451, 1531], "f01": [506, 660], "ns_2019ht_B2_B21": [993, 851], "f04": [487, 419], "tr_a03_0": [1300, 461], "n_2019ht_B2_0": [1451, 1803], "q03": [808, 477], "tr_a08_0": [1300, 690], "n_2020ht_A1_0": [1451, 1338], "tr_a01_0": [1300, 1067], "tr_a01_2": [1300, 136], "qu_sol_04": [1000, 859], "z01t": [1100, 431], "za_sol_08": [1000, 580], "n_2021ht_B2_0": [1451, 1802], "n_2020nt_A2_1": [1451, 366], "f11": [291, 533], "ns_2020nt_A2_A22": [723, 627], "rg_sol_14": [937, 664], "qu_sol_06": [1000, 716], "n_2018ht_A2_1": [1451, 264], "ns_2018ht_B1_B11": [780, 1021], "n_2019ht_B1_0": [1451, 981], "q01k": [910, 754], "f09": [403, 642], "f10b": [1100, 319], "za_sol_09": [1000, 407], "n_2021nt_A2_1": [1451, 559], "q14k": [1100, 932], "ns_2018nt_A2_A21": [751, 528], "qu_sol_11": [883, 1123], "rg_sol_12": [868, 984], "n_2018ht_A1_0": [1451, 1254], "q10": [897, 973], "z01": [550, 252], "n_2018ht_B2_0": [1451, 1727], "z07": [1100, 380], "rg_sol_13": [1000, 903], "f10": [474, 928], "ns_2019ht_A2_A21": [733, 756], "n_2021nt_B2_0": [1451, 1799], "tr_a05_0": [1300, 884], "f13": [499, 460], "ns_2021ht_B2_B21": [799, 899], "tr_sol_d01": [851, 720], "n_2018nt_A3_0": [1451, 957], "n_2019ht_A3_0": [1451, 793], "n_2021ht_B1_0": [1451, 1391], "n_2021nt_A1_0": [1451, 643], "za_sol_03": [1000, 406], "ns_2019nt_B1_B11": [896, 822], "n_2020ht_A2_0": [1451, 1512], "n_2018nt_A2_0": [1451, 1214], "ns_2018ht_A2_A21": [614, 627], "tr_sol_d10": [695, 454], "q07k": [896, 1342], "n_2021ht_A2_0": [1451, 1161], "qu_sol_01": [1000, 550], "n_2020ht_A2_1": [1451, 378], "z06": [1100, 484], "tr_sol_d07": [853, 524], "e01": [961, 838], "qu_sol_12": [1000, 647]};
